  ('cpiuris2025::56412822990ead8ac68daeffe0f30a16', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência da autoridade judiciária brasileira', '## Competência da autoridade judiciária brasileira

A autoridade judiciária brasileira tem competência para processar e julgar ações em que as partes se submetem à jurisdição nacional, além de hipóteses de competência absoluta do juízo brasileiro.

### Conceitos
- **Competência da autoridade judiciária**: A capacidade do juiz de processar e julgar uma ação
- **Jurisdição nacional**: O direito das partes se submeterem à jurisdição do país
- **Competência absoluta**: Hipóteses em que o juiz tem competência sem necessidade de eleição do foro

### Referências legais
- Art. 22 da Lei nº 9.099/1995
- Art. 23 do CPC

### Dicas de prova
- Entenda a diferença entre competência relativa e absoluta
- Conheça as hipóteses de competência absoluta previdas no artigo 23 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.366 (2)", "page_number": 366, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 da Lei nº 9.099/1995", "Art. 23 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T03:55:29.750817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=366", "doc_key": "56412822990ead8ac68daeffe0f30a16"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bfbf5fb7a1aecb2a9deea65853ab274c631e76489c3143ee10a847ce74bf1d69'),
  ('cpiuris2025::e09f964f0d1a18660d0866240bb421c1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eleição de Foro Estrangeiro e Conexão Locus Regit Actum', '## Eleição de Foro Estrangeiro e Conexão Locus Regit Actum

A eleição de foro estrangeiro é válida exceto quando a lide envolver interesses públicos. O lugar de constituição da obrigação (locus regit actum) implica na aplicação do ordenamento do local onde a obrigação foi contraída.

### Conceitos
- **Eleição de Foro Estrangeiro**: Válida exceto quando a lide envolver interesses públicos
- **Locus Regit Actum**: Aplicação do ordenamento do local onde a obrigação foi contraída
- **Lex Fori**: Aplicação das normas vigentes no lugar do foro
- **Conexão Lugar de Constituição da Obrigação**: Aplicação do ordenamento do local onde a obrigação foi contraída

### Referências legais
- Art. 9º da LINDB
- Art. 11 da LINDB
- Art. 784 do CPC

### Jurisprudência
- REsp 242383/SP
- Súmula N STF

### Dicas de prova
- Entenda a conexão locus regit actum e lex loci contractus
- Conheça as regras de aplicação das normas vigentes no lugar do foro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.367", "page_number": 367, "discipline": "Direitos Internacional", "legal_refs": ["Art. 9º da LINDB", "Art. 11 da LINDB", "Art. 784 do CPC"], "jurisprudence": ["REsp 242383/SP", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T03:56:12.027546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=367", "doc_key": "e09f964f0d1a18660d0866240bb421c1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '230cf8641954a8d9de8f070ec9356c28e469f8c87a8dc2df68b4247c93ad1a01'),
  ('cpiuris2025::e2373f9c5d97024930b1e3b376605e6f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação da Lex Fori no Direito Internacional Privado', '## Aplicação da Lex Fori no Direito Internacional Privado

A aplicação da lex fori é a aplicação das normas vigentes na legislação interna. O critério incide quando o Direito estrangeiro não puder ser aplicado por violação da ordem pública ou não for verificável.

### Conceitos
- **Lex Fori**: Aplicação das normas vigentes na legislação interna
- **Ordem Pública**: Assegura a soberania nacional, a ordem jurídica e os bons costumes

### Referências legais
- Art. 17 da LINDB

### Dicas de prova
- Entenda a noção de Lex Fori e sua aplicação no Direito Internacional Privado
- Conheça a ordem pública e suas implicações na resolução de conflitos de leis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.368", "page_number": 368, "discipline": "Direitos Internacional", "legal_refs": ["Art. 17 da LINDB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T03:57:10.807055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=368", "doc_key": "e2373f9c5d97024930b1e3b376605e6f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8f5c78b1dff8aca89ad5ca390aff3ffcdc98256ae1330a632b01c3bbaced5566'),
  ('cpiuris2025::62fd79deaa021ef66ec2c035c2903d41', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas negativas e positivas de ordem pública', '## Reservas negativas e positivas de ordem pública

A aplicação da lei estrangeira é rejeitada se violar a ordem pública, mas a lex fori é aplicada mesmo quando os pressupostos estão cumpridos.

### Conceitos
- **Lex fori**: a lei do país onde o caso está sendo julgado
- **Ordem pública**: a ordem internacional e internacional de direitos humanos
- **Reserva negativa**: aplicação da lex fori mesmo quando a lei estrangeira viola a ordem pública
- **Reserva positiva**: exclusão imediata da aplicação da lei estrangeira devido à sua incompatibilidade com a ordem pública
- **Qualificação**: afirmação ou delimitação do objeto de conexão e elemento de conexão

### Referências legais
- Art. 8º da LINDB
- Art. 9º da LINDB

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre reservas negativas e positivas de ordem pública.
- Conheça as teorias sobre qualificação: lex fori, lex causae e referência a conceitos autônomos e universais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.369", "page_number": 369, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8º da LINDB", "Art. 9º da LINDB"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T03:57:51.442929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=369", "doc_key": "62fd79deaa021ef66ec2c035c2903d41"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b4eeb50ef64fa9f450c00a618a3fce2c5ec7a0c80d0a168b00e13a7a2ac2e6f0'),
  ('cpiuris2025::448a90b3a007cc0f4015616abe7565b3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflito de leis e reenvio', '## Conflito de leis e reenvio

O conflito de leis pode ser positivo ou negativo. No caso de conflito negativo, ambos os ordenamentos indicam a lei estrangeira para resolver o conflito. O reenvio ocorre na hipótese de conflitos de 2º grau negativos, quando um Estado faz o reenvio a outro, e pode ocorrer em vários graus.

### Conceitos
- **Conflito positivo**: A aplicação dos dois sistemas para solucionar um determinado conflito
- **Conflito negativo**: Ambos os ordenamentos indicam a lei estrangeira para resolver o conflito
- **Reenvio**: O retorno, remissão, devolução, opção, renvoi ou remission de um caso para outro Estado

### Referências legais
- Art. 16 da LINDB
- Art. 5º, XXXI, da Constituição
- Art. 10, § 1º da LINDB

### Jurisprudência
- DOLINGER e TIBURCIO, 2020
- Paulo Henrique Gonçalves Portela

### Dicas de prova
- Entenda a diferença entre conflito positivo e negativo
- Conheça o conceito de reenvio e seus graus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.370 (1)", "page_number": 370, "discipline": "Direitos Internacional", "legal_refs": ["Art. 16 da LINDB", "Art. 5º, XXXI, da Constituição", "Art. 10, § 1º da LINDB"], "jurisprudence": ["DOLINGER e TIBURCIO, 2020", "Paulo Henrique Gonçalves Portela"], "confidence": 0.8, "extracted_at": "2026-05-31T03:58:43.026543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=370", "doc_key": "448a90b3a007cc0f4015616abe7565b3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4e891d5c4e1e816a191eb0277745a30519e8a783cfb5dac15377b9e180a50284'),
  ('cpiuris2025::10f877bb973803db23b24d95e08c04aa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento e Proteção de Direitos Privados no Estrangeiro', '## Reconhecimento e Proteção de Direitos Privados no Estrangeiro

O reconhecimento de direitos privados estrangeiros é um conceito que se refere à proteção dos direitos adquiridos por uma pessoa em outro Estado, respeitando a soberania do Estado de destino.

### Conceitos
- **Reconhecimento de Direitos Privados**: Proteção dos direitos adquiridos por uma pessoa em outro Estado
- **Soberania Estatal**: Direito do Estado de determinar suas próprias leis e políticas

### Referências legais
- Art. 29 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Dicas de prova
- Distinção entre reconhecimento e proteção de direitos privados
- Importância da soberania estatal no reconhecimento de direitos estrangeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.370 (2)", "page_number": 370, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T03:58:54.078519+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=370", "doc_key": "10f877bb973803db23b24d95e08c04aa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fd741c708dce5f4ba394994b67443601d0bb168565db1a476ddfa95b9ec47608'),
  ('cpiuris2025::de4636f7f19caf010ab68bcf984dee89', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento do Direito Adquirido', '## Reconhecimento do Direito Adquirido

O direito adquirido é reconhecido desde que não prejudique a ordem pública. A Constituição e a Lei Indireta de Normas Brasileiras (LINDB) garantem o reconhecimento do direito adquirido, respeitado o ato jurídico perfeito e a coisa julgada.

### Conceitos
- **Direito Adquirido**: direito reconhecido pela lei
- **Ordem Pública**: necessidade de respeitar a ordem estabelecida pelo Estado
- **Ato Jurídico Perfeito**: atuação que não pode ser alterada ou anulada
- **Cosa Julgada**: decisão final e imutável de uma ação judicial

### Referências legais
- Art. 5º, XXXVI, da Constituição c/c art. 6º da LINDB

### Jurisprudência
- RE 123456
- DIVÓRCIO. HOMOLOGAÇÃO DE SENTENÇA ESTRANGEIRA. DENEGAÇÃO.

### Dicas de prova
- Entenda a noção de direito adquirido e sua relação com a ordem pública.
- Conheça as regras do ato jurídico perfeito e da coisa julgada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.371 (1)", "page_number": 371, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, XXXVI, da Constituição c/c art. 6º da LINDB"], "jurisprudence": ["RE 123456", "DIVÓRCIO. HOMOLOGAÇÃO DE SENTENÇA ESTRANGEIRA. DENEGAÇÃO."], "confidence": 0.8, "extracted_at": "2026-05-31T04:00:18.738704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=371", "doc_key": "de4636f7f19caf010ab68bcf984dee89"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e71f654cc84bb975d625bbda2905538bd9d867f5ec1f43f2d3cd036774092cb1'),
  ('cpiuris2025::bc1f4fbdbb7a7da443aa452cbaf39fbc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reexaminação de decisões de homologação de sentenças estrangeiras de divórcio', '## Reexaminação de decisões de homologação de sentenças estrangeiras de divórcio

O Superior Tribunal de Justiça pode reexaminar decisões de homologação de sentenças estrangeiras de divórcio, desde que o interessado peça, e a Emenda Constitucional n.º 66/10 suprimiu o prazo para a homologação.

### Conceitos
- **Reexaminação**: Ação de reavaliar uma decisão anterior
- **Homologação**: Procedimento pelo qual se confirma a validade de uma sentença estrangeira
- **Divórcio**: Dissolução do vínculo conjugal
- **Emenda Constitucional n.º 66/10**: Lei que suprimiu o prazo para a homologação de sentenças estrangeiras de divórcio

### Referências legais
- Art. 15 da Lei de Introdução às Normas do Direito Brasileiro (LINDB)
- Arts. 216-A a 216-N do Regimento Interno do STJ
- Lei nº 12.036, de 2009

### Jurisprudência
- SEC 4.445/EX, Rel. Ministro RAUL ARAÚJO, Corte Especial, julgado em 06/05/2015, DJe 17/06/2015

### Dicas de prova
- Entenda a diferença entre reexaminação e homologação de sentenças estrangeiras de divórcio
- Conheça as condições gerais estabelecidas na Lei de Introdução às Normas do Direito Brasileiro (LINDB) e no Regimento Interno do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.372 (1)", "page_number": 372, "discipline": "Direitos Internacional", "legal_refs": ["Art. 15 da Lei de Introdução às Normas do Direito Brasileiro (LINDB)", "Arts. 216-A a 216-N do Regimento Interno do STJ", "Lei nº 12.036, de 2009"], "jurisprudence": ["SEC 4.445/EX, Rel. Ministro RAUL ARAÚJO, Corte Especial, julgado em 06/05/2015, DJe 17/06/2015"], "confidence": 0.8, "extracted_at": "2026-05-31T04:01:55.190072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=372", "doc_key": "bc1f4fbdbb7a7da443aa452cbaf39fbc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a2e2c046ed61ce9da83fc52f34dcb7aabb1af628921ccbef2cd1b19ec4d16362'),
  ('cpiuris2025::5fe5f2e966a73f9995233e05f8478a6f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eficácia de Sentenças Estrangeiras no Brasil', '## Eficácia de Sentenças Estrangeiras no Brasil

A homologação de separação judicial por igual prazo produz efeito imediato, desde que as condições para a eficácia das sentenças estrangeiras sejam obedecidas.

### Conceitos
- **Homologação**: Processo pelo qual uma sentença estrangeira é reconhecida e executada no Brasil.
- **Separação Judicial**: Divisão de bens e direitos entre cônjuges, sem necessidade de divórcio.
- **Eficácia das Sentenças Estrangeiras**: Reconhecimento e execução da sentença estrangeira no Brasil.
- **Prazo de Conversão**: Período durante o qual a separação judicial pode ser convertida em divórcio.
- **Condições para Eficácia das Sentenças Estrangeiras**: Requisitos necessários para que uma sentença estrangeira seja reconhecida e executada no Brasil.
- **Regimento Interno do Supremo Tribunal Federal**: Normas internas do STF que regem o procedimento de reexame de decisões.
- **Lei nº 6.515/77**: Lei que estabeleceu as condições para a eficácia das sentenças estrangeiras no Brasil.
- **Código Civil de 2002**: Legislação brasileira que regula os direitos e deveres dos cidadãos.

### Referências legais
- Art. 7º da Lei nº 6.515/77
- Regimento Interno do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre as condições para a eficácia das sentenças estrangeiras no Brasil.
- Entenda o conceito de homologação e sua importância na execução de sentenças estrangeiras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.371 (2)", "page_number": 371, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º da Lei nº 6.515/77", "Regimento Interno do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T04:02:08.745336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=371", "doc_key": "5fe5f2e966a73f9995233e05f8478a6f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0ab7b2eff60d7fcc53e39aca4f86fbb96b9a92dee100b54196c1be96a6d22675'),
  ('cpiuris2025::7b730893c8c57942e32b115e86dc7de0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ordem Pública e Dívida de Jogo', '## Ordem Pública e Dívida de Jogo

A ordem pública é um conceito mutável que deve ser revisto conforme a evolução da sociedade. A dívida de jogo pode ser cobrada se houver equivalência entre a lei estrangeira e o direito brasileiro.

### Conceitos
- **Ordem Pública**: Conceito mutável que deve ser revisto conforme a evolução da sociedade
- **Dívida de Jogo**: Pode ser cobrada se houver equivalência entre a lei estrangeira e o direito brasileiro
- **Evolução Social**: Importante para revisar a ordem pública
- **Boa-Fé**: Princípio que regula as obrigações na ordem contemporânea
- **Enriquecimento Sem Causa**: Veda expressamente o Código Civil atual

### Referências legais
- Art. 50 da Lei de Contravenções Penais

### Jurisprudência
- REsp 1628974/SP
- Súmula N STF

### Dicas de prova
- Pegar a distinção entre ordem pública e boa-fé
- Entender a importância da evolução social na revisão da ordem pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.372 (2)", "page_number": 372, "discipline": "Direitos Internacional", "legal_refs": ["Art. 50 da Lei de Contravenções Penais"], "jurisprudence": ["REsp 1628974/SP", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T04:02:35.478831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=372", "doc_key": "7b730893c8c57942e32b115e86dc7de0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1b1ffc63c92448e583064b235f376be2056eaa7b8e30454c82e445b385c2fc3b'),
  ('cpiuris2025::bd88b4a8c02fb255a4c8c016239e25fa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Elemento de conexão no Direito Internacional Privado (DIPr)', '## Elemento de conexão no Direito Internacional Privado (DIPr)

O elemento de conexão é crucial no DIPr para determinar a aplicabilidade da lei. As opções apresentam diferentes entendimentos sobre o que deve ser considerado como elemento de conexão.

### Conceitos
- **Elemento de conexão**: Critério utilizado para determinar a aplicabilidade da lei em casos de conflito de leis
- **Lugar da conduta**: Pode ser considerado como elemento de conexão, especialmente em casos de negligência ou imprudência
- **Lei do país de celebração**: Pode ser aplicada quando a norma jurídica estipula formas alternativas de regência de atos entre vivos

### Referências legais
- Art. 8 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 342 STF

### Dicas de prova
- Entenda a distinção entre lugar da conduta e lei do país de celebração
- Avalie as implicações da norma jurídica estipulada nas formas alternativas de regência de atos entre vivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.373 (2)", "page_number": 373, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 342 STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:03:39.175089+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=373", "doc_key": "bd88b4a8c02fb255a4c8c016239e25fa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '213ec3d81dd35a00dd7311decef5caf5dd65c3e2a879f24b4e9f79a1343d6802'),
  ('cpiuris2025::5e21fcab0fecc1d1455f1dadb9e13168', 'doutrina', 'cp_iuris', 'Direitos Internacional — Regras de Conexão no Direito Internacional Privado', '## Regras de Conexão no Direito Internacional Privado

A questão discute sobre qual lei deve ser aplicada em um processo internacional envolvendo uma sociedade empresária chinesa e uma brasileira, considerando a regra de conexão brasileira. A resposta correta é a lei mais favorável ao demandante.

### Conceitos
- **Regras de Conexão**: Estabelecem qual o direito aplicável às diversas situações jurídicas conectadas a mais de um sistema legal.
- **Lei Qualificadora**: Não coincide necessariamente com a lei aplicável.
- **Reenvio**: Ocorre em dois graus: primeiro grau, quando um país nega competência à sua lei; segundo grau, quando a lei de um país manda aplicar a lei de outro.
- **Lei Mais Favorável**: A lei que é mais benéfica para o demandante em situações específicas.

### Referências legais
- Art. 98 do Código Civil
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Reenvio no Direito Internacional Privado

### Dicas de prova
- Pergunte-se se a regra de conexão é aplicável e qual lei deve ser considerada.
- Entenda o conceito de lei mais favorável ao demandante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.373 (1)", "page_number": 373, "discipline": "Direitos Internacional", "legal_refs": ["Art. 98 do Código Civil", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Reenvio no Direito Internacional Privado"], "confidence": 0.8, "extracted_at": "2026-05-31T04:03:40.644465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=373", "doc_key": "5e21fcab0fecc1d1455f1dadb9e13168"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '781af85bfeadefe62a7a1008ac3f6796373ef29c3753417542a2531da3831664'),
