- **Lei de Introdução às Normas do Direito Brasileiro**: Regulamenta a aplicação das leis estrangeiras no direito brasileiro
- **Reenvio**: Procedimento que permite a aplicação da lei estrangeira em casos de conflito de leis
- **Domicílio**: Local onde o proprietário ou interessado está residente ou tem seu domicílio

