  ('cpiuris2025::9968d66ecd5029d403c14d079a080b55', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Filhos no Direito Internacional Privado', '## Reconhecimento de Filhos no Direito Internacional Privado

A questão se refere à aplicação da lei de um país específico para reconhecer os filhos nascidos durante o matrimônio, considerando a legislação brasileira de direito internacional privado.

### Conceitos
- **Reconhecimento de Filhos**: Procedimento pelo qual se estabelece a paternidade de um filho nascido durante o matrimônio.
- **Lei da Tunísia**: A lei do país onde nasceu a mãe ou o pai, que pode ser aplicada para reconhecer os filhos.
- **Ordem Pública**: Princípio que proíbe atos contrários à moralidade e aos bons costumes.
- **Direito Internacional Privado**: Ramo do direito que regula as relações entre os cidadãos de diferentes países.

### Referências legais
- Art. 1.234, Código Civil Brasileiro

### Jurisprudência
- Súmula 343 STF
- RE 456.789

### Dicas de prova
- Entenda a distinção entre direito internacional público e privado.
- Conheça as regras de conexão e elementos de conexão no direito internacional privado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.374 (2)", "page_number": 374, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1.234, Código Civil Brasileiro"], "jurisprudence": ["Súmula 343 STF", "RE 456.789"], "confidence": 0.8, "extracted_at": "2026-05-31T04:06:07.715389+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=374", "doc_key": "9968d66ecd5029d403c14d079a080b55"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6c9c57c07314a1f4389afd6aa8748c28fdafba8b4f32d01a118ac65458d41000'),
  ('cpiuris2025::44662d4dae8fac0cdb4ff7b486bb4cc0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência no Direito Processual Civil Internacional', '## Competência no Direito Processual Civil Internacional

A competência no Direito Processual Civil Internacional é regulada pelas normas de fixação de competência, que são diretas e unilaterais. O juiz competente é determinado pela lex fori, mas pode ser relativizado por meio de tratados internacionais.

### Conceitos
- **Lex fori**: A lei do foro
- **Competência**: O direito de um juiz decidir sobre uma questão
- **Princípio do kompetenz-kompetenz**: O princípio que estabelece a competência do juiz para aplicar as próprias regras de competência
- **Tratados internacionais**: Acordos entre países que podem alterar ou complementar as regras de competência

### Referências legais
- Art. 109 do Código de Processo Civil
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência no Direito Processual Civil Internacional

### Dicas de prova
- Entenda o conceito de lex fori e sua importância na competência
- Conheça as regras do princípio do kompetenz-kompetenz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.375 (1)", "page_number": 375, "discipline": "Direitos Internacional", "legal_refs": ["Art. 109 do Código de Processo Civil", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência no Direito Processual Civil Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T04:06:21.930089+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=375", "doc_key": "44662d4dae8fac0cdb4ff7b486bb4cc0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cd0772eeb27bc6d77a439bf06faf0f4d3878ecc09a6cb5acae525a34e71f9563'),
  ('cpiuris2025::fe8cdf588abb401a2f0e8f75d9339c6d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prova de Direito Estrangeiro no Processo Brasileiro', '## Prova de Direito Estrangeiro no Processo Brasileiro

A prova do direito estrangeiro é regulada pela lex fori e compete à parte que o invoca, enquanto ao juiz compete a aplicação da legislação estrangeira de ofício.

### Conceitos
