  ('cpiuris2025::4ceface8d53f8e628a4342a42b76df02', 'doutrina', 'cp_iuris', 'Direitos Internacional — Retorno de Crianças', '## Retorno de Crianças

A autoridade do Estado Contratante deve ordenar o retorno imediato da criança se encontrando no seu território, independentemente do tempo transcorrido desde a sua remoção. Caso haja razões para crer que a criança foi levada para outro Estado, pode-se suspender ou rejeitar o pedido de retomo.

### Conceitos
- **Retorno de Crianças**: O direito do Estado Contratante de ordenar o retorno da criança se encontrando em seu território
- **Competência**: A autoridade responsável pelo retomo da criança é determinada pela legislação e convenções internacionais
- **Suspensão do Processo**: O Estado pode suspender o processo de retomo se houver razões para crer que a criança foi levada para outro Estado
- **Rejeição do Pedido**: O pedido de retomo pode ser rejeitado se for provado que a criança já está integrada no seu novo meio
- **Legislação Internacional**: As convenções internacionais, como a Convenção de Haia sobre Aspectos Civis do Sequestro, regulamentam o retomo de crianças

### Referências legais
- Art. 36 da Convenção de Haia sobre Aspectos Civis do Sequestro

