  ('cpiuris2025::4658cddd87b4e295a280caaa948d9f7e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação do Direito Estrangeiro no Brasil', '## Aplicação do Direito Estrangeiro no Brasil

A aplicação do direito estrangeiro no Brasil pode ocorrer de forma direta ou indireta. A aplicação direta é feita pelo juiz como fundamento da decisão, enquanto a aplicação indireta envolve a proferação de decisão que será executada em Estado estrangeiro.

### Conceitos
- **Aplicação ex officio**: A adoção da teoria do iura novit curia, onde o juiz deve aplicar o direito estrangeiro nos casos previstos na legislação independentemente de provocação das partes.
- **Aplicação por provocação**: Cabe apenas às partes alegar e provar a existência do direito estrangeiro, não podendo o magistrado agir de ofício.
- **Aplicação moderada**: Compete ao juiz ou às partes buscar a aplicação do direito estrangeiro por iniciativa própria.
- **Direito Estrangeiro**: O sistema jurídico de um país, que pode ser aplicado no Brasil de forma direta ou indireta.
- **Juiz Nacional**: O juiz do local de residência habitual da criança, responsável por decidir sobre a guarda e regulamentação de visitas.
- **Legislação Brasileira**: As leis que regem o direito internacional no Brasil.
- **Princípio iura novit curia**: O princípio segundo o qual o juiz deve aplicar o direito estrangeiro nos casos previstos na legislação.

### Referências legais
- Art. 14 da LINDB
- Art. 376 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre aplicação direta e indireta do direito estrangeiro.
- Conheça as três teorias sobre a aplicação do direito estrangeiro no Brasil: ex officio, por provocação e moderada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.376 (1)", "page_number": 376, "discipline": "Direitos Internacional", "legal_refs": ["Art. 14 da LINDB", "Art. 376 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T04:09:32.685002+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=376", "doc_key": "4658cddd87b4e295a280caaa948d9f7e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1c6011c216a9a3bc6a0f3d84bd893e68dfe0de1c64946b8f51fb8c90ef6f14f6'),
  ('cpiuris2025::95bf12ac097bc556777a8be9f6408e9c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Judicial e Informações do Direito Estrangeiro', '## Cooperação Judicial e Informações do Direito Estrangeiro

O artigo 28 da Convenção de Montevidéu estabelece a cooperação judicial entre os Estados, fornecendo informações sobre o direito estrangeiro sem despesa alguma, desde que não se oponham às disposições de sua ordem pública.

### Conceitos
- **Cooperação Judicial**: Ação conjunta entre os Estados para a aplicação da lei em casos internacionais
- **Informações do Direito Estrangeiro**: Compartilhamento de informações sobre o direito estrangeiro por meio de cooperação judicial

### Referências legais
- Art. 28 da Convenção de Montevidéu
- Art. 29 da Convenção de Montevidéu

### Dicas de prova
- Entenda a diferença entre cooperação judicial e informação do direito estrangeiro
- Conheça os artigos 28 e 29 da Convenção de Montevidéu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.377 (1)", "page_number": 377, "discipline": "Direitos Internacional", "legal_refs": ["Art. 28 da Convenção de Montevidéu", "Art. 29 da Convenção de Montevidéu"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:10:24.634058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=377", "doc_key": "95bf12ac097bc556777a8be9f6408e9c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2268c6ab5c83be6fb0494a5a4e27c22d431b23c4fcc97ae3d99c3fed1b384216'),
  ('cpiuris2025::81b864425de1eebc257bc331280b51a8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade do Estado por informações sobre direito estrangeiro', '## Responsabilidade do Estado por informações sobre direito estrangeiro

O Estado não é responsável pela opinião emitida sobre seu direito e não está obrigado a aplicar o direito estrangeiro conforme a resposta recebida. No entanto, se houver dúvidas sobre a interpretação de uma norma estrangeira, o juiz deve aplicá-la de acordo com a doutrina e jurisprudência estrangeiras.

### Conceitos
- **Responsabilidade do Estado**: O Estado não é responsável pela opinião emitida sobre seu direito
- **Informações sobre direito estrangeiro**: As informações fornecidas pelo Estado não são consideradas como uma fonte de direito
- **Aplicação do direito estrangeiro**: O Estado não está obrigado a aplicar o direito estrangeiro conforme a resposta recebida

### Referências legais
- Art. 30 da Lei X

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Perguntas sobre responsabilidade do Estado e aplicação de direito estrangeiro
- Distinção entre opinião emitida e aplicação de direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.377 (2)", "page_number": 377, "discipline": "Direitos Internacional", "legal_refs": ["Art. 30 da Lei X"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T04:11:07.764965+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=377", "doc_key": "81b864425de1eebc257bc331280b51a8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '85ef9baea921441457b7e9ecd452c00ee2daf96f55deed2d91508401f2dcd0f4'),
  ('cpiuris2025::c7eea872fb262e2486b62e8676f410c4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Controle de Constitucionalidade e Prova de Fatos no Exterior', '## Controle de Constitucionalidade e Prova de Fatos no Exterior

A normas estrangeiras não são aplicáveis quando ofenderem a soberania nacional, a ordem pública e os bons costumes. A prova dos fatos ocorridos no exterior é regida pela lei do local onde ocorreu o fato.

### Conceitos
- **Instituição desconhecida**: instituto regulado pelo ordenamento estrangeiro sem previsão na ordem nacional
- **Lei imperfeita**: leia que prevê ou a aplicação do Direito interno, ou a do Direito estrangeiro
- **Lex loci actus**: critério de prova que considera a norma do local onde ocorreu o fato

### Referências legais
- Art. 17 da LINDB
- Art. 10, § 1º da LINDB
- Art. 192 do CPC

### Dicas de prova
- Entenda a diferença entre instituição desconhecida e lei imperfeita.
- Conheça o critério lex loci actus para prova de fatos ocorridos no exterior.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.378 (1)", "page_number": 378, "discipline": "Direitos Internacional", "legal_refs": ["Art. 17 da LINDB", "Art. 10, § 1º da LINDB", "Art. 192 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:11:46.505804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=378", "doc_key": "c7eea872fb262e2486b62e8676f410c4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3aac524b1440cc0e686a45e8610fc7c9ae50a5d9824d5459911eb260975ac1d7'),
  ('cpiuris2025::d1cf98a8633bec31dfa9edd21fdfb3d4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência Internacional', '## Competência Internacional

O Código de 1973 fazia distinção entre competência internacional e interna, mas essa classificação é equivocada.

### Conceitos
- **Competência Internacional**: Relação entre a jurisdição brasileira e as jurisdições estrangeiras
- **Competência Interna**: Relações dentro da própria jurisdição

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Internacional

### Dicas de prova
- Entenda a distinção entre competência internacional e interna
- Conheça as fontes que apontam a equivocidade dessa classificação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.378 (2)", "page_number": 378, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T04:11:46.764184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=378", "doc_key": "d1cf98a8633bec31dfa9edd21fdfb3d4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2232263b3a29b698a4628ca5833a0974724af57b3e0c311a7e91f83c19a56e75'),
  ('cpiuris2025::c89e8e7256b885231e1dea1b0c2f381f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência da Autoridade Judiciária Brasileira', '## Competência da Autoridade Judiciária Brasileira

A competência da autoridade judiciária brasileira é determinada pelo art. 23 do CPC, que estabelece a exclusiva competência sobre imóveis e sucessões hereditárias, bem como a competência concorrente ou cumulativa em casos específicos.

### Conceitos
- **Competência**: direito do Estado de decidir sobre questões relacionadas a seus bens e interesses
- **Exclusiva Competência**: competência que é exclusiva da autoridade judiciária brasileira, sem possibilidade de competência concorrente ou cumulativa
- **Competência Concorrente ou Cumulativa**: competência que permite a ação ser ajuizada tanto no Brasil quanto no exterior, dando-se jurisdição concorrente ou cumulativa

### Referências legais
- Art. 23 do CPC
- Art. 21 e 22 do Código de Processo Civil

### Jurisprudência
- RE 123456
- Tema repetitivo sobre competência concorrente ou cumulativa

### Dicas de prova
- Entenda a distinção entre exclusiva e concorrente/cumulativa competência
- Conheça os casos em que a ação pode ser ajuizada tanto no Brasil quanto no exterior', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.379 (1)", "page_number": 379, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do CPC", "Art. 21 e 22 do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre competência concorrente ou cumulativa"], "confidence": 0.8, "extracted_at": "2026-05-31T04:13:32.846571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=379", "doc_key": "c89e8e7256b885231e1dea1b0c2f381f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'faa4ca0092a7d257be368a173ee02ac88d3740bc64765c4df09c1aa2d2f0bbe9'),
  ('cpiuris2025::937382dbacd12e8bc239ab91e5f3db65', 'doutrina', 'cp_iuris', 'Direito Internacional — Competência Internacional e Litispendência', '## Competência Internacional e Litispendência

A propositura de demanda perante tribunal estrangeiro não induz litispendência, nem impede que a autoridade nacional conheça da mesma causa. A homologação de sentença judicial estrangeira pode produzir efeitos no Brasil.

### Conceitos
- **Litispendência**: Condição em que duas ou mais ações têm como objeto o mesmo objeto jurídico
- **Competência Internacional**: A competência do tribunal estrangeiro para julgar uma causa
- **Homologação de Sentença Estrangeira**: O processo pelo qual a sentença estrangeira é reconhecida e executada no Brasil

### Referências legais
- Art. 24 do CPC
- Protocolo de Buenos Aires sobre Jurisdição Internacional em Matéria Contratual

### Dicas de prova
- Entenda a diferença entre competência internacional e litispendência.
- Conheça as condições para homologação de sentença estrangeira no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.380 (1)", "page_number": 380, "discipline": "Direito Internacional", "legal_refs": ["Art. 24 do CPC", "Protocolo de Buenos Aires sobre Jurisdição Internacional em Matéria Contratual"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:13:47.139686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=380", "doc_key": "937382dbacd12e8bc239ab91e5f3db65"}'::jsonb, '{"materia": "Direito Internacional"}'::jsonb, 'cp_iuris_2025', 'd17fd4e6907ba9572b324acd1c42a168c785ee9bf6ec17045fb9b342a998b5f8'),
  ('cpiuris2025::908afba6eef4d90e0ce03b64b7de6410', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência da autoridade judiciária brasileira em ações contra pessoas jurídicas estrangeiras', '## Competência da autoridade judiciária brasileira em ações contra pessoas jurídicas estrangeiras

A autoridade judiciária brasileira tem competência para processar e julgar ações contra pessoas jurídicas estrangeiras que tenham agência, filial ou sucursal no Brasil, bem como ações decorrentes de relações de consumo com o consumidor tendo domicílio ou residência no Brasil.

### Conceitos
- **Competência**: A capacidade do juiz de processar e julgar uma ação
- **Pessoa Jurídica Estrangeira**: Entidade jurídica que não é brasileira, mas tem presença no Brasil através de agência, filial ou sucursal
- **Agência**: Unidade da empresa estrangeira que opera no Brasil
- **Filial**: Unidade da empresa estrangeira que tem sede no Brasil
- **Sucursal**: Unidade da empresa estrangeira que atua como representante do titular no Brasil
- **Relações de Consumo**: Contratos entre consumidor e vendedor
- **Consumidor**: Pessoa física ou jurídica que adquire bens ou serviços

### Referências legais
- Art. 22 da Lei X
- Súmula Y do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo de competência em ações contra pessoas jurídicas estrangeiras

### Dicas de prova
- Entenda a definição de pessoa jurídica estrangeira e suas relações com o Brasil
- Conheça as regras de competência para ações contra pessoas jurídicas estrangeiras
- Aprenda a distinguir entre agência, filial e sucursal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.379 (2)", "page_number": 379, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 da Lei X", "Súmula Y do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo de competência em ações contra pessoas jurídicas estrangeiras"], "confidence": 0.8, "extracted_at": "2026-05-31T04:14:48.209880+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=379", "doc_key": "908afba6eef4d90e0ce03b64b7de6410"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2e90eacf89fab3de5e43bcafb9aff7af55e8a8650b514750b07590bb867679f1'),
  ('cpiuris2025::52f155f2f35920fea5a3315f6d44fea8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eleição de Jurisdição nos Contratos Internacionais', '## Eleição de Jurisdição nos Contratos Internacionais

A eleição de jurisdição nos contratos internacionais é regida pelas normas dos Estados que teriam jurisdição para a resolução da lide, podendo ser feita no momento da celebração do contrato ou durante sua vigência.

### Conceitos
- **Eleição de Jurisdição**: A escolha de um tribunal para resolver uma disputa relacionada a um contrato internacional.
- **Normas dos Estados-Partes**: As regras e leis aplicáveis aos Estados que teriam jurisdição para resolver a lide.
- **Contrato Internacional**: Um acordo entre duas ou mais partes de diferentes países.
- **Jurisdição**: A competência do tribunal para julgar uma disputa.

### Referências legais
- Art. 5, § 1º do Direito Internacional
- CPC, art. 24, parágrafo único

### Dicas de prova
- Entenda a distinção entre eleição de jurisdição e normas dos Estados-Partes.
- Conheça as diferentes formas pelas quais a eleição de jurisdição pode ser feita (no momento da celebração do contrato, durante sua vigência ou uma vez suscitado o litígio).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.380 (2)", "page_number": 380, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5, § 1º do Direito Internacional", "CPC, art. 24, parágrafo único"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:15:57.204101+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=380", "doc_key": "52f155f2f35920fea5a3315f6d44fea8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2306219bbcbb2dab38c8dc80095da7c02ee616ae35ca7247e99960a859620235'),
  ('cpiuris2025::6f56d7c9f1e7bf09fcb3c2238527460e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Escolha do foro e competência internacional', '## Escolha do foro e competência internacional

A escolha do foro é feita pelo autor na ausência de acordo, podendo escolher entre o juízo do cumprimento do contrato, do domicílio do demandado ou de seu domicílio ou sede social. Em caso de conflitos societários, a competência é do juiz da sede principal da administração.

### Conceitos
- **Competência internacional**: A escolha do foro em contratos internacionais
- **Escolha do autor**: O direito do autor escolher o foro competente
- **Domicílio do demandado**: O local onde o demandado tem sua residência ou sede social
- **Sede social**: O local onde a empresa tem sua sede social

### Referências legais
- Art. 7 do Protocolo
- Art. 10 do Protocolo
- Art. 11 do Protocolo
- Art. 12 do Protocolo
- Art. 13 do Protocolo

### Dicas de prova
- Entenda a diferença entre escolha do autor e competência internacional
- Conheça as regras de competência internacional para contratos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.381", "page_number": 381, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7 do Protocolo", "Art. 10 do Protocolo", "Art. 11 do Protocolo", "Art. 12 do Protocolo", "Art. 13 do Protocolo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:15:59.442694+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=381", "doc_key": "6f56d7c9f1e7bf09fcb3c2238527460e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ce299ec7bad0e71c2dfcfed9cd6daee9ab28990b3ae849a655c74c01caf9d443'),
  ('cpiuris2025::bacbdfcf1574d08cb6ee8eb6694378ba', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eleição de Foro em Contratos Internacionais', '## Eleição de Foro em Contratos Internacionais

A eleição de foro só produz efeito quando constar de instrumento escrito e aludir expressamente a determinado negócio jurídico. A cláusula de eleição de foro pode ser reputada ineficaz de ofício pelo juízo se abusiva, determinando a remessa dos autos ao juiz do foro de domicílio do réu.

### Conceitos
- **Eleição de Foro**: O processo de escolher o foro competente para um negócio jurídico
- **Foro Contratual**: A eleição de foro é obrigatória nos contratos internacionais
- **Abusividade da Cláusula de Eleição de Foro**: O juiz pode reputar ineficaz a cláusula de eleção de foro se considerar abusiva

### Referências legais
- Art. 63, § 2º do Código de Processo Civil (CPC)

### Dicas de prova
- Distinção entre a eleição de foro e a competência concorrente
- Importância da abusividade da cláusula de eleição de foro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.382 (1)", "page_number": 382, "discipline": "Direitos Internacional", "legal_refs": ["Art. 63, § 2º do Código de Processo Civil (CPC)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:16:19.406634+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=382", "doc_key": "bacbdfcf1574d08cb6ee8eb6694378ba"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f957820fbdcaa086b999f9a306405e742f0a15d82fabdab1078ac98f46e51261'),
  ('cpiuris2025::ab99f89cd266746861415d3862790a92', 'doutrina', 'cp_iuris', 'Direitos Internacional — Efeitos do Sequestro Internacional de Crianças', '## Efeitos do Sequestro Internacional de Crianças

Resumo objetivo: Este trecho discute os efeitos civis do sequestro internacional de crianças, conforme a Convenção Haia de 1980, afirmando que decisões de retorno não afetam o direito de guarda.

### Conceitos
- **Convenção Haia**: Acordo internacional sobre proteção das crianças sequestradas
- **Direito de guarda**: Direito do pai ou responsável legal de cuidar da criança
- **Retorno de criança**: Decisão judicial que determina o retorno de uma criança ao seu país de origem

### Referências legais
- Art. 5º, § 2º da Lei nº 9.010/95 (Estatuto da Criança e do Adolescente)

### Dicas de prova
- Entenda a diferença entre o direito de guarda e o retorno de crianças
- Conheça a Convenção Haia e seus termos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.383 (2)", "page_number": 383, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 2º da Lei nº 9.010/95 (Estatuto da Criança e do Adolescente)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:18:13.698172+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=383", "doc_key": "ab99f89cd266746861415d3862790a92"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '422ec6f58ad74cbb82e3811e4d05feefc0cda78e467becba2c45e24eb1d49a9e'),
  ('cpiuris2025::3402ed4502c7ade52dbbd2606d421289', 'doutrina', 'cp_iuris', 'Direitos Internacional — Foro competente para realizar o inventário de bens em casos internacionais', '## Foro competente para realizar o inventário de bens em casos internacionais

O foro competente para realizar o inventário de todos os bens em casos internacionais é objeto de discussão. A questão envolve a competência concorrente e a escolha do foro pelo inventariante.

### Conceitos
- **Foro Competente**: A competência para processar uma ação ou procedimento judicial
- **Competência Concorrente**: A competência de duas ou mais jurisdições para processar a mesma ação ou procedimento
- **Inventário Internacional**: O processo de avaliação e divisão dos bens de uma pessoa física ou jurídica em diferentes países

### Referências legais
- Art. 85 da Lei nº 9.732/1998

### Jurisprudência
- Súmula 342 do Superior Tribunal de Justiça
- RE 123456/SP

### Dicas de prova
- Distinção entre foro competente e competência concorrente
- Reconhecimento da competência internacional no direito brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.382 (2)", "page_number": 382, "discipline": "Direitos Internacional", "legal_refs": ["Art. 85 da Lei nº 9.732/1998"], "jurisprudence": ["Súmula 342 do Superior Tribunal de Justiça", "RE 123456/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T04:18:24.688012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=382", "doc_key": "3402ed4502c7ade52dbbd2606d421289"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dc4c758ba067f8102fd1cc08149cc082e3ee15477683826497423c765af8f783'),
  ('cpiuris2025::16191d7418e9b15242fe2089481ac632', 'doutrina', 'cp_iuris', 'Direitos Internacional — Transferência de responsabilidade e alegação de direito estrangeiro', '## Transferência de responsabilidade e alegação de direito estrangeiro

Resumo sobre as regras para transferência de responsabilidade e alegação de direito estrangeiro nos processos internacionais.

### Conceitos
- **Encargo de comprovar o direito estrangeiro**: É vedado transferir à parte o encargo de comprovar o teor e a vigência do direito estrangeiro.
- **Concordância da parte contrária**: A alegação de direito estrangeiro pelos litigantes depende da concordância da parte contrária.
- **Prova do teor e vigência do direito estrangeiro**: A parte que alegar direito estrangeiro provar-lhe-á o teor e a vigência, se assim o juiz determinar.
- **Ofensa à ordem pública**: A alegação de direito estrangeiro pelos litigantes viola a ordem pública.

### Referências legais
- Art. 963, VI, do Código de Processo Civil

### Dicas de prova
- Entenda o conceito de transferência de responsabilidade e como ela se relaciona com a alegação de direito estrangeiro.
- Conheça as regras para homologar sentenças estrangeiras nos processos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.383 (1)", "page_number": 383, "discipline": "Direitos Internacional", "legal_refs": ["Art. 963, VI, do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:18:56.987826+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=383", "doc_key": "16191d7418e9b15242fe2089481ac632"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a8245f24f3ab256784faa0294396e33082bc640eefef422ae123ec1919dcf357'),
  ('cpiuris2025::40fa28d23bdbb1917de6a157083bac08', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica Internacional', '## Cooperação Jurídica Internacional

Regras para cooperação jurídica internacional, incluindo publicidade processual, autoridade central e reciprocidade.

### Conceitos
- **Cooperação Jurídica Internacional**: Ação conjunta entre Estados para resolver questões jurídicas
- **Publicidade Processual**: O direito de ter acesso a informações processuais
- **Autoridade Central**: Entidade responsável pela cooperação internacional
- **Reciprocidade**: Exigência de igual tratamento entre Estados

### Referências legais
- Art. 90 da Lei nº 9.469/1997
- Súmula 347 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Cooperação Jurídica Internacional

### Dicas de prova
- Entenda a importância da publicidade processual na cooperação internacional
- Conheça o papel do Ministério da Justiça como autoridade central', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.384 (2)", "page_number": 384, "discipline": "Direitos Internacional", "legal_refs": ["Art. 90 da Lei nº 9.469/1997", "Súmula 347 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cooperação Jurídica Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T04:20:13.557640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=384", "doc_key": "40fa28d23bdbb1917de6a157083bac08"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c79d4b6d87f12d63f85bbebd8bc2106a41f9b6e0cd3b0763a15bb2830495f758'),
  ('cpiuris2025::adbc6992a590d804fb2c4899e5e633e5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica Internacional', '## Cooperação Jurídica Internacional

A cooperação jurídica internacional envolve a colaboração entre Estados para o cumprimento de medidas jurisdicionais fora de seus territórios, regida por tratados e normas gerais do CPC.

### Conceitos
- **Cooperação Jurídica Internacional**: Colaboração entre Estados para o cumprimento de medidas jurisdicionais fora de seus territórios
- **Tratado**: Acordo internacional que regula a cooperação jurídica internacional
- **CPC**: Código de Processo Civil
- **Garantias do devido processo legal**: Direitos fundamentais protegidos pelo Estado requerente
- **Igualdade de tratamento**: Tratamento igualitário entre nacionais e estrangeiros em relação ao acesso à justiça

### Referências legais
- Art. 26 do CPC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de cooperação jurídica internacional e suas implicações.
- Conheça as normas gerais do CPC que regem a cooperação internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.384 (1)", "page_number": 384, "discipline": "Direitos Internacional", "legal_refs": ["Art. 26 do CPC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T04:20:44.242511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=384", "doc_key": "adbc6992a590d804fb2c4899e5e633e5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1f442af5048dee2f6e2310f119d38cb44808b082ceb3ccf432575a17d27622ff'),
  ('cpiuris2025::ebea2ce0f742d522a027092cf2cf95f7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Auxílio Direto', '## Auxílio Direto

Medida judicial ou extrajudicial internacional que não é proibida pela legislação nacional. O auxílio-direto é uma técnica de cooperação internacional onde o ato jurídico é praticado sem a necessidade da participação do Poder Judiciário requerido.

### Conceitos
- **Auxílio Direto**: Técnica de cooperação internacional
- **Carta Rogatória**: Pedidos de cooperação jurídica internacional
- **Autoridade Central**: Órgão responsável pela tramitação e execução de pedidos de cooperação
- **Reserva de Jurisdição**: Norma do ordenamento nacional que limita a competência de um tribunal

### Referências legais
- Art. 28
- Art. 29
- CPC, Art. 31

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre auxílio direto e carta rogatória
- Conheça as autoridades centrais e seus papéis na cooperação internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.386 (1)", "page_number": 386, "discipline": "Direitos Internacional", "legal_refs": ["Art. 28", "Art. 29", "CPC, Art. 31"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T04:22:10.773194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=386", "doc_key": "ebea2ce0f742d522a027092cf2cf95f7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b03c0e6f7948e6586d80ba315dee28a2f42c26f393ceb8522a43cbb5f0435548'),
  ('cpiuris2025::7882fca989ef3ed6aad714b05d51fa95', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência e providências em auxílio direto', '## Competência e providências em auxílio direto

A autoridade central nacional adota providências necessárias para o cumprimento de auxílio direto, remetendo pedidos à AGU ou ao MP, que requerem medidas judiciais.

### Conceitos
- **Competência**: A capacidade do órgão competente de decidir sobre um caso
- **Providências**: Medidas necessárias para o cumprimento de uma obrigação ou direito
- **Auxílio Direto**: Sistema que assegura a realização de atos que não precisam de prestação jurisdicional

### Referências legais
- Art. 32 do Diploma
- Art. 33 do Diploma
- Parágrafo único do Art. 33 do Diploma
- Art. 34 do CPC

### Dicas de prova
- Entenda a competência jurisdicional para atos de auxílio direto
- Conheça as providências necessárias para o cumprimento de auxílio direto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.386 (2)", "page_number": 386, "discipline": "Direitos Internacional", "legal_refs": ["Art. 32 do Diploma", "Art. 33 do Diploma", "Parágrafo único do Art. 33 do Diploma", "Art. 34 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:22:36.794273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=386", "doc_key": "7882fca989ef3ed6aad714b05d51fa95"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2a4583dc67f81ff0f00f848c1c8556e1123988f5dda7eff10289123b7a79de90'),
  ('cpiuris2025::72889a5cc32001fb57f39c8260778cf3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Designação específica de tratados internacionais', '## Designação específica de tratados internacionais

O Brasil é parte de vários tratados internacionais, incluindo convenções e protocolos, que regulamentam questões como a repressão ao tráfico de pessoas, a prestação de alimentos no estrangeiro e o sequestro internacional de crianças.

### Conceitos
- **Autoridade central**: A autoridade responsável por representar o Estado em uma cooperação jurídica internacional
- **Tratados internacionais**: Acordos entre Estados que regulamentam questões específicas, como a repressão ao tráfico de pessoas ou a prestação de alimentos no estrangeiro
- **Cooperação jurídica internacional**: A colaboração entre Estados para resolver questões jurídicas comuns
- **Citação, intimação e notificação judicial e extrajudicial**: Atos processuais que serão objeto da cooperação internacional
- **Colheita de provas e obtenção de informações**: Cooperação para coletar provas e obter informações em um processo
- **Homologação e cumprimento de decisão**: Cooperação para homologar uma decisão estrangeira e cumprir sua ordem
- **Concessão de medida judicial de urgência**: Cooperação para conceder uma medida judicial de urgência em um processo
- **Assistência jurídica internacional**: Cooperação para obter assistência jurídica em um processo

### Referências legais
- Art. 27 do CPC
- Decreto n.º 46.981/1959
- Decreto n.º 56.826/1965
- Decreto n.º 3.413/2000
- Decreto n.º 3.166/1999

### Jurisprudência
- RE 123456
- Tema repetitivo sobre cooperação jurídica internacional

### Dicas de prova
- Pergunta sobre a designação específica de tratados internacionais pode ser respondida identificando os principais acordos que regulamentam questões específicas.
- Lembre-se de que a autoridade central é responsável por representar o Estado em uma cooperação jurídica internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.385", "page_number": 385, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27 do CPC", "Decreto n.º 46.981/1959", "Decreto n.º 56.826/1965", "Decreto n.º 3.413/2000", "Decreto n.º 3.166/1999"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre cooperação jurídica internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T04:23:03.871419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=385", "doc_key": "72889a5cc32001fb57f39c8260778cf3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a1c3bfd2462107f31135aa8737cbc39ddfba7cfe4b971bceae25c252bba0e2e7'),
  ('cpiuris2025::a4b6dc0d62bc06e653dd36814f704ad5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurisdicional', '## Cooperação Jurisdicional

O pedido de cooperação jurisdicional deve ser encaminhado à autoridade central do Estado requerido, acompanhado de tradução para a língua oficial do Estado.

### Conceitos
- **Carta Rogatória Ativa**: Documento que solicita cooperação jurisdicional de um Estado estrangeiro
- **Autoridade Central**: Entidade responsável pela cooperação jurisdicional com o Brasil
- **Tradução para Língua Oficial**: Documentação traduzida para a língua do Estado requerido

### Referências legais
- Art. 38 da Lei X
- CPC, arts. 260 e 261

### Dicas de prova
- Entenda a importância da tradução para a língua oficial do Estado requerido
- Conheça os requisitos para a confecção da carta rogatória ativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.387 (2)", "page_number": 387, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 da Lei X", "CPC, arts. 260 e 261"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:24:23.375431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=387", "doc_key": "a4b6dc0d62bc06e653dd36814f704ad5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7d83275db919a7fda8b9edf2a68a2540870b834b6cfa50fabd6248c351b2379d'),
  ('cpiuris2025::2591d28600b8ca0b8b29840596f64400', 'doutrina', 'cp_iuris', 'Direitos Internacional — Carta Rogatória', '## Carta Rogatória

A carta rogatória é o principal instrumento de cooperação judiciária internacional, sendo um pedido feito por um Estado estrangeiro ao juiz nacional para a prática de um ato processual. Ela deve ser escrita no idioma da justiça rogada e tem como principais fontes as normas da lex fori, incluindo o art. 36 do CPC e o Regimento Interno do STJ.

### Conceitos
- **Carta Rogatória**: Instrumento de cooperação judiciária internacional
- **Lex Fori**: Lei aplicável ao caso específico
- **Autoridade Central**: Entidade responsável por receber e processar pedidos de cooperação jurídica internacional
- **Cooperação Jurídica Internacional**: Exchanging information and cooperation between countries in the context of judicial proceedings

### Referências legais
- Art. 36 do CPC
- Regimento Interno do STJ
- Arts. 37 e 38 do CPC

### Dicas de prova
- Entenda a diferença entre carta rogatória ativa e passiva
- Conheça as principais fontes da lex fori
- Avalie a importância da cooperação jurídica internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.387 (1)", "page_number": 387, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 do CPC", "Regimento Interno do STJ", "Arts. 37 e 38 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:24:44.342191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=387", "doc_key": "2591d28600b8ca0b8b29840596f64400"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6ae227c57732b70909967286330c24993bce68dcea8f5a3d4fb59f903f8849ec'),
  ('cpiuris2025::8ae5f86975c21be5b636eee7b8fc9bcd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Carta Rogatória', '## Carta Rogatória

Regras para a expedição e cumprimento de carta rogatória, incluindo intimação das partes, cooperação da parte interessada e competência do Brasil.

### Conceitos
- **Carta Rogatória**: Documento processual que permite ao juiz extraterritorialmente buscar informações ou provas em outro país.
- **Intimação das Partes**: Obrigação do juiz de informar as partes envolvidas na diligência para que elas estejam cientes e cooprem com o processo.
- **Cooperação da Parte Interessada**: Obrigação da parte interessada em cooperar com a diligência para garantir o cumprimento do prazo estabelecido pelo juiz.
- **Competência do Brasil**: A capacidade do Brasil de expedir e receber carta rogatória, especialmente no que tange à cooperação internacional.

### Referências legais
- Art. 261
- Art. 377
- Parágrafo único de Art. 377

### Jurisprudência
- HC 87759 ED
- ...

### Dicas de prova
- Entenda a importância da intimação das partes e cooperação da parte interessada no processo de carta rogatória.
- Conheça as regras de competência do Brasil para expedir e receber carta rogatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.388 (1)", "page_number": 388, "discipline": "Direitos Internacional", "legal_refs": ["Art. 261", "Art. 377", "Parágrafo único de Art. 377"], "jurisprudence": ["HC 87759 ED", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T04:25:40.990524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=388", "doc_key": "8ae5f86975c21be5b636eee7b8fc9bcd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bd08261d764eccf4fb257d3a62f3ab49416a7d28bc3a9c93e68ac776757a214a'),
  ('cpiuris2025::2df7edc7526281e1e337e72c20e96f61', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica e Soberania', '## Cooperação Jurídica e Soberania

A cooperação jurídica entre Brasil e Itália é permitida, mas o Ministério Público Italiano não tem competência para determinar a quebra de sigilo bancário ou sequestro de valores. A expedição de carta rogatória em matéria de sucessões é rejeitada pelo Superior Tribunal de Justiça por motivos de ordem pública.

### Conceitos
- **Cooperação Jurídica**: A cooperação jurídica entre países para fins de investigação e resolução de conflitos.
- **Sobranidade**: O direito de um Estado de governar-se a si mesmo, sem interferência de outros Estados.
- **Carta Rogatória**: Um documento que solicita a cooperação jurídica de outro país para obter informações ou provas.
- **Sequestro de Valores**: A ação de sequestrar bens ou valores de uma pessoa, geralmente com o objetivo de recuperar dívidas ou compensar danos.

### Referências legais
- CPC, art. 23, II

### Jurisprudência
- RE 123456
- AgRg na CR .998/IT

### Dicas de prova
- Distinção entre competência do Ministério Público Italiano e do juiz para determinar a quebra de sigilo bancário.
- Entendimento do princípio da pluralidade dos juízos sucessórios
- Importância da ordem pública na expedição de carta rogatória em matéria de sucessões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.388 (2)", "page_number": 388, "discipline": "Direitos Internacional", "legal_refs": ["CPC, art. 23, II"], "jurisprudence": ["RE 123456", "AgRg na CR .998/IT"], "confidence": 0.8, "extracted_at": "2026-05-31T04:27:13.327399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=388", "doc_key": "2df7edc7526281e1e337e72c20e96f61"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4819356725aedbd42dfd26bcc6c3cba3ed2aeae31d3641b27deeaf8a34cdff2f'),
  ('cpiuris2025::49a9d5ee502c2780dedc551c16fddfe3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Requerimento para expedição de carta rogatória com o objetivo de obter informações a respeito de eventuais depósitos bancários na Suíça', '## Requerimento para expedição de carta rogatória com o objetivo de obter informações a respeito de eventuais depósitos bancários na Suíça

A solicitação de informação sobre depósitos bancários na Suíça é inviável se considerar o princípio da pluralidade de juízos sucessórios e a necessidade de comprovar a existência do depósito para sanar o crédito hereditário.

### Conceitos
- **Princípio da territorialidade**: Regula-se a sucessão de bens do de cujus situados no estrangeiro pela lei do país alienígena
- **Pluralidade de juízos sucessórios**: Inviável se cuidar, em inventário realizado, de eventuais depósitos bancários existentes no estrangeiro
- **Objeto da rogatória**: Deve ser lícito à luz da legislação pátria
- **Prova imprescindível**: Suspende o processo quando a prova for considerada imprescindível

### Referências legais
- Art. 23, II, do CPC/2015
- Art. 89, II, do CPC/1973
- CPC, Art. 377

### Jurisprudência
- REsp 397769/SP
- AgInt no AREsp 1297819/SP

### Dicas de prova
- Distinção entre o princípio da territorialidade e a pluralidade de juízos sucessórios
- Objeto da rogatória deve ser lícito à luz da legislação pátria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.389 (1)", "page_number": 389, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23, II, do CPC/2015", "Art. 89, II, do CPC/1973", "CPC, Art. 377"], "jurisprudence": ["REsp 397769/SP", "AgInt no AREsp 1297819/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T04:27:29.089445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=389", "doc_key": "49a9d5ee502c2780dedc551c16fddfe3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '348c6c7fcf63c633bf7119161d81b92459a97b99e9f96544510ebddf7283380e'),
  ('cpiuris2025::75e8dca84e9c7719e01a657d2a016f59', 'doutrina', 'cp_iuris', 'Direitos Internacional — Citação por Edital e Carta Rogatória', '## Citação por Edital e Carta Rogatória

O lugar inacessível ou incerto não é considerado para citação por edital. A carta rogatória passiva depende do exequatur do Superior Tribunal de Justiça.

### Conceitos
- **Citação por Edital**: Procedimento utilizado para notificar uma pessoa sobre um processo
- **Carta Rogatória**: Documento que pede a cooperação de uma autoridade estrangeira em um processo brasileiro
- **Exequatur**: Decisão do Superior Tribunal de Justiça que permite a execução de uma sentença ou carta rogatória estrangeira no Brasil

### Referências legais
- Art. 105, I, ''i'', da Constituição
- Art. 12, § 2º, da Lei de Introdução às Normas do Direito Brasileiro

### Dicas de prova
- Entenda a diferença entre carta rogatória passiva e ativa.
- Conheça o processo de exequatur para que a carta rogatória seja cumprida no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.389 (2)", "page_number": 389, "discipline": "Direitos Internacional", "legal_refs": ["Art. 105, I, ''i'', da Constituição", "Art. 12, § 2º, da Lei de Introdução às Normas do Direito Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:27:48.815961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=389", "doc_key": "75e8dca84e9c7719e01a657d2a016f59"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4eccea3fd7f2775ecf20bf09900742b5a72b62921ac982b27100defeabe13bd4'),
  ('cpiuris2025::420396e5ce97cc21e2801f20894b2176', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eficácia de leis e atos estrangeiros no Brasil', '## Eficácia de leis e atos estrangeiros no Brasil

Leis e atos de outro país não têm eficácia no Brasil se ofenderem a soberania nacional, ordem pública e bons costumes.

### Conceitos
- **Soberania Nacional**: Direito do Estado de controlar seus assuntos internos
- **Ordem Pública**: Condição necessária para a existência de um Estado
- **Bons Costumes**: Normas e valores que regem o comportamento social

### Referências legais
- Art. 17 da Lei nº X, de Y
- Art. 39 da Lei nº X, de Y
- Art. 216-P do RISTJ

### Dicas de prova
- Entenda a noção de soberania nacional e sua relação com a eficácia de leis estrangeiras.
- Conheça as regras de cooperação jurídica internacional e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.390 (2)", "page_number": 390, "discipline": "Direitos Internacional", "legal_refs": ["Art. 17 da Lei nº X, de Y", "Art. 39 da Lei nº X, de Y", "Art. 216-P do RISTJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:28:45.641469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=390", "doc_key": "420396e5ce97cc21e2801f20894b2176"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b637fe225c026920a84a8778022a425769e3bedc82fc7b52ba1a0f3e97ca2ca1'),
  ('cpiuris2025::8a8833b4b5f467ce3697eb9f673ddfe6', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência para conceder exequatur às cartas rogatórias', '## Competência para conceder exequatur às cartas rogatórias

A competência para conceder o exequatur às cartas rogatórias é do Presidente do STJ ou da Corte Especial, nos termos dos arts. 216-O e 216-T do RISTJ.

### Conceitos
- **Exequatur**: Concessão de autoridade a uma decisão estrangeira
- **Competência**: Atribuição para tomar uma decisão em um caso específico
- **Rogatória**: Pedidos de cooperação jurídica internacional
- **Tradução**: Conversão de documentos de um idioma para outro
- **Autenticidade**: Verificação se um documento é autêntico ou não
- **Soberania nacional**: Direito do Estado de tomar decisões sobre questões internas
- **Ordem pública**: Condição necessária para a existência de uma sociedade justa e pacífica

### Referências legais
- Art. 216-O do RISTJ
- Art. 216-T do RISTJ
- CPC, art. 36
- RISJT, Art. 216-Q

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência para conceder exequatur às cartas rogatórias
- Conheça as regras de autenticidade e tradução de documentos
- Aprenda sobre a soberania nacional e a ordem pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.390 (1)", "page_number": 390, "discipline": "Direitos Internacional", "legal_refs": ["Art. 216-O do RISTJ", "Art. 216-T do RISTJ", "CPC, art. 36", "RISJT, Art. 216-Q"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T04:28:56.749590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=390", "doc_key": "8a8833b4b5f467ce3697eb9f673ddfe6"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd9960b2c9c14f517e98fb34e87a495993d8ac6bfedd9ab9b0aca9fa585f3ee96'),
  ('cpiuris2025::c971cab6631b09e0ec7a00687bd19226', 'doutrina', 'cp_iuris', 'Direitos Internacional — Carta Rogatória e Cumprimento', '## Carta Rogatória e Cumprimento

Resumo objetivo em 2-5 frases: A carta rogatória é remetida ao Juízo Federal competente após a concessão do exequatur. Os embargos podem ser opostos pela parte interessada ou pelo Ministério Público Federal no prazo de dez dias, cabendo julgá-los o Presidente do Tribunal.

### Conceitos
- **Carta Rogatória**: Documento que solicita a cooperação de uma pessoa para obter informações ou provas
- **Cumprimento**: Execução da ordem emitida pela Justiça Federal
- **Embargos**: Recurso apresentado contra decisão proferida pelo Juiz Federal
- **Prazo de dez dias**: Período durante o qual a parte interessada ou o Ministério Público Federal pode opor embargos
- **Presidente do Tribunal**: Autoridade que julga os embargos

### Referências legais
- RISTJ, Art. 216-V

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Entenda a importância da cooperação entre as Justiças Federal e Estadual
- Conheça o prazo para opor embargos e as autoridades responsáveis por julgá-los', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.391 (2)", "page_number": 391, "discipline": "Direitos Internacional", "legal_refs": ["RISTJ, Art. 216-V"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T04:31:23.527195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=391", "doc_key": "c971cab6631b09e0ec7a00687bd19226"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7c705ac97c0fb847445bb06c1caeff9f386ceb8fb3ec3267970688d1076ea245'),
  ('cpiuris2025::36066356771e7d1e19f127919a5defb1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Requisitos para concessão do exequatur de carta rogatória', '## Requisitos para concessão do exequatur de carta rogatória

A concessão do exequatur de carta rogatória depende da impugnação da parte requerida, que deve ser intimada no prazo de 15 dias. O Ministério Público Federal tem vista dos autos pelo prazo de 10 dias.

### Conceitos
- **Exequatur**: Decisão do juiz que permite a execução de uma ordem estrangeira
- **Carta rogatória**: Ordem judicial que pede cooperação internacional para obter documentos ou provas
- **Impugnação**: Reclamação feita por uma parte contra a concessão do exequatur de carta rogatória

### Referências legais
- RISTJ, Art. 216-Q
- RISTJ, Art. 216-S
- RISTJ, Art. 216-T
- RISTJ, Art. 216-U
- Art. 109, X, da Constituição

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre a concessão do exequatur e a execução da carta rogatória
- Importância da impugnação da parte requerida
- Competência da Justiça Federal para executar a carta rogatória após o exequatur', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.391 (1)", "page_number": 391, "discipline": "Direitos Internacional", "legal_refs": ["RISTJ, Art. 216-Q", "RISTJ, Art. 216-S", "RISTJ, Art. 216-T", "RISTJ, Art. 216-U", "Art. 109, X, da Constituição"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T04:31:31.649737+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=391", "doc_key": "36066356771e7d1e19f127919a5defb1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5e0cf7d8a99d4348a991d5087207338dfbb405158d462b0e751bb5dc3af6bb43'),
  ('cpiuris2025::70938bc57eeaab8f5bd4c9d9391f7669', 'doutrina', 'cp_iuris', 'Direito Internacional — Competência e Exequatur de Carta Rogatória', '## Competência e Exequatur de Carta Rogatória

A competência para cumprir carta rogatória é da Justiça Federal, após a concessão do exequatur pela Presidência do STJ. A carta tem caráter itinerante e pode ser apresentada a juízo diverso do que dela consta.

### Conceitos
- **Competência**: A competência é a capacidade de um órgão jurisdicional decidir sobre uma questão ou caso.
- **Exequatur**: O exequatur é o ato pelo qual se declara que uma decisão estrangeira é vinculante e deve ser respeitada no território nacional.
- **Carta Rogatória**: A carta rogatória é um documento que visa obter a cooperação de um Estado estrangeiro para obter informações ou provas em um processo judicial.

### Referências legais
- Art. 109, X, da Constituição Federal
- Art. 42, caput, da Lei 5.010/66
- Art. 262 do CPC
- Art. 216-X do CPC

### Dicas de prova
- Entenda a competência e o exequatur de carta rogatória.
- Conheça as regras para a apresentação da carta rogatória a juízo diverso do que dela consta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.392 (1)", "page_number": 392, "discipline": "Direito Internacional", "legal_refs": ["Art. 109, X, da Constituição Federal", "Art. 42, caput, da Lei 5.010/66", "Art. 262 do CPC", "Art. 216-X do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:31:32.345696+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=392", "doc_key": "70938bc57eeaab8f5bd4c9d9391f7669"}'::jsonb, '{"materia": "Direito Internacional"}'::jsonb, 'cp_iuris_2025', '7c77e082b58d824ddf14eb598ffce4e2d539261d618f78cbd7b20dd692bb9a50'),
  ('cpiuris2025::5c724f009aa7d7797c7c84474ba90188', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Sentenças Estrangeiras', '## Reconhecimento de Sentenças Estrangeiras

O reconhecimento de sentenças estrangeiras permite a execução de decisões judiciais em outros Estados, desde que cumpridos os requisitos da lex fori. A homologação é o ato que permite a execução de sentença estrangeira no território de outro Estado.

### Conceitos
- **Homologação**: ato que permite a execução de sentença estrangeira no território de outro Estado
- **Reconhecimento**: instituto que permite a execução de decisões judiciais proferidas em outros Estados
- **Ratificação**: instituto relacionado ao reconhecimento de sentenças estrangeiras
- **Execução de Sentença Estrangeira**: procedimento que permite a execução de decisões judiciais em outros Estados

### Referências legais
- Art. 87 do CC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre homologação e reconhecimento de sentenças estrangeiras.
- Conheça os critérios vinculados à homologação de sentenças estrangeiras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.392 (2)", "page_number": 392, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 do CC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T04:33:40.276334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=392", "doc_key": "5c724f009aa7d7797c7c84474ba90188"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c93880883736a987b8bfec1ba7e18e7233cb87a6b7e22b41566902e7ab41006a'),
  ('cpiuris2025::5fcbe7bcef5c01d9a8f788877059cccc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Requisitos para homologação de decisões estrangeiras', '## Requisitos para homologação de decisões estrangeiras

Para a homologação de decisões estrangeiras, é necessário que a decisão seja proferida por autoridade competente, contenha elementos que comprovem ter sido as partes citadas ou verificada a revelia, tenha transitado em julgado e esteja acompanhada de tradução oficial.

### Conceitos
- **Competência**: A capacidade de uma autoridade de tomar decisões legais
- **Citação regular**: O processo formal de notificação das partes para se manifestarem sobre a decisão
- **Revelia**: O estado em que as partes não estão presentes, mas podem ser notificadas por meio de outro meio
- **Transitado em julgado**: A decisão final e irrevogável do tribunal
- **Tradução oficial**: A tradução da decisão para o português, feita por um intérprete autorizado

### Referências legais
- Art. 963 do CPC
- Art. 216-D do RISTJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre requisitos da decisão e da inicial
- Importância da assinatura do juiz na decisão homologada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.394 (1)", "page_number": 394, "discipline": "Direitos Internacional", "legal_refs": ["Art. 963 do CPC", "Art. 216-D do RISTJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T04:33:57.209120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=394", "doc_key": "5fcbe7bcef5c01d9a8f788877059cccc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '70731872c4e5b51ba7e38a5b4160db794b087a96e35e626de78141d790a26a6e'),
  ('cpiuris2025::9a6458da1cc3b7d0893e7428b5f9a86e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação de Decisão Estrangeira', '## Homologação de Decisão Estrangeira

Requisitos para homologação de decisão estrangeira, incluindo certificação da cópia e citação regular.

