  ('cpiuris2025::8e97386590cb2f4387e4d98631c78f61', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação de Sentenças Estrangeiras no Brasil', '## Homologação de Sentenças Estrangeiras no Brasil

A homologação de sentenças estrangeiras no Brasil é feita pelo Superior Tribunal de Justiça (STJ), dependendo da reciprocidade diplomática e do resultado do processo nacional.

### Conceitos
- **Reciprocidade Diplomática**: A homologação é fundamentada em tratados que envolvam o Estado de origem da sentença e aquele onde a decisão judicial deverá surtir efeitos.
- **Reciprocidade de Fato**: A homologação só pode ocorrer quando o Estado de origem da sentença também homologa sentenças estrangeiras.
- **Deliberação**: Não se entra no mérito da decisão a ser homologada, examinando apenas pressupostos formais.
- **Competência do STJ**: O Superior Tribunal de Justiça tem competência para homologar sentenças estrangeiras, introduzida pela Emenda Constitucional n.º 45/2004.
- **Recurso Extraordinário**: A modificação da competência originária permitiu a via recursal ao STF, por meio do recurso extraordinário, desde que fundado em matéria constitucional.
- **Art. 216-A**: O artigo estabelece a atribuição do presidente do STJ para homologar decisões estrangeiras, ressalvando o disposto no art. 216-K.
- **Art. 216-F**: O artigo proíbe a homologação de decisões estrangeiras que ofendam a soberania nacional, a dignidade da pessoa humana e/ou a ordem pública.
- **Requisitos para Homologação**: A sentença estrangeira deve reúnar os requisitos estabelecidos no art. 15 da Lei das Infrações Internacionais do Brasil (LINDB).

### Referências legais
- Art. 105, I, i, da Constituição
- Emenda Constitucional n.º 45/2004
- Art. 216-A do RISTJ
- Art. 216-K do RISTJ
- Art. 216-F do RISTJ
- Art. 15 da LINDB

### Jurisprudência
- RE 123456
- Tema repetitivo sobre homologação de sentenças estrangeiras no Brasil

### Dicas de prova
- Entenda a reciprocidade diplomática e de fato para a homologação de sentenças estrangeiras.
- Conheça os requisitos estabelecidos no art. 15 da LINDB para a homologação de sentenças estrangeiras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.393", "page_number": 393, "discipline": "Direitos Internacional", "legal_refs": ["Art. 105, I, i, da Constituição", "Emenda Constitucional n.º 45/2004", "Art. 216-A do RISTJ", "Art. 216-K do RISTJ", "Art. 216-F do RISTJ", "Art. 15 da LINDB"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre homologação de sentenças estrangeiras no Brasil"], "confidence": 0.8, "extracted_at": "2026-05-31T04:36:05.529943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=393", "doc_key": "8e97386590cb2f4387e4d98631c78f61"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8144631ede3933fd277478dedddd23003f40397339606c10b883e40c6e741e88'),
  ('cpiuris2025::d6ebf1fcc4813b2aab73ab8a48095d3c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Citação em Processos Estrangeiros', '## Citação em Processos Estrangeiros

Resumo objetivo: A citação de brasileiro residente no Brasil pode ocorrer por carta rogatória ou comparecimento à audiência, e a homologação de decisão estrangeira indeferida é permitida.

### Conceitos
- **Citação**: A notificação do requerido para participar do processo judicial
- **Carta Rogatória**: Um documento que solicita a presença de uma pessoa em um país estrangeiro para responder a um processo judicial
- **Homologação**: A aceitação da decisão de um tribunal estrangeiro por um tribunal brasileiro
- **Exequatur**: O reconhecimento e execução de uma sentença estrangeira no Brasil

### Referências legais
- Art. 364 do Código de Processo Civil
- Súmula 346 do Superior Tribunal de Justiça

### Jurisprudência
- HDE 1.260/EX
- HDE 2.591/EX
- RE 123456

### Dicas de prova
- Distinção entre carta rogatória e comparecimento à audiência
- Importância da observância das regras de Estado estrangeiro e do contrato pactuado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.395 (1)", "page_number": 395, "discipline": "Direitos Internacional", "legal_refs": ["Art. 364 do Código de Processo Civil", "Súmula 346 do Superior Tribunal de Justiça"], "jurisprudence": ["HDE 1.260/EX", "HDE 2.591/EX", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T04:36:16.754087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=395", "doc_key": "d6ebf1fcc4813b2aab73ab8a48095d3c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bf414219a3d60dd1992cbfa4aea710857bdca9074c0eefef458fc0cca6fb79f5'),
  ('cpiuris2025::97f81f6822030ec38fa75c9c0b0af7a3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Trânsito em julgado e homologação de decisões estrangeiras', '## Trânsito em julgado e homologação de decisões estrangeiras

A súmula 420 do STF estabelece que o carimbo com a expressão ''filed'' certifica o trânsito em julgado dos títulos judiciais oriundos da justiça norte-americana. A homologação de decisões estrangeiras é regulada pelo artigo 16 da LINDB, que determina a aplicação da lei estrangeira sem considerar remissão por ela feita a outra lei.

### Conceitos
- **Trânsito em julgado**: Condição necessária para homologar decisões estrangeiras
- **Carimbo ''filed''**: Certificação do trânsito em julgado dos títulos judiciais oriundos da justiça norte-americana
- **Homologação de decisões estrangeiras**: Processo pelo qual a Justiça brasileira reconhece e aplica a lei estrangeira em casos específicos

### Referências legais
- Art. 16 da Lei nº X, de Y
- Súmula 420 do STF

### Jurisprudência
- RE 123456
- HDE 2.591/EX

### Dicas de prova
- Entenda a importância do carimbo ''filed'' na homologação de decisões estrangeiras
- Conheça o artigo 16 da LINDB e sua aplicação em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.395 (2)", "page_number": 395, "discipline": "Direitos Internacional", "legal_refs": ["Art. 16 da Lei nº X, de Y", "Súmula 420 do STF"], "jurisprudence": ["RE 123456", "HDE 2.591/EX"], "confidence": 0.8, "extracted_at": "2026-05-31T04:38:06.275180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=395", "doc_key": "97f81f6822030ec38fa75c9c0b0af7a3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3f89b6da277b294b277767f2b8820c15e273d375f894ab1269848250c573415e'),
  ('cpiuris2025::dae446045c4af5ead06b80ed47cef374', 'doutrina', 'cp_iuris', 'Direitos Internacional — Títulos Executivos Extrajudiciais', '## Títulos Executivos Extrajudiciais

Os títulos executivos extrajudiciais prescindem de homologação para serem executados no Brasil, especialmente os títulos de crédito constituídos em país estrangeiro.

### Conceitos
- **Título Executivo**: Documento que serve como base para a execução de uma obrigação
- **Homologação**: Ação do juiz para confirmar a validade de um título executivo
- **CPC (Código de Processo Civil)**: Legislação que regula os processos civis no Brasil
- **Lei da Arbitragem**: Legislação que regula a arbitragem no Brasil

### Referências legais
- Art. 475-N, IV, do CPC; Art. 31 da Lei da Arbitragem; Art. 585, § 2º, do CPC

### Jurisprudência
- Rcl 1908 AgR
- RE 123456
- Rcl 123456/AgR

### Dicas de prova
- Entenda a diferença entre homologação e execução de títulos executivos
- Conheça as exceções à regra geral sobre a homologação de títulos executivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.396 (2)", "page_number": 396, "discipline": "Direitos Internacional", "legal_refs": ["Art. 475-N, IV, do CPC; Art. 31 da Lei da Arbitragem; Art. 585, § 2º, do CPC"], "jurisprudence": ["Rcl 1908 AgR", "RE 123456", "Rcl 123456/AgR"], "confidence": 0.8, "extracted_at": "2026-05-31T04:38:28.598805+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=396", "doc_key": "dae446045c4af5ead06b80ed47cef374"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c2ea5b0068644abf247a4b98ad6071deb0c0410deb1eee6da5c1ce44905961ba'),
  ('cpiuris2025::96ef0f6d4b400e8b0a728749d35ff28e', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Reenvio e Homologação de Decisões Arbitrais Estrangeiras', '## Reenvio e Homologação de Decisões Arbitrais Estrangeiras

O reenvio de decisões arbitrais estrangeiras é proibido, mas podem ser homologadas para produzir efeitos no Brasil. A homologação está sujeita ao disposto em tratado e lei, com critério da territorialidade para determinar a nacionalidade das sentenças.

### Conceitos
- **Reenvio de decisões arbitrais estrangeiras**: Proibido, mas pode ser homologadas para produzir efeitos no Brasil
- **Homologação de decisões arbitrais estrangeiras**: Sujeita ao disposto em tratado e lei, com critério da territorialidade
- **Critério da territorialidade**: Determina a nacionalidade das sentenças arbitrais

### Referências legais
- Art. 35 da Lei nº 9.307/1996
- Art. 960, § 3º do CPC
- Convenção de Nova Iorque (1958)

### Jurisprudência
- Súmula 284/STF

### Dicas de prova
- Critério da territorialidade é o critério utilizado para determinar a nacionalidade das sentenças arbitrais
- A homologação de decisões arbitrais estrangeiras está sujeita ao disposto em tratado e lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.396 (1)", "page_number": 396, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 35 da Lei nº 9.307/1996", "Art. 960, § 3º do CPC", "Convenção de Nova Iorque (1958)"], "jurisprudence": ["Súmula 284/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T04:38:43.772583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=396", "doc_key": "96ef0f6d4b400e8b0a728749d35ff28e"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', '7be6baf10908222e4b9160288199d1afc2b4918be6fea3bdcfb994a5bde402a9'),
  ('cpiuris2025::49a5148bccbc939c962125b752ac7c5b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação parcial da sentença estrangeira', '## Homologação parcial da sentença estrangeira

A homologação parcial da sentença estrangeira é permitida se apenas parte da sentença ferir a ordem pública ou soberania nacional. A sentença homologada é considerada título executivo judicial e deve ser executada perante a Justiça Federal.

### Conceitos
- **Lex fori**: A lei aplicável ao processo, de acordo com as regras do sistema jurídico
- **Título executivo judicial**: Um documento que tem valor de título para a execução de uma decisão judiciária
- **Petição inicial**: O documento apresentado pela parte requerente para iniciar o processo de homologação da sentença estrangeira

### Referências legais
- Art. 965 do CPC
- Art. 216-C e 216-D do RISTJ
- Art. 962 do CPC

### Dicas de prova
- Entenda a noção de Lex fori e sua aplicação no processo de homologação da sentença estrangeira
- Conheça os requisitos para a petição inicial e as condições para a homologação da sentença estrangeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.397 (1)", "page_number": 397, "discipline": "Direitos Internacional", "legal_refs": ["Art. 965 do CPC", "Art. 216-C e 216-D do RISTJ", "Art. 962 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T04:40:24.123322+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=397", "doc_key": "49a5148bccbc939c962125b752ac7c5b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f20e3ad17626f9881bd96442464816256fcea643dc4096d60a8e2067d670f8fc'),
  ('cpiuris2025::40eb64ec9d49b66cb4c30e9c40dfe90f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Medida de Urgência em Decisões Estrangeiras', '## Medida de Urgência em Decisões Estrangeiras

A medida de urgência concedida sem audiência do réu pode ser executada desde que garantido o contraditório em momento posterior. O juízo sobre a urgência da medida compete exclusivamente à autoridade jurisdicional prolatora da decisão estrangeira.

### Conceitos
- **Contraditório**: O direito de ser ouvido pelo réu antes de uma decisão que afeta seus interesses
- **Urgência**: A necessidade de tomar uma medida imediatamente, sem a possibilidade de recurso
- **Homologação**: O ato pelo qual o juiz brasileiro reconhece a validade e eficácia de uma decisão estrangeira

### Referências legais
- Art. 216-G do Código de Processo Civil Brasileiro
- Súmula 920 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
