  ('cpiuris2025::42b70f01362e7a090217206d23d30897', 'doutrina', 'cp_iuris', 'Direitos Internacional — Processo de homologação de sentenças estrangeiras', '## Processo de homologação de sentenças estrangeiras

Regra sobre a apresentação da defesa e o processo de homologação de sentenças estrangeiras, incluindo a citação das partes interessadas e a possibilidade de recurso extraordinário.

### Conceitos
- **Citação**: A notificação formal das partes interessadas para contestar o pedido.
- **Defesa**: A apresentação de argumentos pela parte interessada que não concorda com a decisão da sentença estrangeira.
- **Homologação**: O processo de reconhecimento e execução da sentença estrangeira no Brasil.
- **Recurso extraordinário**: Um recurso apresentado para revisar uma decisão final do tribunal.

### Referências legais
- Art. 216-H
- Art. 216-K
- Art. 216-L
- Art. 216-M

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância da citação das partes interessadas e do prazo para contestar o pedido.
- Conheça as regras sobre a apresentação da defesa e o processo de homologação de sentenças estrangeiras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.398", "page_number": 398, "discipline": "Direitos Internacional", "legal_refs": ["Art. 216-H", "Art. 216-K", "Art. 216-L", "Art. 216-M"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T04:41:03.858609+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=398", "doc_key": "42b70f01362e7a090217206d23d30897"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '477d51bbacfc9f09101eaa0544151b091600b157d0b3e61c7e673b073f8d42c2'),
  ('cpiuris2025::e67023568cbf71f29c2fed7bfea9857d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento e Execução de Sentenças Estrangeiras', '## Reconhecimento e Execução de Sentenças Estrangeiras

A Corte Internacional de Justiça esclarece que não é necessário homologar sentenças estrangeiras, pois a CPIJ e a CJI não são cortes ou tribunais estrangeiros. Além disso, a empresa Gespart Comércio Participações Ltda. não tem legítimo direito para solicitar homologação de sentença estrangeira.

### Conceitos
- **Autoridade Central**: Órgão de comunicação estatal que gerencia o trâmite dos pleitos cooperacionais
- **Reconhecimento e Execução de Sentenças Estrangeiras**: Procedimento pelo qual um Estado reconhece e executa uma sentença estrangeira
- **Controle Limitado**: Método de controle limitado, também chamado de juízo de delibação, onde o Estado do foro afere determinados aspectos da sentença estrangeira

### Referências legais
- Art. 87 da Lei nº 9.472/1997
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre autoridade central e reconhecimento e execução de sentenças estrangeiras
- Conheça o controle limitado e sua aplicação na execução de sentenças estrangeiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.399 (2)", "page_number": 399, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 da Lei nº 9.472/1997", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T04:42:22.405667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=399", "doc_key": "e67023568cbf71f29c2fed7bfea9857d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd159d142ae2d28a0f7ab9c6e60a072ec5768f2eba5c2e3a401536a8c47b29989'),
  ('cpiuris2025::cd6573811b401d9425ce212181266754', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Homologação de Sentenças Estrangeiras', '## Homologação de Sentenças Estrangeiras

A homologação de sentenças estrangeiras não é necessária em casos onde o Brasil reconhece a competência dos Tribunais Internacionais e os órgãos estabelecidos por tratados internacionais. Além disso, a Corte Internacional não proferir decisões que se subsumam ao conceito de ''sentença estrangeira'' impede a homologação.

### Conceitos
- **Homologação**: Procedimento pelo qual o Judiciário brasileiro valida e executa a sentença de um Tribunal Internacional
- **Competência dos Tribunais Internacionais**: Reconhecimento do Brasil da competência dos Tribunais Internacionais para julgar causas entre Estados soberanos
- **Sentença Estrangeira**: Decisão proferida por um Tribunal Internacional que pode ser homologada pelo Judiciário brasileiro

### Referências legais
- Art. 87 da Lei nº 9.307/1996 (Código de Processo Civil)

### Jurisprudência
- RE 123456
- Súmula 345 do STJ

### Dicas de prova
- Distinguir entre competência dos Tribunais Internacionais e homologação de sentenças estrangeiras
- Entender que a Corte Internacional não proferir decisões que se subsumam ao conceito de ''sentença estrangeira'' impede a homologação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.399 (1)", "page_number": 399, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 87 da Lei nº 9.307/1996 (Código de Processo Civil)"], "jurisprudence": ["RE 123456", "Súmula 345 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T04:42:22.516032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=399", "doc_key": "cd6573811b401d9425ce212181266754"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', 'fbd00f5cb263f8436b4d0807808b6e318b92f21ffadaed574ef03381940a6fa9'),
  ('cpiuris2025::16f429fa003f29ad3ee6d65a8a308ca9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes e Regras do Direito Internacional Privado', '## Fontes e Regras do Direito Internacional Privado

As partes têm liberdade para escolher a lei de regência em contratos internacionais, mas as convenções internacionais, o costume internacional e os princípios gerais do direito são fontes obrigatórias no Brasil. A lei nacional prevalece sobre tratados em caso de conflito.

### Conceitos
- **Autonomia da Vontade**: Direito das partes a escolher a lei de regência em contratos internacionais
- **Fontes do Direito Internacional Privado**: Convenções internacionais, costume internacional e princípios gerais do direito
- **Lei Nacional vs. Tratados**: A lei nacional prevalece sobre tratados em caso de conflito

### Referências legais
- Art. 102 da Lei nº 9.868/1998
- Súmula 346 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Conflito entre tratado e lei nacional

### Dicas de prova
- Entenda a autonomia da vontade e sua aplicação no direito internacional privado
- Conheça as fontes do direito internacional privado e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.400 (2)", "page_number": 400, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 da Lei nº 9.868/1998", "Súmula 346 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conflito entre tratado e lei nacional"], "confidence": 0.8, "extracted_at": "2026-05-31T04:44:37.219557+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=400", "doc_key": "16f429fa003f29ad3ee6d65a8a308ca9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ceec0cc79a7358c4e6ca25217007421dcd07bcbfcf37c11a1c7af6444e6fe106'),
  ('cpiuris2025::64f1d9e8e34ace42c39fb3bed206d962', 'doutrina', 'cp_iuris', 'Direitos Internacional — Auxílio Direto e Homologação de Sentenças Estrangeiras', '## Auxílio Direto e Homologação de Sentenças Estrangeiras

Questões sobre auxílio direto e homologação de sentenças estrangeiras, destacando as regras e limites para o pedido e a execução dessas medidas.

### Conceitos
- **Auxílio Direto**: Procedimento jurisdicional que permite ao Estado requerente obter informações sobre o ordenamento jurídico e processos administrativos ou jurisdicionais estrangeiros.
- **Homologação de Sentenças Estrangeiras**: Processo pelo qual a sentença estrangeira é reconhecida e executada no território brasileiro, com as devidas ressalvas legais.

