  ('cpiuris2025::ab3f958cf0cb8fa259ff343cf3dbcc03', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica Internacional', '## Cooperação Jurídica Internacional

Resumo do texto sobre cooperação jurídica internacional em diferentes contextos.

### Conceitos
- **Cooperação Jurídica Internacional**: Relação entre os Estados e suas entidades, para a realização de procedimentos judiciais ou administrativos.
- **Assistência Jurídica Internacional Passiva**: Ação do Estado requerente em favor de um Estado receptor, com o objetivo de obter a cooperação jurídica internacional.
- **Cooperação Jurídica Internacional em Matéria Penal**: Transferência de sentenciados, por seu cunho humanitário, exige anuência dos Estados envolvidos.

### Referências legais
- Art. 87 da Lei nº 9.472/1997 (Código de Processo Civil)
- Súmula 272 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Cooperação Jurídica Internacional

### Dicas de prova
