Requerimento de homologação de sentença penal estrangeira que reconhece o perdimento de imóvel brasileiro como produto de crime de lavagem de dinheiro, bem como a aplicabilidade da litispendência internacional em ações intentadas no Brasil e no exterior.

### Conceitos
- **Homologação**: Requerimento de homologação de sentença penal estrangeira
- **Litispendência internacional**: Impedimento que o juiz brasileiro dê curso à ação intentada no Brasil se a questão já tiver sido submetida a juiz estrangeiro

