  ('cpiuris2025::bb8e2592109dd45fdffa2e11aa0678f9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Autenticação de documentos internacionais', '## Autenticação de documentos internacionais

Para ser autenticada, uma documentação internacional deve estar acompanhada de tradução e ter sido proferida por um órgão colegiado ou tribunal, com as partes citadas adequadamente.

### Conceitos
- **Autenticação**: processo pelo qual se confirma a autenticidade de uma documentação internacional
- **Tradução juramentada**: tradução de um documento internacional que pode ser juramentada para sua autenticidade
- **Revelia**: figura jurídica em que uma parte não é citada em um processo

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da autenticação de documentos internacionais e como ela afeta a validade de uma negociação.
