  ('cpiuris2025::36db412566afeeac5f203a20b550d666', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica Internacional', '## Cooperação Jurídica Internacional

A cooperação jurídica internacional é regida por tratados ao qual o Brasil faz parte e observa as regras de autoridade central, igualdade de tratamento e publicidade processual.

### Conceitos
- **Autoridade Central**: Entidade responsável pela recepção e transmissão dos pedidos de cooperação.
- **Igualdade de Tratamento**: Assegurar o acesso igual para nacionais e estrangeiros ao acesso à justiça e à tramitação dos processos.
- **Publicidade Processual**: Exceção para hipóteses de sigilo previstas na legislação brasileira.
- **Obrigatoriedade da Transmissão**: A transmissão de informações a autoridades estrangeiras é obrigatória.

### Referências legais
- Art. 340 do Código de Processo Civil
- Regimento Interno do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- Tema repetitivo da cooperação jurídica internacional

### Dicas de prova
- Distinção entre autoridade central e outras autoridades competentes.
- Requisitos para homologação de sentença estrangeira no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.402 (1)", "page_number": 402, "discipline": "Direitos Internacional", "legal_refs": ["Art. 340 do Código de Processo Civil", "Regimento Interno do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "Tema repetitivo da cooperação jurídica internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T04:47:08.651327+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=402", "doc_key": "36db412566afeeac5f203a20b550d666"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '36cc35ad34ab15163de71603fac2446820cf8c0ee98320ab51792976179375cc'),
  ('cpiuris2025::560b6eeed555f6e278fcd5c94f330329', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação de Sentença Estrangeira', '## Homologação de Sentença Estrangeira

A homologação de sentença estrangeira é regulamentada pelo Código de Processo Civil e requer a autenticação pela autoridade consular brasileira. A sentença não pode ser homologada se houver inadimplemento de obrigações decorrentes dela.

### Conceitos
- **Homologação de Sentença Estrangeira**: Procedimento pelo qual a sentença estrangeira é reconhecida e executada no Brasil
- **Autenticação**: Ato de verificar a autenticidade de documentos, como a sentença estrangeira
- **Autoridade Consular**: Entidade responsável pela autenticação da sentença estrangeira no Brasil

### Referências legais
- Art. 84 do Código de Processo Civil
- Súmula 246 do STJ

### Jurisprudência
- RE 123456
- Súmula 246/STJ

### Dicas de prova
- Diferenciar entre homologação e autenticação
- Conhecer a autoridade responsável pela autenticação da sentença estrangeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.403 (2)", "page_number": 403, "discipline": "Direitos Internacional", "legal_refs": ["Art. 84 do Código de Processo Civil", "Súmula 246 do STJ"], "jurisprudence": ["RE 123456", "Súmula 246/STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T04:48:33.257500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=403", "doc_key": "560b6eeed555f6e278fcd5c94f330329"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ad93272855b4eec86ead66f312d9e6eccb3255ba930c912c3f1cc35af5c9d954'),
  ('cpiuris2025::c96a81d7f1734db867afd653f045fc3b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação de Sentenças Estrangeiras', '## Homologação de Sentenças Estrangeiras

A homologação de sentenças estrangeiras no Brasil é regulada por leis e convenções internacionais, com requisitos como a soberania nacional, ordem pública e reciprocidade.

### Conceitos
- **Homologação**: Procedimento pelo qual uma sentença estrangeira é reconhecida e executada no Brasil
- **Sentenças Estrangeiras**: Decisões proferidas por tribunais de outros países
- **Soberania Nacional**: Direito do Estado de controlar seus assuntos internos
- **Ordem Pública**: Bom comportamento social e ético
- **Reciprocidade**: Princípio segundo o qual os Estados reconhecem as sentenças de outros países

### Referências legais
- Art. 85 da Lei nº 9.472/1997
- Convenção de Nova Iorque sobre Cobrança de Alimentos no Estrangeiro

### Jurisprudência
- Súmula 347/2015 STJ
- RE 123456

### Dicas de prova
- Reconhecer a competência do tribunal estrangeiro
