  ('cpiuris2025::d6d1c8236df62cd384aae489cad5014e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito Internacional Privado', '## Direito Internacional Privado

Exame de Direito Internacional Privado, com questões e respostas.

### Conceitos
- **Direito Internacional Privado**: Ramo do direito que regula as relações entre estados e pessoas físicas ou jurídicas em diferentes países.
- **Exame**: Avaliação de conhecimento em um determinado assunto.
- **Questões**: Perguntas apresentadas no exame para avaliar o conhecimento do candidato.
- **Respostas**: Explicações corretas ou incorretas às questões apresentadas.

### Referências legais
- Art. 5 da Convenção de Viena sobre Direito dos Tratados
- Súmula 342 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Direito Internacional Privado

### Dicas de prova
- Pergunte-se se a questão está relacionada ao direito internacional privado.
- Verifique se a resposta está de acordo com as regras do direito internacional privado.
- Não se esqueça das exceções e hipóteses específicas do direito internacional privado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.404", "page_number": 404, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 da Convenção de Viena sobre Direito dos Tratados", "Súmula 342 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Direito Internacional Privado"], "confidence": 0.8, "extracted_at": "2026-05-31T04:49:10.309882+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=404", "doc_key": "d6d1c8236df62cd384aae489cad5014e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '47dd7d2d9403d2e78f31eb5feae37f0468528911aec7056fa57c2bd5da6cd49d'),
