  ('cpiuris2025::5763a5e1866fc98a2aecb61b774864ce', 'doutrina', 'cp_iuris', 'Direitos Internacional — Índices de ações e procedimentos', '## Índices de ações e procedimentos

Lista de índices de ações civis, rescisórias, acordos extradição, ações diretas de inconstitucionalidade, agravo, constituições, decretos, emendas, homologação de decisão estrangeira, lei complementar, leis e recursos extraordinários.

### Conceitos
- **AÇÃO CÍVEL ORIGINÁRIA**: ação civil que busca resolver um litígio
- **ACORDÃO EXTRADIÇÃO**: acordo entre países para a extradição de uma pessoa
- **AÇÃO DIRETA DE INCONSTITUCIONALIDADE**: ação que busca anular uma lei ou ato do governo
- **AGRAVO**: recurso apresentado para revisar uma decisão
- **CONSTITUIÇÕES BRASILEIRAS**: constituição do Brasil
- **DECRETOS**: decisões do governo brasileiro
- **EMENDAS**: mudanças introduzidas em uma lei ou constituição
- **HOMOLOGAÇÃO DE DECISÃO ESTRANGEIRA**: homologação de decisão estrangeira no Brasil

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- Decreto n.º 7.030/2009
- Decreto n.º 7.107/2010
- Decreto n.º 9.199/2017
- Decreto n.º 4.388/2002
- Decreto n.º 50.215/1961
- Decreto nº 154/1991
- Decreto n.º 10.214/2020

### Jurisprudência
- RE 578.543
- RE 349.703
- RE 627.280
- RE 954858
- RE 597368
- RE 1034840

### Dicas de prova
- Entenda a estrutura dos índices de ações e procedimentos.
- Conheça as diferentes espécies de ações e recursos.
- Identifique as leis e constituições relevantes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.406", "page_number": 406, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF", "Decreto n.º 7.030/2009", "Decreto n.º 7.107/2010", "Decreto n.º 9.199/2017", "Decreto n.º 4.388/2002", "Decreto n.º 50.215/1961", "Decreto nº 154/1991", "Decreto n.º 10.214/2020"], "jurisprudence": ["RE 578.543", "RE 349.703", "RE 627.280", "RE 954858", "RE 597368", "RE 1034840"], "confidence": 0.8, "extracted_at": "2026-05-31T04:53:21.585341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=406", "doc_key": "5763a5e1866fc98a2aecb61b774864ce"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fd2fba5f1342f83d96b8743f0a5b7fe73ad2e8be10e16387654d08b22cae9b4f'),
  ('cpiuris2025::8dfc7d6ee7b4f18be2d0e88df87ec5b1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Delimitações marítimas e questões territoriais', '## Delimitações marítimas e questões territoriais

