  ('cpiuris2025::d805722560366fb6ced4b755fb4ec4ca', 'doutrina', 'cp_iuris', 'Direitos Internacional — Introdução ao Direito Internacional', '## Introdução ao Direito Internacional

Resumo objetivo: Este texto apresenta uma introdução geral ao direito internacional, destacando sua importância e características principais.

### Conceitos
- **Direito Internacional**: O conjunto de regras que regem as relações entre os Estados e outras entidades internacionais.
- **Relações Internacionais**: As interações entre os Estados e outras entidades, como organizações internacionais ou indivíduos.
- **Sobrestação**: A ação de um Estado em relação a outro Estado, com o objetivo de obter uma decisão ou ato do outro Estado.
- **Reconhecimento**: O reconhecimento de um Estado por outro, que envolve a aceitação da soberania e autoridade desse Estado.
- **Apoio**: A assistência ou cooperação de um Estado em relação a outro, com o objetivo de ajudar esse último.
- **Sobriedade**: O direito de um Estado de não ser obrigado a realizar uma ação que não seja necessária para sua segurança ou interesse.
- **Imunidade**: O direito de um Estado de não ser processado em outro Estado por ações realizadas dentro do seu território.
- **Competência**: A capacidade de um Estado de decidir sobre uma questão ou caso que envolve relações com outros Estados.

### Referências legais
- Art. 1 da Convenção de Viena sobre Relações de Tratados
- Súmula 441 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência dos Tribunais Internacionais

### Dicas de prova
- Entenda a definição de direito internacional e suas características principais.
- Conheça as diferentes formas de relações internacionais, como reconhecimento e apoio.
- Aprenda sobre a soberestação e sua importância nos relações internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.2", "page_number": 2, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 da Convenção de Viena sobre Relações de Tratados", "Súmula 441 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência dos Tribunais Internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T05:00:22.859808+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=2", "doc_key": "d805722560366fb6ced4b755fb4ec4ca"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f84c00ff6d0d03a6a828b4928808395a04b9641a013cc682f92974df7902941b'),
  ('cpiuris2025::110ecc6384f9c4d35c3015a06961ab79', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição e Classificação dos costumes internacionais', '## Definição e Classificação dos costumes internacionais

