  ('cpiuris2025::f65c09fe77a37c4e010d000a4ff04667', 'doutrina', 'cp_iuris', 'Direitos Internacional — Condições de validade e outros aspectos dos tratados internacionais', '## Condições de validade e outros aspectos dos tratados internacionais

