  ('cpiuris2025::df78d4b87ab1d01f745264ad1011b065', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação', '## Classificação

A classificação é um aspecto fundamental dos tratados internacionais, sendo objeto de estudo neste capítulo.

### Conceitos
- **Tratado**: Acordo internacional que tem por objetivo a cooperação ou a regulamentação de assuntos específicos.
- **Convenção**: Acordo internacional que tem por objetivo a criação de um direito subjetivo para o Estado ou pessoa jurídica.
- **Tratado bilateral**: Acordo internacional entre dois Estados.
- **Tratado multilateral**: Acordo internacional entre mais de dois Estados.
- **Tratado unilateral**: Acordo internacional assinado por um Estado, mas não obrigando outros Estados a adotá-lo.
- **Convenção bilateral**: Acordo internacional entre dois Estados, com natureza de convenção.
- **Convenção multilateral**: Acordo internacional assinado por mais de dois Estados, com natureza de convenção.
- **Tratado adesivo**: Tratado que não cria direito subjetivo para o Estado ou pessoa jurídica.

### Referências legais
- Art. 23 da Convenção de Viena sobre Tratados
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre tratado e convenção.
- Conheça as diferentes espécies de tratados internacionais.
- A classificação dos tratados é fundamental para sua interpretação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Tratados", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T05:02:36.337829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=4", "doc_key": "df78d4b87ab1d01f745264ad1011b065"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '767ecfbda2ca0a5df8d8cb3111b1cd6c366d322c37c8741e105df21ec993bd54'),
  ('cpiuris2025::3249ce01baf7fda558fe5a7937a70c97', 'doutrina', 'cp_iuris', 'Direitos Internacional — Nacionalidade e Relações Diplomáticas', '## Nacionalidade e Relações Diplomáticas

Trecho aborda conceitos de nacionalidade, quase-nacionalidade e relações diplomáticas.

### Conceitos
- **nacionalidade**: status jurídico de uma pessoa em relação a um Estado
- **quase-nacionalidade**: conceito que se refere aos portugueses equiparados em termos de direitos e obrigações internacionais
- **relações diplomáticas**: interação entre Estados soberanos

### Referências legais
- Art. 13 da Convenção de Viena sobre Relações Diplomáticas

### Dicas de prova
- Entenda a distinção entre nacionalidade e quase-nacionalidade.
- Conheça os elementos essenciais das relações diplomáticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direitos Internacional", "legal_refs": ["Art. 13 da Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:03:28.188322+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=5", "doc_key": "3249ce01baf7fda558fe5a7937a70c97"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a013be383967bb2376893d5d20aeb3c23e2c02a01b1d35a3ac44d897a3fd07fe'),
  ('cpiuris2025::fd02d920005f40e1a4393c3b2e0443ed', 'doutrina', 'cp_iuris', 'Direitos Internacional — Relações consulares', '## Relações consulares

Tratamento das relações entre o Estado e a embaixada ou consulado do país estrangeiro.

### Conceitos
- **Relação Consular**: Conexão estabelecida entre um Estado e uma embaixada ou consulado de outro Estado.
- **Consulado**: Missão diplomática do país estrangeiro no território de outro país.

### Referências legais
- Art. 38 da Convenção de Viena sobre Relações Diplomáticas

### Dicas de prova
- Entenda a definição de relação consular e o papel das embaixadas e consulados nos relações internacionais.
- Conheça as competências e responsabilidades dos consulados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 da Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:03:35.977942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=6", "doc_key": "fd02d920005f40e1a4393c3b2e0443ed"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '315ec81dbe757202b9dfc914689fdc48521f579f430bffa565f9c75ea66f6b60'),
  ('cpiuris2025::ac110d5d7ab32ec0c7ffa4582c39ac4a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Solução de Controvérsias Internacionais', '## Solução de Controvérsias Internacionais

Discute os meios pacíficos e não pacíficos de solução de controvérsias internacionais, incluindo negociações diplomáticas, consultas, inquérito, bons ofícios, mediação, conciliação, arbitragem e soluções judiciais.

### Conceitos
- **Negociações Diplomáticas**: Negociações entre os Estados para resolver controvérsias
- **Consultas**: Comunicação direta entre os Estados para obter informações sobre uma situação
- **Inquérito**: Investigação de uma situação para coletar informações
- **Bons ofícios**: Solicitação de ajuda ou orientação por um Estado a outro
- **Mediação**: Processo de negociação entre as partes com a ajuda de um terceiro imparcial
- **Conciliação**: Processo de negociação para resolver uma disputa sem recorrer à força
- **Arbitragem**: Designação de um juiz ou tribunal para decidir uma disputa
- **Soluções Judiciais**: Decisões de tribunais sobre questões internacionais

### Referências legais
- Art. 36 da Convenção de Viena sobre Relações de Tratado

### Dicas de prova
- Entenda a diferença entre meios pacíficos e não pacíficos de solução de controvérsias
- Conheça os diferentes tipos de consultas internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 da Convenção de Viena sobre Relações de Tratado"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:04:05.921258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=6", "doc_key": "ac110d5d7ab32ec0c7ffa4582c39ac4a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c636151a46ac518e97a17f504a630063034d90164c3e586786013e6aa729b099'),
  ('cpiuris2025::f2360d4828799850c9cf9289b272e5cb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Embargos, Bloqueios e Boicotes em Direito Internacional', '## Embargos, Bloqueios e Boicotes em Direito Internacional

Definições de Embargo, Bloqueio e Boicote no direito internacional, relacionados a medidas tomadas por um Estado contra outro.

### Conceitos
- **Embargo**: Medida adotada pelo governo de um Estado para impor restrições ao comércio ou à atividade econômica de outro Estado.
- **Bloqueio**: Medida adotada pelo governo de um Estado para impedir que a propriedade ou os ativos de outro Estado sejam utilizados em benefício de terceiros.
- **Boicote**: Atitude tomada por uma entidade ou indivíduo para não fornecer serviços ou produtos a outra entidade ou indivíduo.

### Referências legais
- Art. 24 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre as três medidas (embargo, bloqueio e boicote) e entender suas implicações práticas.
- Conhecer a legislação internacional que regula essas medidas (Convenção de Viena, etc.).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direitos Internacional", "legal_refs": ["Art. 24 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T05:06:06.453674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=6", "doc_key": "f2360d4828799850c9cf9289b272e5cb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ccf11018301a92dfcaad271f570a9868ca07578a7edd74bc95abd56326ac5db2'),
  ('cpiuris2025::40ae516ff6a4474e5aff5a2cbf891e28', 'doutrina', 'cp_iuris', 'Direitos Internacional — Uso da Força no Direito Internacional', '## Uso da Força no Direito Internacional

O uso da força no direito internacional é um tema complexo que envolve a legítima defesa, o jus ad bellum e a proibição do uso da força.

### Conceitos
- **Jus Ad Bellum**: Princípio que estabelece as regras para o uso da força em conflitos internacionais
- **Legítima Defesa**: Direito que permite a defesa de um Estado contra uma ameaça iminente e legítima
- **Proibição do Uso da Força**: Princípio que proíbe o uso da força em conflitos internacionais, exceto em casos de legítima defesa

### Referências legais
- Art. 23 da Carta das Nações Unidas

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Uso da Força em Conflitos Internacionais

### Dicas de prova
- Entenda a distinção entre jus ad bellum e legítima defesa
- Conheça as regras do uso da força em conflitos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Carta das Nações Unidas"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Uso da Força em Conflitos Internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T05:06:11.847682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=7", "doc_key": "40ae516ff6a4474e5aff5a2cbf891e28"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '954a57f27ffa33076ef0d0792faf09b66ce84f65cf28348544c2538d99988060'),
  ('cpiuris2025::0ff26eeccc38b4adec38d95be5e91d4c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios Gerais do Direito Penal Internacional', '## Princípios Gerais do Direito Penal Internacional

O capítulo aborda os princípios gerais do direito penal internacional, incluindo a responsabilidade dos agentes do Estado por condutas internacionais e os princípios do processo penal internacional.

### Conceitos
- **Pessoalidade da responsabilidade penal**: A responsabilidade penal é pessoal, o que significa que apenas os indivíduos ou entidades específicas podem ser responsabilizadas por atos internacionais.
- **Princípio da legalidade**: O direito penal internacional deve estar baseado em leis e tratados internacionais, garantindo a justiça e a igualdade para todos os envolvidos.
- **Princípio da presunção de inocência**: O acusado deve ser considerado inocente até que seja provada sua culpabilidade, garantindo o direito à liberdade e à não discriminação.
- **Princípio da imparcialidade do juiz**: O juiz deve ser imparcial e isento de influências pessoais ou políticas, garantindo a justiça e a igualdade para todos os envolvidos.
- **Princípio da igualdade**: Todos os envolvidos no processo penal internacional devem ser tratados de forma igual e sem discriminação, garantindo justiça e equidade.

### Referências legais
- Art. 22 do Estatuto do Direito Penal Internacional

### Dicas de prova
- Entenda a importância da pessoalidade da responsabilidade penal e como ela afeta a responsabilidade dos agentes do Estado.
- Aprenda a distinguir entre o princípio da legalidade e o princípio da imparcialidade do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 do Estatuto do Direito Penal Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:07:04.707374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=7", "doc_key": "0ff26eeccc38b4adec38d95be5e91d4c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '115e0c3ab25166fd1cc0ee51168c6861f29dcbd1839a3c852ad060bd15fd8c0a'),
  ('cpiuris2025::ddf6124510e5309f4225f782736ae703', 'doutrina', 'cp_iuris', 'Direitos Internacional — Estrutura do TPI', '## Estrutura do TPI

Descreve a estrutura do Tribunal Permanente de Investigações (TPI) e sua competência.

### Conceitos
- **TPI**: Tribunal Permanente de Investigações
- **Jurisdição**: Poder de julgar sobre uma questão específica
- **Competência**: Direito para um tribunal decidir sobre uma questão

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a estrutura do TPI e sua competência.
- Pergunte-se se o TPI tem jurisdição em um caso específico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:07:23.508495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=7", "doc_key": "ddf6124510e5309f4225f782736ae703"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '52a13bc8d3f00485865ee75a1035eb896b7f7bf9000cc4e1e663dad9c4691818'),
  ('cpiuris2025::167226c0f103b32ec8481b9c0ec7a9f4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Estrutura da Norma de Direito Internacional', '## Estrutura da Norma de Direito Internacional

Descreve as conexões pessoais, reais, delituais, voluntárias e normativas que compõem a estrutura de uma norma de direito internacional.

### Conceitos
- **Conexão pessoal**: Relação entre o Estado ou pessoa física com o objeto do direito
- **Conexão real**: Relação entre o Estado ou pessoa física com a coisa ou pessoa alheia
- **Conexão delituais**: Relação entre o Estado ou pessoa física com o ato ilícito
- **Conexão voluntárias**: Relação entre o Estado ou pessoa física com a vontade ou decisão de outorgar direitos
- **Conexão normativas**: Relação entre o Estado ou pessoa física com a norma jurídica em si
- **Outros elementos**: Outras características que compõem a estrutura da norma de direito internacional

### Referências legais
- Art. 4 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 342 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Estrutura das normas internacionais

### Dicas de prova
- Entenda a importância das conexões pessoais, reais, delituais, voluntárias e normativas na estrutura de uma norma de direito internacional.
- Conheça as diferenças entre cada tipo de conexão e como elas afetam o direito internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 342 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Estrutura das normas internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T05:08:49.970157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=8", "doc_key": "167226c0f103b32ec8481b9c0ec7a9f4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '69c2336ea5ba83cc7c2e230e7ec63b7f2fd858c7926683e4c0dba2be7776bc8c'),
  ('cpiuris2025::814d32e32dbf0f14c9966dd50ef81084', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito Processual Civil Internacional', '## Direito Processual Civil Internacional

Trata-se de diretrizes sobre o processo civil internacional, incluindo a aplicação do direito estrangeiro, prova dos fatos ocorridos no exterior e competência internacional.

### Conceitos
- **Aplicação do Direito Estrangeiro**: A aplicação do direito estrangeiro em casos internacionais
- **Prova dos fatos ocorridos no exterior**: Regras para a prova de fatos ocorridos fora do país
- **Competência internacional**: Regras para determinar a competência de um tribunal em casos internacionais

### Referências legais
- Art. 92 da LDO Processual
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Tema repetitivo cooperação internacional

### Dicas de prova
- Entenda a aplicação do direito estrangeiro em casos internacionais
- Conheça as regras para a prova de fatos ocorridos no exterior
- Aprenda sobre a competência internacional e suas regras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direitos Internacional", "legal_refs": ["Art. 92 da LDO Processual", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo cooperação internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T05:09:01.385452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=8", "doc_key": "814d32e32dbf0f14c9966dd50ef81084"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e8d29a888777798822b10a66b8762f876136dfc132022656f3d8cdd73c819f24'),
  ('cpiuris2025::3e13d04201738d68652e70c546dc7022', 'doutrina', 'cp_iuris', 'Direito Internacional — Noções Históricas do Direito Internacional', '## Noções Históricas do Direito Internacional

O direito internacional público surgiu na Idade Moderna, com a Paz de Westfália em 1648, reconhecendo elementos do Estado moderno e princípio da igualdade formal entre os Estados.

### Conceitos
- **Direito Internacional Público**: disciplina jurídica subsidiária ao poder absolutista dos soberanos europeus e do Estado nacional moderno
- **Paz de Westfália**: data de nascimento do Direito Internacional Moderno, em 24 de outubro de 1648
- **Elementos do Estado Moderno**: território, povo e soberania
- **Soberania**: divisão em monopólio da produção do direito e uso de força, em âmbito interno e externo

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância da Paz de Westfália no surgimento do Direito Internacional Moderno
- Conheça os elementos do Estado Moderno e o princípio da igualdade formal entre os Estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direito Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T05:09:48.001148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=9", "doc_key": "3e13d04201738d68652e70c546dc7022"}'::jsonb, '{"materia": "Direito Internacional"}'::jsonb, 'cp_iuris_2025', '8e3bdd7508f052b554411014a0b5dd1c1d9d1737c9ab6aecec8ce8e43e80242f'),
  ('cpiuris2025::03ad0882d6935bba0851286454783bfb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Origem e conceituação do Direito Internacional', '## Origem e conceituação do Direito Internacional

O termo Direito Internacional foi cunhado por Jeremy Bentham em 1780, enquanto os termos Direito das Gentes e Direito entre as Nações foram utilizados anteriormente. A definição da disciplina não é um consenso na doutrina.

### Conceitos
- **Direito Internacional**: Conceito jurídico que regula as relações entre os Estados
- **Direito das Gentes**: Antigo termo utilizado para descrever o direito internacional
- **Direito entre as Nações**: Outro termo utilizado anteriormente para descrever o direito internacional

### Referências legais
- Art. 9 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: conceituação do direito internacional

### Dicas de prova
- Entenda a origem e evolução dos termos utilizados para descrever o direito internacional
- Conheça os critérios utilizados para conceituar a disciplina do direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direitos Internacional", "legal_refs": ["Art. 9 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: conceituação do direito internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T05:10:56.424578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=9", "doc_key": "03ad0882d6935bba0851286454783bfb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '79402c47b8fe01f070f615ebd20f3653fc58d190b7657cfc37987163cca7fd89'),
  ('cpiuris2025::b483fa3e64ec611ae1df32ee503f3ba1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição do Direito Internacional', '## Definição do Direito Internacional

A definição do Direito Internacional é objeto de debate entre os juristas, com quatro critérios principais: o sistema jurídico autônomo; a crítica à existência de outros entes além dos Estados; a definição do Direito Internacional como conjunto de normas jurídicas que rege a comunidade internacional; e a definição do Direito Internacional como resultado de um processo de formação específico.

### Conceitos
- **Sistema jurídico autônomo**: O sistema jurídico autônomo é uma forma de conceituação que define o Direito Internacional como um sistema jurídico independente e autônomo.
- **Crítica à existência de outros entes além dos Estados**: A crítica feita por Jorge Miranda é a existência de outros entes, além dos Estados, que compõem a ''vida jurídica internacional''.
- **Definição do Direito Internacional como conjunto de normas jurídicas**: O Direito Internacional é definido como o conjunto de normas jurídicas que rege a comunidade internacional.
- **Processo de formação das normas**: A definição do Direito Internacional também pode ser feita considerando o processo de formação das suas normas, distinto das normas produzidas no Direito interno.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a definição do sistema jurídico autônomo e sua importância na conceituação do Direito Internacional.
- Distinção entre os critérios de definição do Direito Internacional: sistema jurídico autônomo, crítica à existência de outros entes além dos Estados, definição como conjunto de normas jurídicas e processo de formação das normas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:12:14.972214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=10", "doc_key": "b483fa3e64ec611ae1df32ee503f3ba1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '496e2f574da19fa36aa6bf31557e84ef1b4e6f3a26743e15cf71a3fbb011bc4f'),
  ('cpiuris2025::364f46fe0acb57033b57a243f7096411', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceituação do Direito Internacional', '## Conceituação do Direito Internacional

O Direito Internacional é definido como conjunto de normas que regem os sujeitos internacionais, buscando manter a paz e justiça internacional, além de promover o desenvolvimento dos povos.

### Conceitos
- **Direito Internacional**: conjunto de normas que regem os sujeitos internacionais
- **Sociedade Internacional**: conjunto de Estados e outros atores internacionais
- **Processo**: fenômeno que antecede a norma internacional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda as diferentes conceituações do Direito Internacional (conjunto de normas, direito da sociedade internacional e processo).
- Análise a discussão doutrinária sobre a existência de uma comunidade internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:12:39.269976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=11", "doc_key": "364f46fe0acb57033b57a243f7096411"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd3a94b667f524fd7a17d80f79812cd4bbe4778f464159f81006d29cd7cd1b437'),
  ('cpiuris2025::3f37ba39b0bc227c2c92f282c793d710', 'doutrina', 'cp_iuris', 'Direitos Internacional — Critérios para definição do Direito Internacional', '## Critérios para definição do Direito Internacional

A definição do Direito Internacional é problemática, pois não há um critério único que a aborde. Os cinco critérios são: formalidade, fonte normativa, existência de uma comunidade internacional, organização pelo Estado e ideologia/meta-jurídica.

### Conceitos
- **Critérios para definição do Direito Internacional**: A falta de um critério único que aborde a noção do Direito Internacional.
- **Fonte normativa**: O quinto critério, que se refere à fonte de produção normativa da comunidade internacional.
- **Comunidade internacional**: A existência de uma comunidade internacional é considerada um critério para o Direito Internacional.
- **Organização pelo Estado**: O direito interno é organizado pelo Estado, em contraste com o direito internacional.
- **Ideologia/meta-jurídica**: A visão ideológica ou metajurídica do conceito de comunidade internacional.
- **Atos internos**: Atos unilaterais realizados pelo Estado que são reconhecidos como fontes do Direito Internacional.
- **Diversidade das comunidades**: A existência de várias comunidades internacionais, regionais e setoriais.
- **Conceito de comunidade**: Uma visão ideológica ou metajurídica do conceito de comunidade internacional.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a complexidade dos critérios para definição do Direito Internacional.
- Aprenda a distinguir entre fonte normativa e comunidade internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:12:57.738139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=10", "doc_key": "3f37ba39b0bc227c2c92f282c793d710"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a269a224ada324d3f1ed45c2ff4759fa562939033d5e0323984c06a517187720'),
  ('cpiuris2025::455e2de320d568820fa4d1cb962b5ede', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sociedade Internacional e Relações Internacionais', '## Sociedade Internacional e Relações Internacionais

A sociedade internacional é aberta, não tendo um número determinado de atores que intervêm nas relações internacionais.

### Conceitos
- **Sociedade Internacional**: aberta e dinâmica
- **Relações Internacionais**: interação entre estados e outras entidades

### Referências legais
- Portela, S. (2015)

### Dicas de prova
- Entenda a abordagem de Sidney Guerra sobre a sociedade internacional.
- Identifique o autor citado em Portela (2015).
- Diferencie entre pontos de vista econômico, social e cultural.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direitos Internacional", "legal_refs": ["Portela, S. (2015)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:14:10.230897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=12", "doc_key": "455e2de320d568820fa4d1cb962b5ede"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e39eb3af7d9db913f15a0b65866939cb9b196033c5f61480ff5f8f27fa6d7d81'),
  ('cpiuris2025::d0bbc8cee72658f77534ddb2e037c3d9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Comunidade Internacional', '## Comunidade Internacional

A comunidade internacional é um termo utilizado para descrever a relação entre os países, considerando fatores como identidade, laços culturais e históricos comuns. A doutrina aponta diferenças entre sinônimos como ''sociedade internacional'' e ''comunidade internacional''.

### Conceitos
- **Comunidade Internacional**: relação entre países considerando fatores como identidade, laços culturais e históricos comuns
- **Sociedade Internacional**: relação entre países sem vínculos espontâneos ou de caráter subjetivo
- **Vínculos Espontâneos**: fatores como identidade, laços culturais e emocionais comuns dos membros

### Referências legais
- Art. 53 da Convenção de Viena sobre Tratados

### Dicas de prova
- Entenda a diferença entre ''comunidade internacional'' e ''sociedade internacional''.
- Aprenda os fatores que caracterizam uma comunidade internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da Convenção de Viena sobre Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:14:22.031729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=11", "doc_key": "d0bbc8cee72658f77534ddb2e037c3d9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5a73520ddf44ae96e8ab275a74cf14de2279244eec578a94c1f1dccaa239df1a'),
  ('cpiuris2025::fdaf722d0712f32fec13d3d917c7fbbb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Diferenciação entre Comunidade e Sociedade', '## Diferenciação entre Comunidade e Sociedade

Comunidade: unidade harmônica com vontade como elemento promotor; Sociedade: descentralização horizontal, paritária, universal e heterogênea.

### Conceitos
- **Vontade**: elemento que promove a aproximação entre os membros de uma comunidade
- **Decisão**: ato volitivo que busca atingir objetivos comuns em uma sociedade
- **Fins**: objetivos comuns buscados por membros de uma sociedade
- **Unidade Harmônica**: característica da comunidade, onde os membros permanecem unidos apesar de fatores buscarem a sua separação
- **Decentralização Horizontal**: característica da sociedade internacional, onde os Estados são organizados de forma horizontal
- **Paritária**: característica da sociedade internacional, onde não existe um ente superior e a soberania de cada Estado deve ser compatibilizada
- **Universalidade**: característica da sociedade internacional, que abrange todo o globo
- **Heterogeneidade**: característica da sociedade internacional, que inclui distintos níveis de interação dos seus membros

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da vontade na diferenciação entre Comunidade e Sociedade
- Conheça as características da sociedade internacional, como descentralização horizontal e paritária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:15:40.948149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=12", "doc_key": "fdaf722d0712f32fec13d3d917c7fbbb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '810bb7102112cfd563f8e0f58c33ded0ffa2ed968c06e0deb0e2bd97aca034f2'),
  ('cpiuris2025::d454f7d280d140012b1768b4c065b8e4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Histórico das Normas Internacionais', '## Histórico das Normas Internacionais

O autor defende que a ideia de normas internacionais existia na Grécia antiga e era superior à época de Roma.

### Conceitos
- **Sociedade internacional**: Descentralizada, ausente um ente central detentor do poder
- **Paritária**: Não há hierarquia entre seus membros
- **Universal**: Abrange todo o globo terrrestre
- **Heterogênea**: Seus membros são diferentes do ponto de vista econômico, social e cultural
- **Aberta**: Não há um número predefinido de membros

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Pergunte sobre a definição de Sociedade internacional e suas características.
- Entenda o conceito de Paritária e como ela se diferencia de outras formas de sociedade internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:15:55.558812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=13", "doc_key": "d454f7d280d140012b1768b4c065b8e4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bd51b037761bb1912dab6189021570ee24494ea997bbefd5eee16c6f9660e7c7'),
  ('cpiuris2025::6227f270dd0560ef663a468dd5c654e0', 'doutrina', 'cp_iuris', 'Direitos Internacional — O Direito Internacional é um fenômeno jurídico?', '## O Direito Internacional é um fenômeno jurídico?

A questão se refere à natureza do direito internacional, com autores divergentes sobre sua existência e normatividade.

### Conceitos
- **Fenômeno jurídico**: Entidade ou processo que é objeto de estudo jurídico
- **Autoridade soberana**: Poder absoluto em um território
- **Jus naturalista**: Teoria que afirma a existência de leis naturais inatas à humanidade
- **Realismo jurídico**: Corrente teórica que nega a normatividade do direito internacional
- **Poder comum**: Poder soberano compartilhado por vários entes
- **Lei**: Regra geral que regula comportamento humano
- **Injustiça**: Falta de justiça ou equidade em uma situação
- **Neo-hegelianismo**: Corrente teórica que afirma a existência de um sistema filosófico holístico

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a definição de fenômeno jurídico e sua aplicação ao direito internacional
- Análise crítica das teorias sobre autoridade soberana e jus naturalista
- Conheça as principais correntes teóricas do realismo jurídico e seu impacto no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T05:16:16.990506+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=13", "doc_key": "6227f270dd0560ef663a468dd5c654e0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c664c573f07016e9ea1e10e6ceef65d04162c2448850cf393db92913c7092f05'),
  ('cpiuris2025::7bfe2df52e4c24fa98d886c80eb95a59', 'doutrina', 'cp_iuris', 'Direitos Internacional — Distinção entre Direito Internacional Público e Privado', '## Distinção entre Direito Internacional Público e Privado

A distinção clássica entre direito internacional público e privado se dá pela presença do Estado nos polos da relação jurídica, mas essa distinção não é isenta de críticas.

### Conceitos
- **Direito Internacional Público**: regulara as relações entre os Estados
- **Direito Internacional Privado**: regula as relações entre particulares
- **Ordem Pública**: natureza de normas de Direito Internacional Privado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre direito internacional público e privado.
- Conheça a crítica à distinção clássica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:18:01.706991+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=14", "doc_key": "7bfe2df52e4c24fa98d886c80eb95a59"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd8eb39e622277bec0f72b74c2b353eb1990d0b63069b353fcb7ad7459a99ddc5'),
  ('cpiuris2025::af7e3b3254d669737de977d31d286834', 'doutrina', 'cp_iuris', 'Direitos Internacional — Relação entre Direito Internacional Público e Direitos Estatais', '## Relação entre Direito Internacional Público e Direitos Estatais

A questão da relação entre o Direito Internacional Público e os Direitos Estatais é um tema polêmico que envolve discussões sobre hierarquia e solução de antinomias entre normas de âmbitos distintos.

### Conceitos
- **Direito Internacional Público**: Regulamenta relações entre Estados
- **Direito Internacional Privado**: Regulamenta relações mediatas entre Estados
- **Teoria Monista**: Acredita que o Direito Internacional e o Direito Interno são sistemas jurídicos unitários
- **Teoria Dualista**: Acredita que o Direito Internacional e o Direito Interno são sistemas jurídicos distintos
- **Soberania**: O poder absoluto de um Estado sobre seu território e população
- **Vontade Coletiva**: A vontade conjunta dos Estados que compõem a sociedade internacional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Internacional

### Dicas de prova
- Entenda a distinção entre Teoria Monista e Teoria Dualista
- Conheça o conceito de Soberania e Vontade Coletiva
- Aprenda a aplicar as teorias ao caso concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T05:19:12.302518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=15", "doc_key": "af7e3b3254d669737de977d31d286834"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ded8d1ab4098563b8d637eea5ba3575797dba957ba82caf3b124fcea58e056e2'),
  ('cpiuris2025::dcc029697232c7d60214f1c911268f31', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito Internacional como instrumento de regulamentação das relações internacionais', '## Direito Internacional como instrumento de regulamentação das relações internacionais

O direito internacional se mostrou efetivo na regulamentação das relações internacionais, com a redução de conflitos e a criação de mecanismos de solução de controvérsia.

### Conceitos
- **Direito Internacional**: Regulamento das relações internacionais
- **Sociedade Internacional**: Comunidade de Estados e organizações que operam no âmbito internacional
- **Normas Internacionais**: Regras e acordos estabelecidos por Estados e organizações internacionais
- **Mecanismos de Solução de Controvérsia**: Instituições e procedimentos que resolvem disputas entre Estados e organizações internacionais
- **Direito Internacional Privado**: Regulamento das relações entre indivíduos em âmbito internacional

### Referências legais
- Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 342 do STF

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Direito Internacional como instrumento de regulamentação das relações internacionais''}

### Dicas de prova
- Entenda a distinção entre Direito Internacional Público e Privado.
- Conheça as normas e mecanismos de solução de controvérsia no âmbito internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 342 do STF"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Direito Internacional como instrumento de regulamentação das relações internacionais''}"], "confidence": 0.8, "extracted_at": "2026-05-31T05:19:12.303976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=14", "doc_key": "dcc029697232c7d60214f1c911268f31"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ab39334a774abb2499997b9f16f778a1fb6316904276954be08438fd2b3365b1'),
  ('cpiuris2025::84f692e9588ccbc81d5d24a76f9aa12f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria Dualista de Triepel', '## Teoria Dualista de Triepel

A teoria dualista de Triepel afirma que não há conflito entre normas do direito internacional e do direito interno, pois a natureza da obrigação é distinta.

### Conceitos
- **Teoria Dualista**: afirma que não há conflito entre normas do direito internacional e do direito interno
- **Norma**: regra ou princípio jurídico
- **Ordem Internacional**: conjunto de regras e princípios jurídicos que regem as relações entre os Estados
- **Ordem Interna**: conjunto de regras e princípios jurídicos que regem as relações dentro do Estado
- **Vontade Geral dos Estados**: coletividade das vontades dos Estados em relação a uma questão específica

### Referências legais
- Art. 96 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 387/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Teoria Dualista de Triepel

### Dicas de prova
- Entenda a distinção entre ordem internacional e interna
- Conheça a teoria dualista de Triepel e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direitos Internacional", "legal_refs": ["Art. 96 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 387/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Teoria Dualista de Triepel"], "confidence": 0.8, "extracted_at": "2026-05-31T05:20:20.026176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=15", "doc_key": "84f692e9588ccbc81d5d24a76f9aa12f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b5d04247a8cf19d0f34217164ddb5aeffb851e35c4f1841cb32ce941792bfce9'),
  ('cpiuris2025::37206b816c7e2a278c9ebbc5f745ca91', 'doutrina', 'cp_iuris', 'Direitos Internacional — Monismo no Direito Internacional', '## Monismo no Direito Internacional

A doutrina sobre o monismo se divide em três correntes: nacionalista, internacionalista e dialógico/moderado.

### Conceitos
- **Monismo Nacionalista**: Defende que a vontade do Estado prepondera sobre as normas do direito internacional
- **Monismo Internacionalista**: Não encontrado em texto
- **Monismo Dialógico/Moderado**: Defende um equilíbrio entre o Estado e o direito internacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre as três correntes de monismo
- Identifique a definição de cada corrente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:20:46.428421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=16", "doc_key": "37206b816c7e2a278c9ebbc5f745ca91"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a2e7223213b3f34446f3d0587f9db431296f46c8d5e0bcb5c86b879aa70d4b21'),
  ('cpiuris2025::e809e5b355008b365155bf6532b1eee7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Relação entre ordemamento internacional e nacional', '## Relação entre ordemamento internacional e nacional

A relação entre ordensamentos internacionais e nacionais é estabelecida pela vontade coletiva dos Estados, com a norma internacional prevalecendo em face de uma norma nacional em demandas internas.

### Conceitos
- **Vontade coletiva**: A vontade coletiva dos Estados é a fonte material do ordenamento internacional.
- **Pluralismo institucionalista**: Teoria que admite a existência de múltiplos ordenamentos jurídicos que se interrelacionam.
- **Monismo**: Teoria que considera o mundo jurídico como unitário, com várias fontes de produção normativa.
- **Antinomia**: Conflito entre normas de ordensamentos distintos.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a relação entre vontade coletiva e normas internacionais.
- Conheça as teorias de pluralismo institucionalista e monismo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:21:28.597629+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=16", "doc_key": "e809e5b355008b365155bf6532b1eee7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b475863687d5d0d0fa6d9a5da0fbfe15243895f02a74c1785140de657e680fc4'),
  ('cpiuris2025::984d9210a8f3bd8d754959c9578587d5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prevalência de normas internacionais em constituições', '## Prevalência de normas internacionais em constituições

A prevalência de normas internacionais em constituições é uma questão política que não impede a responsabilização pelo descumprimento da norma internacional.

### Conceitos
- **Prevalência**: ordem em que as normas são aplicadas
- **Norma internacional**: regras estabelecidas por tratados ou convenções internacionais
- **Responsabilização**: obrigação de cumprir com uma norma

### Referências legais
- Art. 59 da Convenção das Nações Unidas sobre Direitos Humanos

### Jurisprudência
- RE 123456
- Tema repetitivo: prevalência de normas internacionais em constituições

### Dicas de prova
- Entenda a diferença entre prevalência e aplicação das normas internacionais
- Conheça as fontes da responsabilização pelo descumprimento de normas internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Convenção das Nações Unidas sobre Direitos Humanos"], "jurisprudence": ["RE 123456", "Tema repetitivo: prevalência de normas internacionais em constituições"], "confidence": 0.8, "extracted_at": "2026-05-31T05:22:31.998599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=17", "doc_key": "984d9210a8f3bd8d754959c9578587d5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '30083e7eb66587d0b53fd60b1a2d4f3234875dec717af9b8fe365f691bed69fc'),
  ('cpiuris2025::2737f2a36fe57834162053be698e0d00', 'doutrina', 'cp_iuris', 'Direitos Internacional — Monismo Nacionalista', '## Monismo Nacionalista

A teoria monista nacionalista defende a prevalência do direito internacional em face do direito interno. Hans Kelsen é um dos principais defensores desse ponto de vista, argumentando que as normas mutuamente válidas não podem coexistir em um mesmo espaço e tempo.

### Conceitos
- **Monismo Nacionalista**: Teoria que defende a prevalência do direito internacional em face do direito interno
- **Hans Kelsen**: Autor que defende o monismo nacionalista e argumenta que as normas mutuamente válidas não podem coexistir em um mesmo espaço e tempo
- **Princípio da Eficácia**: Princípio do direito internacional que determina a validade das ordens jurídicas nacionais
- **Pacta Sunt Servanda**: Princípio que defende a prevalência da norma pactuada em face de outras normas
- **Costume Internacional**: Fato criador de normas jurídicas cogentes aos Estados

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre o princípio da eficácia e o pacta sunt servanda
- Conheça as teorias monistas internacionalistas e suas principais figuras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:23:01.453676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=17", "doc_key": "2737f2a36fe57834162053be698e0d00"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8869d907f00da386448f550c5d5f496556cb00ff0034d9d80f52430b03cb61ef'),
  ('cpiuris2025::20d72b81f0f2869ae505af4a24d8a156', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípio da Hierarquia e Aplicação de Leis Domésticas em Tratados de Direitos Humanos', '## Princípio da Hierarquia e Aplicação de Leis Domésticas em Tratados de Direitos Humanos

O princípio da hierarquia prevalece sobre a aplicação de leis domésticas favoráveis aos direitos humanos, conforme norma de interpretação do tratado.

### Conceitos
- **Princípio da Hierarquia**: Prevalência de uma norma internacional sobre outra
- **Princípio da Primazia da Norma mais Favorável ao Ser Humano**: Norma que prevalece em caso de conflito entre leis domésticas e tratados de direitos humanos

### Referências legais
- Art. 59 do CC
- ...

### Dicas de prova
- Distinção entre princípio da hierarquia e aplicação de leis domésticas favoráveis aos direitos humanos
- Reconhecimento da primazia da norma mais favorável ao ser humano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 do CC", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:24:19.100307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=18", "doc_key": "20d72b81f0f2869ae505af4a24d8a156"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e25fcdb9c7b6869530b0fee119aebb8ed361e0c357d6cfda73a777f5d91c692a'),
  ('cpiuris2025::a0fe427e4c2f9b66694d0af63968de25', 'doutrina', 'cp_iuris', 'Direitos Internacional — Supremacia e Monismo no Direito Internacional', '## Supremacia e Monismo no Direito Internacional

A supremacia do direito internacional é uma questão de conteúdo normativo, não de soberania. Existem teorias monistas radicais e mitigadas, que consideram a relação entre direito interno e internacional em termos de conteúdo normativo.

### Conceitos
- **Monismo**: Teoria que afirma a existência de um único direito superior ao direito interno
- **Supremacia do Direito Internacional**: Conceito que indica a superioridade do direito internacional em relação ao direito interno
- **Teoria Monista Mitigada**: Variante da teoria monista, que considera a relação entre direito interno e internacional em termos de conteúdo normativo
- **Jus Cogens**: Princípio do direito internacional que estabelece normas inderrogáveis e superiores ao direito interno
- **Pro Homine**: Princípio que prioriza a proteção da vítima em caso de conflito entre normas internacionais e nacionais

### Referências legais
- Art. 5º, § 2º, da Constituição Brasileira
- Artigo 29 da Convenção Americana de Direitos Humanos

### Jurisprudência
- RE 123456
- Tema repetitivo sobre monismo e supremacia do direito internacional

### Dicas de prova
- Entenda a distinção entre teorias monistas radicais e mitigadas
- Conheça o princípio do jus cogens e sua relação com a supremacia do direito internacional
- Aprenda a aplicar o princípio pro homine em casos de conflito entre normas internacionais e nacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 2º, da Constituição Brasileira", "Artigo 29 da Convenção Americana de Direitos Humanos"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre monismo e supremacia do direito internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T05:24:37.018568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=18", "doc_key": "a0fe427e4c2f9b66694d0af63968de25"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2ff56e1f78ea56631a10500df35c4da1bd5de2270e7ce68560ea3a2191e0776e'),
  ('cpiuris2025::2e3ed3ddd11e343a73df56babe72f115', 'doutrina', 'cp_iuris', 'Direitos Internacional — Monismo internacionalista dialógico', '## Monismo internacionalista dialógico

A teoria monista internacionalista dialógica é defendida, que combina o monismo com o diálogo entre as normas internacionais e internas, especialmente em relação aos direitos humanos.

### Conceitos
- **Monismo**: Teoria que considera que há uma única fonte do direito
- **Dualismo**: Teoria que considera que existem dois sistemas de direito: internacional e nacional
- **Dialógico**: Abordagem que combina o monismo com a interação entre as normas internacionais e internas
- **Sobranidade Estatal**: Conceito de soberania estatal, que se refere à capacidade do Estado de agir de acordo com sua vontade própria
- **Direitos Humanos**: Direitos fundamentais das pessoas humanas, protegidos por tratados e convenções internacionais
- **Unidade Jurídica Global**: Conceito de uma ordem jurídica global unificada e coerente

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre monismo e dualismo, bem como o conceito de dialógico em teoria jurídica internacional
- Conheça a importância dos direitos humanos na teoria jurídica internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:25:42.897220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=19", "doc_key": "2e3ed3ddd11e343a73df56babe72f115"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '985ca812186a53a6ed4a5f5f3487f2ac60fa0f919fceb29413d3b74394befdf8'),
  ('cpiuris2025::ff89a8ceb79dd9e794e16587b0390cae', 'doutrina', 'cp_iuris', 'Direitos Internacional — Monismo internacionalista no sistema brasileiro', '## Monismo internacionalista no sistema brasileiro

O artigo 178 da Constituição pode indicar a adoção do monismo internacionalista, mas não é claro se é uma posição normativa ou interpretativa.

### Conceitos
- **Monismo internacionalista**: Teoria que afirma que o direito internacional é uma fonte de direitos internos
- **Cláusulas de abertura**: Disposições constitucionais que permitem a aplicação de tratados internacionais

### Referências legais
- Art. 178 da Constituição

### Dicas de prova
- Entenda o conceito de monismo internacionalista e suas implicações no sistema brasileiro
- Análise cuidadosa do artigo 178 da Constituição para determinar se é uma posição normativa ou interpretativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direitos Internacional", "legal_refs": ["Art. 178 da Constituição"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-31T05:25:53.963617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=19", "doc_key": "ff89a8ceb79dd9e794e16587b0390cae"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8985c48d9b5ab8ac468215c2a8d2509392c4ca6ac42be52194da35085153fab4'),
  ('cpiuris2025::7ec0f38af0b0e3d6afed8385e42c21b7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria Dualista Moderada de Incorporação de Tratados', '## Teoria Dualista Moderada de Incorporação de Tratados

A teoria dualista moderada é defendida pelo ministro Celso de Mello, que considera que o Brasil adota uma abordagem que combina elementos da incorporação dos tratados ao ordenamento e do arcabouço teórico. O procedimento complexo de ratificação interna de um tratado requer a manifestação do Congresso Nacional e do presidente da República.

### Conceitos
- **Teoria Dualista Moderada**: Abordagem que combina elementos da incorporação dos tratados ao ordenamento e do arcabouço teórico
- **Incorporação de Tratados**: Procedimento pelo qual os tratados internacionais são integrados ao ordenamento jurídico nacional
- **Arcabouço Teórico**: Frammento teórico que estrutura a compreensão e a aplicação dos direitos internacionais

### Referências legais
- Art. 59 da Constituição Federal de 1988
- Súmula 646 do Supremo Tribunal Federal

### Jurisprudência
- RE 1025542/MG
- ADI 1.480-MC

### Dicas de prova
- Entenda a distinção entre incorporação e arcabouço teórico
- Conheça o procedimento de ratificação interna de um tratado
- Análise crítica do julgamento da ADI 1.480-MC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Constituição Federal de 1988", "Súmula 646 do Supremo Tribunal Federal"], "jurisprudence": ["RE 1025542/MG", "ADI 1.480-MC"], "confidence": 0.8, "extracted_at": "2026-05-31T05:28:15.623884+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=20", "doc_key": "7ec0f38af0b0e3d6afed8385e42c21b7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '360a7850f7a7af25f82aac4e64a510236ca13b73940a075ce267711e421c3fd1'),
  ('cpiuris2025::8b6b6ba48a7a909f169df50021661ec2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Status formal dos tratados internacionais', '## Status formal dos tratados internacionais

O Supremo Tribunal Federal interpretou que a Convenção n.º 158 da OIT é uma norma não autoexecutória, dependendo de manifestação legislativa posterior para sua implementação.

### Conceitos
- **Teoria monista nacionalista**: Teoria que afirma a supremacia da Constituição em relação aos tratados internacionais
- **Teoria dualista moderada**: Teoria que distingue entre o status formal e normativo dos tratados internacionais
- **Status formal de lei ordinária**: Consideração de um tratado internacional como uma lei ordinária, sem o condão de regulamentar a Constituição
- **Internalização de tratados internacionais**: Processo pelo qual os tratados internacionais são incorporados ao ordenamento interno como normas legais

### Referências legais
- Art. 7º, I, da Constituição
- Art. 10 do Tratado n.º 158 da OIT

### Jurisprudência
- RE 349.703
- Súmula N da STF

### Dicas de prova
- Entenda a distinção entre teoria monista e dualista moderada
- Conheça o conceito de status formal de lei ordinária
- Avalie a importância da internalização de tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º, I, da Constituição", "Art. 10 do Tratado n.º 158 da OIT"], "jurisprudence": ["RE 349.703", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T05:28:26.658004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=21", "doc_key": "8b6b6ba48a7a909f169df50021661ec2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5f5b34e8a72d9637153fb58041f0dd0621cb5ab7a19cb82d072f7b4898bc8665'),
  ('cpiuris2025::01384801039f1c958073fd00fc6763d7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Direito Tributário', '## Tratados Internacionais e Direito Tributário

O direito tributário internacional é regido por tratados e convenções internacionais, que revogam ou modificam a legislação tributária interna. A interpretação desses acordos prevalece sobre a norma posterior, revelando uma posição monista internacionalista.

### Conceitos
- **Tratados Internacionais**: Acordos entre Estados estrangeiros que regem questões específicas
- **Convenções Internacionais**: Acordos entre Estados estrangeiros que regem questões específicas, geralmente com mais flexibilidade do que os tratados
- **Princípio da Reciprocidade**: O Estado deve observar os acordos firmados pela União e atender ao princípio da reciprocidade
- **Teoria Monista Internacionalista Radical**: Não prevê que um Estado alegue as normas da sua Constituição para justificar o descumprimento de um tratado
- **Controle de Constitucionalidade dos Tratados Internacionais**: O Supremo Tribunal Federal tem competência para julgar as causas decididas em única ou última instância, quando a decisão recorrida declara a inconstitucionalidade de um tratado
- **Posição Monista Nacionalista**: A Constituição permite o controle de constitucionalidade dos tratados internacionais, mas não prevê que os Estados invocem as normas da sua Constituição para justificar o descumprimento de um tratado
- **Interpretação dos Tratados Internacionais**: Os tratados e convenções internacionais em matéria tributária são interpretados como norma especial, prevalecendo sobre a norma posterior

### Referências legais
- Art. 178 da Lei
- Art. 98 do Código Tributário Nacional (CTN)
- Art. 85-A da Lei n.º 8.212/1991
- Convenção de Viena sobre Tratados
- Decreto n.º 7.030/2009

### Jurisprudência
- RE 123456
- Tema repetitivo da jurisprudência pátria

### Dicas de prova
- Entenda a diferença entre tratados e convenções internacionais em matéria tributária
- Aprenda a aplicar o princípio da reciprocidade e a teoria monista internacionalista radical
- Conheça a competência do Supremo Tribunal Federal no controle de constitucionalidade dos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direitos Internacional", "legal_refs": ["Art. 178 da Lei", "Art. 98 do Código Tributário Nacional (CTN)", "Art. 85-A da Lei n.º 8.212/1991", "Convenção de Viena sobre Tratados", "Decreto n.º 7.030/2009"], "jurisprudence": ["RE 123456", "Tema repetitivo da jurisprudência pátria"], "confidence": 0.8, "extracted_at": "2026-05-31T05:28:53.114925+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=20", "doc_key": "01384801039f1c958073fd00fc6763d7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fe24ce72ade6396c3e85984bfbd22ad9634b1c58ba60d3f5186a1364694ab89e'),
  ('cpiuris2025::7884832ed42fba61ca14b6870de484af', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prevalência das Convenções de Varsóvia e Montreal em relação à lei consumerista interna', '## Prevalência das Convenções de Varsóvia e Montreal em relação à lei consumerista interna

O Supremo Tribunal Federal definiu que as normas das Convenções de Varsóvia e Montreal prevalem sobre a lei consumerista interna em casos de transporte aéreo internacional.

### Conceitos
- **Convenções de Varsóvia e Montreal**: Tratados internacionais que limitam a responsabilidade das transportadoras aéreas de passageiros
- **Tema 210 da Repercussão Geral**: Revisão jurídica sobre a prevalência das Convenções de Varsóvia e Montreal em relação à lei consumerista interna
- **Danos materiais**: Danos físicos ou de propriedade causados pelo transporte aéreo internacional
- **Danos extra patrimoniais**: Danos não materiais, como danos emocionais ou psicológicos, causados pelo transporte aéreo internacional
- **Lei Consumerista Interna**: Lei que regula os direitos do consumidor em relação aos serviços de transporte aéreo internacional

### Referências legais
- Art. 178 da Constituição da República
- STF. RE 636.331, rel. min. Gilmar Mendes, voto da Min. Rosa Weber, j. 25/05/2017, p. DJE de 13/11/2017

### Jurisprudência
- Tema 210 da Repercussão Geral
- RE 636.331

### Dicas de prova
- Entenda a prevalência das Convenções de Varsóvia e Montreal em relação à lei consumerista interna
- Distinga entre danos materiais e extra patrimoniais
- Conheça as normas das Convenções de Varsóvia e Montreal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Direitos Internacional", "legal_refs": ["Art. 178 da Constituição da República", "STF. RE 636.331, rel. min. Gilmar Mendes, voto da Min. Rosa Weber, j. 25/05/2017, p. DJE de 13/11/2017"], "jurisprudence": ["Tema 210 da Repercussão Geral", "RE 636.331"], "confidence": 0.8, "extracted_at": "2026-05-31T05:29:37.360301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=21", "doc_key": "7884832ed42fba61ca14b6870de484af"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ab057d031221012dda8782234a56ecb2a7c8302c545d9ba2b3f01dbaf9df3e48'),
  ('cpiuris2025::6870983e9e531f8f7b42ad6e57412037', 'doutrina', 'cp_iuris', 'Direitos Internacional — Dualismo vs Monismo no Direito Internacional', '## Dualismo vs Monismo no Direito Internacional

Resumo do texto sobre o dualismo e monismo no direito internacional, destacando as teorias de Adriely Andriani.

### Conceitos
- **Dualismo**: Teoria que afirma a existência de dois sistemas jurídicos: interno e internacional
- **Monismo**: Teoria que afirma a unidade do ordenamento jurídico, com prevalecimento das normas internacionais sobre as internas
- **Corrente Monista**: Acredita que o direito internacional sempre prevalece sobre o interno
- **Corrente Dualista**: Acredita que os direitos internos e internacionais convivem em uma única ordem jurídica

### Referências legais
- Art. 59 da Constituição Federal

### Jurisprudência
- Súmula 455 do STF

### Dicas de prova
- Entenda a diferença entre dualismo e monismo
- Conheça as teorias de Adriely Andriani sobre o assunto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Constituição Federal"], "jurisprudence": ["Súmula 455 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T05:31:41.032235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=22", "doc_key": "6870983e9e531f8f7b42ad6e57412037"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3f6347d16e16b59b0956c5015c7143eaf62d3b80ee0bc3bc66a7fd353082599f'),
  ('cpiuris2025::cd7d423b120b0776e1537b613b1c24a2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teorias do Direito Internacional', '## Teorias do Direito Internacional

A questão discute as teorias do direito internacional, destacando a distinção entre monismo moderado e dualismo moderado. O texto destaca a adoção do monismo moderado pelo Brasil e a proteção dos direitos humanos.

### Conceitos
- **Monismo Moderado**: Teoria que considera que o direito internacional é uma fonte de direito interno, mas com limitações
- **Dualismo Moderado**: Teoria que considera que o direito internacional e o direito interno são fontes separadas de direito
- **Monismo Internacionalista**: Teoria que considera que o direito internacional é a única fonte de direito, mas com limitações

### Referências legais
- Art. 109 da Constituição Federal
- Súmula 397 do STF

### Jurisprudência
- RE 1394401
- ADI 1.480/MC

### Dicas de prova
- Perguntas objetivas podem ter diferentes respostas, dependendo da forma de redação.
- A adoção do monismo moderado pelo Brasil é provável para questões relacionadas à proteção dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direitos Internacional", "legal_refs": ["Art. 109 da Constituição Federal", "Súmula 397 do STF"], "jurisprudence": ["RE 1394401", "ADI 1.480/MC"], "confidence": 0.8, "extracted_at": "2026-05-31T05:32:00.411363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=22", "doc_key": "cd7d423b120b0776e1537b613b1c24a2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5bc565c8e8dd611650004a24d407892e213bc762b20b043f2b12c11c18be317b'),
  ('cpiuris2025::d1ccb7729e745f254bf57dc586e420a8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflitos Normativos entre Normas Internacionais e Nacionais', '## Conflitos Normativos entre Normas Internacionais e Nacionais

A análise de conflitos normativos envolve a aplicação das regras internacionais, constitucionais e nacionais para determinar qual norma prevalece em cada caso.

### Conceitos
- **Critério pré-estipulado**: não há critério pré-estipulado para a análise de conflitos normativos
- **Supremacia da Constituição Federal**: a regra prevalece sobre a norma prescrita no tratado internacional
- **Princípio pro homine**: prevalece a norma mais benéfica ao indivíduo titular do direito
- **Lei posterior revoga lei anterior**: leis posteriores revogam leis anteriores com ela incompatíveis
- **Hierarquia supraconstitucional**: prevalece a norma do tratado internacional de proteção de direitos humanos

### Referências legais
- Art. 5 da Constituição Federal
- Tratados Internacionais de Proteção de Direitos Humanos

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pergunte se a norma internacional prevalece ou não sobre a norma nacional.
- Entenda o princípio pro homine e como ele é aplicado em conflitos normativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 da Constituição Federal", "Tratados Internacionais de Proteção de Direitos Humanos"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T05:32:23.013155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=23", "doc_key": "d1ccb7729e745f254bf57dc586e420a8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7b7b6315ac3bec4aea444e4f68e998d7712e72defe378134954491037d39b9d9'),
  ('cpiuris2025::40dd6f2a8a17eeff99896a4ddb3bf852', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria da Autolimitação Estatal', '## Teoria da Autolimitação Estatal

O direito internacional se baseia na vontade dos Estados, que criam normas e sanções para seu descumprimento.

### Conceitos
- **Vontade dos Estados**: A base do direito internacional
- **Autolimitação Estatal**: O Estado se obriga a si mesmo
- **Teoria da Autolimitação**: Argumento metafísico de poder absoluto

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Caso (navio) S.S. Lótus, Corte Permanente de Justiça Internacional

### Dicas de prova
- Entenda a relação entre vontade dos Estados e direito internacional
- Distinção entre vontade particular e autolimitação estatal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Caso (navio) S.S. Lótus, Corte Permanente de Justiça Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T05:33:50.393116+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=24", "doc_key": "40dd6f2a8a17eeff99896a4ddb3bf852"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '695a63274421b8ade0af9b0ae4238f7993391ac1705f0021e705d4aa9f970e4b'),
  ('cpiuris2025::46fc2e59a0e111947870207f684a8cd1', 'doutrina', 'cp_iuris', 'Direitos Internacional — IncorporaÎo de tratados de direitos humanos na ordem jurídica interna', '## IncorporaÎo de tratados de direitos humanos na ordem jurídica interna

Discute a incorporação de tratados de direitos humanos à ordem jurídica interna, destacando a aplicação do direito internacional e a prevalência do ordenamento jurídico interno em caso de conflito.

### Conceitos
- **Dualismo**: Teoria que afirma a existência de dois sistemas jurídicos: o internacional e o interno
- **IncorporaÎo**: Processo pelo qual os tratados de direitos humanos se tornam parte integrante da ordem jurídica interna
- **Ordem Jurídica Internacional**: Sistema jurídico que regula as relações entre os Estados
- **Ordem Jurídica Interna**: Sistema jurídico que regula as relações dentro de um Estado

### Referências legais
- Art. 59 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a distinção entre dualismo e monismo
- Conheça as teorias sobre a incorporação de tratados de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.7, "extracted_at": "2026-05-31T05:33:50.877922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=23", "doc_key": "46fc2e59a0e111947870207f684a8cd1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c8c010898acdd1f5b45eae6e5dce375edb9c9e1321c7f2aad2de3888e2c44b3c'),
  ('cpiuris2025::04cd77471dba710bc3646d74136e75b4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teorias Voluntaristas', '## Teorias Voluntaristas

As teorias voluntaristas defendem que as regras do direito internacional dependem da vontade dos Estados soberanos.

### Conceitos
- **Voluntarismo Jurídico**: afirmação de que as normas do Direito são produto da vontade humana
- **Positivismo**: definição do Direito através dos institutos da ''estadualidade e coercibilidade''
- **Soberania**: princípio que os Estados não estão sujeitos a uma vontade superior
- **Teoria da Autolimitação do Estado**: desenvolvimento de Georg Jellinek sobre a soberania dos Estados

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de voluntarismo jurídico e sua relação com o positivismo
- Identifique a teoria da autolimitação do Estado e seu papel na discussão sobre soberania', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:34:05.751879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=24", "doc_key": "04cd77471dba710bc3646d74136e75b4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b7be85e0a432a03cd4b2ed920592abcfe654bfcbeae805bcda95be20a60d5cce'),
  ('cpiuris2025::ce700f9fcb9b3e8ee7d02c411346cc04', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípio da Proeminência', '## Princípio da Proeminência

O princípio da proeminência é um princípio geral que estabelece que, se um grande número de Estados aceita uma prática ou código, outros Estados devem aceitá-lo, com a ressalva de que tal dever não lhe será imposto se uma prática mais geral melhorar a legitimidade do Estado que não a aceitou.

### Conceitos
- **Princípio da Proeminência**: princípio geral que estabelece a aceitação de práticas ou códigos por um grande número de Estados
- **Vontade Comum**: teoria baseada na vontade comum, de Triepel, ou no consentimento das nações, de Oppenheim

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre a teoria da autolimitação do Estado e a teoria baseada na vontade comum.
- Identifique o autor que apresenta uma teoria baseada na vontade comum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T05:35:57.946615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=25", "doc_key": "ce700f9fcb9b3e8ee7d02c411346cc04"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '54b7479eed32447b76c9e2997397a8c0bc16998a0687781e8a2890b1fa3a2a59'),
  ('cpiuris2025::77bca516e4c7e4eecc8273e9716e2ce5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teorias não voluntaristas do direito internacional', '## Teorias não voluntaristas do direito internacional

As teorias não voluntaristas buscam assentar o fundamento do Direito Internacional em princípios ou normas superiores aos ordenamentos nacionais, independentes da vontade dos Estados.

### Conceitos
- **tese normativista**: reconduz o sistema de Direito Internacional à uma norma fundamental pressuposta
- **pacta sunt servanda**: princípio que obriga os Estados a cumprir as suas obrigações internacionais
- **tese solidarista**: fundamenta o direito internacional na solidariedade entre indivíduos, sendo fatores sociológicos que explicam as normas jurídicas
- **consuetudo est servanda**: princípio que obriga os Estados a cumprir as suas obrigações internacionais de acordo com as práticas habituais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Internacional

### Dicas de prova
- Entenda a distinção entre teorias voluntaristas e não voluntaristas do direito internacional.
- Conheça os princípios fundamentais das teses normativistas e solidaristas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T05:36:28.683787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=26", "doc_key": "77bca516e4c7e4eecc8273e9716e2ce5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e6986be26e6c195ba5f3e2653af0e0512d3cb2b5a1691471b02ea0ccdc8c3d4f'),
  ('cpiuris2025::2d316fc893cd393bb1fbc34b43475fcb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Pacta Sunt Servanda e Teorias do Direito Internacional', '## Pacta Sunt Servanda e Teorias do Direito Internacional

A norma pacta sunt servanda é a base do ordenamento internacional, fundamentando o respeito aos pactos concluídos por Estados. A teoria da vontade coletiva de Karl Heinrich Triepel destaca as uniões de vontade como fundamento do direito internacional, enquanto Max Wenzel defende que ele se baseia nos ordenamentos nacionais, e William Edward Hall e Lassa Oppenheim na consentimento das nações.

### Conceitos
- **Pacta Sunt Servanda**: Princípio fundamental do direito internacional que exige o respeito aos pactos concluídos por Estados
- **Vontade Coletiva**: Conceito de Karl Heinrich Triepel que destaca as uniões de vontade como fundamento do direito internacional
- **Delegatário do Direito Interno**: Teoria de Max Wenzel que fundamenta o direito internacional nos ordenamentos nacionais
- **Consentimento das Nações**: Teoria de William Edward Hall e Lassa Oppenheim que fundamenta o direito internacional no consentimento da maioria dos Estados

### Referências legais
- CPJI, Caso do SS. Lotus, Series A. nº 10, 1927
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre pacta sunt servanda e delegatário do direito interno
- Conheça as diferentes teorias sobre a vontade coletiva e consentimento das nações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direitos Internacional", "legal_refs": ["CPJI, Caso do SS. Lotus, Series A. nº 10, 1927", "Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:36:57.131472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=25", "doc_key": "2d316fc893cd393bb1fbc34b43475fcb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '474b265c7e7d867e4e15e0eb1e4eed8e623dd9b21f68fcf975f2ca898a16b99d'),
  ('cpiuris2025::b481ee46c77d7cdfc160e6ea9b2ca6b8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teorias do Direito Internacional', '## Teorias do Direito Internacional

Descreve as teorias institucionalistas e jusnaturalistas sobre o Direito Internacional, destacando suas principais características.

### Conceitos
- **Institucionalismo**: teoria que considera o Direito Internacional como ordenamento da comunidade internacional
- **Jus Naturalista**: teoria que assenta-se em valores suprapositivos, critérios éticos e princípios jurídicos transcendentes

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre institucionalismo e jusnaturalismo.
- Conheça as principais teorias jusnaturalistas, como a de Hugo Grócio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:37:32.740223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=26", "doc_key": "b481ee46c77d7cdfc160e6ea9b2ca6b8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ce74bdb0c1e127bae32ad43200d9625f9c2918fdcc5811162760912d82d4f3a4'),
  ('cpiuris2025::66ec315c58d4ffeb2795467082b1f0bb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigatoriedade do Direito Internacional', '## Obrigatoriedade do Direito Internacional

A corrente voluntarista considera que a obrigatoriedade do direito internacional deve basear-se no consentimento dos cidadãos, enquanto a corrente objetivista defende que o consentimento perceptivo das normas jurídicas do direito internacional nasce da pura vontade dos Estados.

### Conceitos
- **Obrigatoriedade do Direito Internacional**: A questão de saber se as normas do direito internacional são obrigatórias ou não.
- **Consentimento**: A ideia central para a corrente voluntarista e objetivista
- **Vontade dos Estados**: A base da corrente objetivista

### Referências legais
- Art. 23 do Estatuto de Roma sobre Direitos do Consumidor

### Dicas de prova
- Entenda a distinção entre consentimento perceptivo e vontade dos Estados
- Conheça as correntes voluntarista e objetivista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Estatuto de Roma sobre Direitos do Consumidor"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:38:38.724323+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=27", "doc_key": "66ec315c58d4ffeb2795467082b1f0bb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0ec6f677cfd4b664ebb4b451a650f34559f0cb6babd297cca06312930a449636'),
