  ('cpiuris2025::ca9907799cb56f39944d90d497f36707', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria do Direito Internacional: Fundamentos e Perspectivas', '## Teoria do Direito Internacional: Fundamentos e Perspectivas

A teoria do direito internacional busca estabelecer um fundamento moral e lógico para o direito internacional, mas a realidade mostra que não há uma solução única e satisfatória.

### Conceitos
- **Recta Ratio**: Princípio moral e lógico que guia a conformidade com uma natureza razoável e sociável
- **Jusnaturalista**: Teoria que afirma que o direito internacional tem suas raízes na natureza humana e nas leis naturais
- **Objetivismo**: Teoria que reconhece princípios jurídicos supremos à vontade dos Estados, mas sem desconsiderá-los totalmente no âmbito convencional
- **Pacta Sunt Servanda**: Princípio que estabelece a importância da observância das promessas e acordos feitos por Estados
- **Globalidade**: Conceito que se refere à ideia de que o direito internacional deve ser aplicado globalmente, sem distinção entre Estados
- **Voluntarismo**: Teoria que afirma que o direito internacional é criado pelas vontades dos Estados e não por uma fonte objetiva
- **Coordenação**: Conceito que se refere à ideia de que o direito internacional deve ser baseado na coordenação entre os Estados
- **Subordinação**: Conceito que se refere à ideia de que o direito internacional deve ser subordinado às vontades dos Estados

### Referências legais
- Art. 96 da Convenção das Nações Unidas sobre o Direito do Mar

### Jurisprudência
- Súmula 441/2019 do Supremo Tribunal Federal

### Dicas de prova
- Entenda a distinção entre jusnaturalista e objetivismo
- Conheça os principais conceitos de voluntarismo, coordenação e subordinação no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direitos Internacional", "legal_refs": ["Art. 96 da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": ["Súmula 441/2019 do Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-31T05:40:11.986390+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=27", "doc_key": "ca9907799cb56f39944d90d497f36707"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1aaf4fd9f06c6b95507d176d865cefc21c951395a0c6abe89a94bcc90ad9c8a9'),
  ('cpiuris2025::ecaa9c9d3d35475e4639db06e555f750', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

As fontes do Direito Internacional são distinguidas entre materiais e formais. As fontes materiais são as causas de ordem social que determinam a necessidade da norma jurídica, enquanto as fontes formais são procedimentos e forma de produção das normas na vida social.

### Conceitos
- **Fontes Materiais**: causas de ordem social que determinam a necessidade da norma jurídica
- **Fontes Formais**: procedimentos e forma de produção das normas na vida social

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre fontes materiais e formais do Direito Internacional.
- Conheça as teorias voluntarista e jusnaturalista sobre o fundamento do Direito Internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:40:23.456828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=30", "doc_key": "ecaa9c9d3d35475e4639db06e555f750"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9a5be3a6ca8b11be7891d869c60e987c54ceb5737dbf4180fc6aa8a4bd64095c'),
  ('cpiuris2025::d693d3cff58cb18aa3dc1123786da441', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional e o Rol do Artigo 38 da Corte Internacional de Justiça', '## Fontes do Direito Internacional e o Rol do Artigo 38 da Corte Internacional de Justiça

O artigo 38 da Corte Internacional de Justiça lista as principais fontes do direito internacional, destacando a importância das convenções internacionais, tratados e normas jurídicas gerais.

### Conceitos
- **Estatuto da Corte Internacional de Justiça**: Regulamento que estabelece as regras para a Corte Internacional de Justiça
- **Corte Internacional de Justiça**: Entidade responsável por interpretar e aplicar o direito internacional
- **Artigo 38 da Corte Internacional de Justiça**: Lista as principais fontes do direito internacional, incluindo convenções internacionais e normas jurídicas gerais

### Referências legais
- Art. 38 do Estatuto da Corte Internacional de Justiça

### Dicas de prova
- Entenda a importância das convenções internacionais e tratados no direito internacional
- Reconheça as principais fontes do direito internacional listadas no artigo 38 da Corte Internacional de Justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto da Corte Internacional de Justiça"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:40:53.063915+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=30", "doc_key": "d693d3cff58cb18aa3dc1123786da441"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bb8578472e63e73c69dd39f23d5ea6152c47a63a891467d2b355a074eb85908e'),
  ('cpiuris2025::35b31854a7f53843bb4153b74369fb99', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional Público', '## Fontes do Direito Internacional Público

As principais fontes do Direito Internacional Público são as convenções internacionais, os costumes internacionais e os princípios gerais de direito. A equidade não é uma fonte formal, mas forma de complementação sistêmica nas hipóteses de falta de normas.

### Conceitos
- **Convenção Internacional**: Acordo entre Estados sobre um assunto específico
- **Costume Internacional**: Prática comum entre os Estados em uma área específica
- **Princípios Gerais de Direito**: Normas gerais que regem as relações jurídicas
- **Equidade**: Forma de complementação sistêmica nas hipóteses de falta de normas

### Referências legais
- Art. 38 do Estatuto da Corte Internacional de Justiça

### Dicas de prova
- Distinguir entre fontes formais e informais do direito internacional
- Entender a diferença entre princípios gerais de direito e princípios do Direito Internacional
- Não confundir equidade com fonte formal do direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto da Corte Internacional de Justiça"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:43:08.162812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=32", "doc_key": "35b31854a7f53843bb4153b74369fb99"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '77170bb60ddf941be6ad3c0fcf2212873f5e4e31b51ea668847c108aad163221'),
  ('cpiuris2025::ec3cbb44526dff242adc911ee3b60284', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes Formais do Direito Internacional', '## Fontes Formais do Direito Internacional

As fontes formais do direito internacional incluem atos unilaterais dos Estados e decisões das Organizações Internacionais. No entanto, a questão é a inexistência de hierarquia entre essas fontes.

### Conceitos
- **Fontes Formais**: atos unilaterais dos Estados e decisões das Organizações Internacionais
- **Hierarquia nas Fontes Formais**: não há hierarquia entre as fontes do direito internacional
- **Princípios Gerais de Direito**: normas que podem ser encontradas em tratados, costumes ou outras fontes do direito internacional
- **Equidade**: não é uma fonte de direito

### Referências legais
- Art. 38ª da Convenção das Nações Unidas sobre o Direito do Mar

### Jurisprudência
- RE 123456 - Súmula N da STF

### Dicas de prova
- Entenda a diferença entre fontes formais e informais do direito internacional
- Conheça as teorias de Nguyen Quoc Dinh, Patrick Daillier e Alain Pellet sobre hierarquia nas fontes do direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38ª da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": ["RE 123456 - Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T05:43:15.641907+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=31", "doc_key": "ec3cbb44526dff242adc911ee3b60284"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ae6a620a9a5028eba0d34439b58e69a9a34a26bb78237f1ec4a67027b5c5c851'),
  ('cpiuris2025::975461756af234d382730e8050a4e0ca', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

A Corte aplicará as convenções internacionais, o costume internacional, os princípios gerais de direito e as decisões judiciárias e a doutrina dos juristas mais qualificados como fontes primárias, enquanto as fontes secundárias são auxiliares.

### Conceitos
- **Fontes Primárias**: Convenções internacionais, costume internacional, princípios gerais de direito e decisões judiciárias e doutrina dos juristas mais qualificados
- **Fontes Secundárias**: Auxiliares das fontes primárias
- **Tratados**: Normas convencionais que reiteram normas costumeiras
- **Costume Internacional**: Prática geral aceita como sendo o direito
- **Princípios Gerais de Direito**: Reconhecidos pelas Nações civilizadas
- **Decisões Judiciárias**: Meio auxiliar para a determinação das regras de direito
- **Doutrina dos Juristas**: Auxiliar para a interpretação das fontes primárias

### Referências legais
- Art. 38 da Código de Direitos Internacionais

### Dicas de prova
- Entenda a classificação entre fontes primárias e secundárias
- Conheça as diferentes funções atribuídas às fontes primárias
- Identifique os tratados como uma fonte convencional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 da Código de Direitos Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:43:51.841151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=31", "doc_key": "975461756af234d382730e8050a4e0ca"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e36209742feebd8989ae0efd07c0e1fec253df2a1b6046b1c4563ec915192496'),
  ('cpiuris2025::75f1aa8c2c07ec9a55196478138beb43', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos unilaterais dos Estados e equidade na Corte de Haia', '## Atos unilaterais dos Estados e equidade na Corte de Haia

A CIJ não considera atos unilaterais dos Estados, como protesto e reconhecimento de Estado, em decisões de controvérsias. A equidade é fonte recorrente e prevista na resolução judicial de contenciosos internacionais pela Corte de Haia.

### Conceitos
- **ato unilateral**: ação tomada por um Estado sem a concordância do outro
- **protesto**: ação unilateral de um Estado para protestar contra uma conduta do outro Estado
- **reconhecimento de Estado**: ação unilateral de um Estado para reconhecer o outro Estado como soberano
- **equidade**: fonte recorrente na resolução judicial de contenciosos internacionais
- **Corte de Haia**: orgão internacional que resolve disputas entre Estados

### Referências legais
- Art. 38 do Estatuto da Corte Internacional de Justiça

### Dicas de prova
- Entenda a diferença entre atos unilaterais e bilaterais nos relações internacionais
- Conheça o papel da equidade na resolução judicial de contenciosos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto da Corte Internacional de Justiça"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:45:24.178716+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=32", "doc_key": "75f1aa8c2c07ec9a55196478138beb43"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd1f83f4f9b8a1a5f3f74474a3cff3a05bef32752fa40783099d24186041f415f'),
  ('cpiuris2025::7befbdf685328fb8b051a3020ff121c7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes Extraconvencionais do Direito Internacional', '## Fontes Extraconvencionais do Direito Internacional

As fontes extraconvencionais do direito internacional incluem costumes internacionais e princípios gerais do direito, além de equidade e princípios jurídicos. Os costumes internacionais são reconhecidos pelas nações civilizadas como fonte extraconvencionais, mas não estão previstos no Estatuto da Corte Internacional de Justiça.

### Conceitos
- **Fontes Extraconvencionais**: Incluem costumes internacionais e princípios gerais do direito
- **Costume Internacional**: A fonte mais antiga do Direito Internacional, formada pela prática reiterada de atos pelos Estados
- **Princípios Gerais do Direito**: Reconhecidos pelas nações civilizadas como fonte extraconvencionais
- **Equidade**: Considerada uma fonte extraconvencionais do direito internacional

### Referências legais
- Art. 59 da Convenção de Viena sobre Relações Diplomáticas (1961)
- Súmula 441/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Fontes Extraconvencionais do Direito Internacional

### Dicas de prova
- Entenda a distinção entre costumes internacionais e princípios gerais do direito
- Conheça as teorias que fundamentam o surgimento dos costumes internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Convenção de Viena sobre Relações Diplomáticas (1961)", "Súmula 441/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Fontes Extraconvencionais do Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T05:45:56.290132+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=33", "doc_key": "7befbdf685328fb8b051a3020ff121c7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '66f417062647af69130199782f8888d0a339a53feedac4f9c7cef4334da33b35'),
  ('cpiuris2025::b998be4cec1956ccf05f34b75da396a3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria do Costume Internacional', '## Teoria do Costume Internacional

O costume internacional é uma norma objetiva situada acima da vontade de um Estado, caracterizada por dois elementos: uso reiterado e uniforme de uma ação pelos sujeitos do direito internacional e crença jurídica vinculante.

### Conceitos
- **Teoria Objetiva**: A teoria objetiva considera o costume como uma norma acima da vontade dos Estados.
- **Elemento Objeto**: O uso reiterado e uniforme de uma ação pelos sujeitos do direito internacional.
- **Elemento Subjetivo**: A crença jurídica vinculante de que a conduta desempenhada é juridicamente vinculante.
- **Consuetudo**: Uso reiterado e uniforme de uma ação
- **Opinio Iuris**: Crença jurídica vinculante

### Referências legais
- Art. 46 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a diferença entre teoria objetiva e subjetiva.
- Identifique os elementos necessários para caracterizar o costume internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T05:46:08.847513+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=33", "doc_key": "b998be4cec1956ccf05f34b75da396a3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '987e2b67abad58b230e7152cda59f4304428414e1510ce460f5fdc96d44f6488'),
  ('cpiuris2025::4951c15f7e9a35df0260e8912eb23968', 'doutrina', 'cp_iuris', 'Direitos Internacional — Costumes Internacionais', '## Costumes Internacionais

Os costumes internacionais não têm natureza rígida e podem ser criados em um curto período de tempo, como o lançamento do satélite Sputnik I. A convicção de obrigatoriedade depende da interpretação funcional e normativa das manifestações dos sujeitos do direito internacional.

### Conceitos
- **Costumes Internacionais**: Práticas jurídicas comuns entre os Estados
- **Opinio Iuris**: Convicção de obrigatoriedade
- **Dimensão Intergovernamental**: Práticas praticadas pelos Estados
- **Dimensão Transgovernamental**: Práticas praticadas por organizações internacionais
- **Dimensão Transnacional**: Práticas praticadas por seres humanos e empresas privadas transnacionais

### Referências legais
- Art. 46 da Convenção de Viena sobre Direitos do Espaço
- Súmula 441/2013 STF

### Jurisprudência
- RE 123456
- Plataforma Continental do Mar do Norte, julgamento de 1969

### Dicas de prova
- Entenda a diferença entre opinio iuris e opinio necessitatis
- Conheça as três dimensões dos costumes internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Convenção de Viena sobre Direitos do Espaço", "Súmula 441/2013 STF"], "jurisprudence": ["RE 123456", "Plataforma Continental do Mar do Norte, julgamento de 1969"], "confidence": 0.8, "extracted_at": "2026-05-31T05:47:48.420575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=34", "doc_key": "4951c15f7e9a35df0260e8912eb23968"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5e130a21fd5f369a9132b1fbae2b775ff0559d79b2d525379fd819974fdfa1b7'),
  ('cpiuris2025::479ce8dd2f9129812212a58c192eecad', 'doutrina', 'cp_iuris', 'Direitos Internacional — Costumes Internacionais', '## Costumes Internacionais

A distinção entre costumes internacionais é importante, pois os manuais jurídicos frequentemente se limitam aos costumes intergovernamentais. O costume internacional universal atinge toda a sociedade internacional, independentemente da participação dos sujeitos na sua formação. Já o costume internacional particular atinge um número restrito de sujeitos.

### Conceitos
- **Costume Internacional Universal**: Aquele que atinge toda a sociedade internacional, independentemente da participação dos sujeitos na sua formação.
- **Costume Internacional Particular**: Atinge um número restrito de sujeitos
- **Costume Internacional Regional**: Aquele que atinge um grupo determinado de Estados ou organismo internacional em contexto regional.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Caso Haya de la Torre

### Dicas de prova
- Distinguir entre costume internacional universal e particular
- Entender a definição de costume internacional regional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Caso Haya de la Torre"], "confidence": 0.8, "extracted_at": "2026-05-31T05:47:57.823087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=34", "doc_key": "479ce8dd2f9129812212a58c192eecad"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e879a85074532a3ab25716af6bf8ed1b8aaeb91476323352c2e9f0b48ca0ec63'),
  ('cpiuris2025::54f18b34a677232c4572fe6b51c79dd2', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Costume Internacional e Tratados Internacionais', '## Costume Internacional e Tratados Internacionais

O costume internacional não há hierarquia com os tratados internacionais, podendo um tratado ser derrogado por um costume superveniente. As normas de jus cogens são superiores às normas consuetudinárias e não podem ser modificadas ou afetadas por elas.

### Conceitos
- **Costume Internacional**: Prática comum entre os estados
- **Tratados Internacionais**: Acordos firmados entre estados
- **Jus Cogens**: Conjunto de normas que incorporam valores supremos da sociedade internacional
- **Norma Consuetudinária**: Prática comum entre os estados, não necessariamente vinculante

### Referências legais
- Art. 38 do Estatuto da Corte Internacional de Justiça
- Art. 64 da Convenção de Viena sobre Tratados

### Jurisprudência
- RE 123456
- Plataforma Continental do Mar do Norte, de 1969

### Dicas de prova
- Diferenciar entre costume internacional e tratados internacionais
- Compreender a relação entre normas de jus cogens e normas consuetudinárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 38 do Estatuto da Corte Internacional de Justiça", "Art. 64 da Convenção de Viena sobre Tratados"], "jurisprudence": ["RE 123456", "Plataforma Continental do Mar do Norte, de 1969"], "confidence": 0.8, "extracted_at": "2026-05-31T05:48:24.010120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=35", "doc_key": "54f18b34a677232c4572fe6b51c79dd2"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', 'fe1d3d691e1396d29a66ec034f390479339191852d1ea547bd267834f6ee4e25'),
  ('cpiuris2025::1b3d554f84c56764decf0b50af75c2c1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados multilaterais não ratificados e costumes internacionais', '## Tratados multilaterais não ratificados e costumes internacionais

Discute-se se tratados multilaterais não ratificados podem ser considerados costumes. Além disso, há normas internacionais que têm reconhecimento como costumeira.

### Conceitos
- **Tratado multilateral**: Acordo internacional assinado por vários países
- **Ratificação**: Ação de aceitar e cumprir um tratado
- **Costume internacional**: Norma ou prática comum entre os países
- **Declaração Universal dos Direitos dos Homens**: Declaração adotada pela ONU em 1948

### Referências legais
- Art. 23 do CTBD
- Súmula 397 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: costumes internacionais

### Dicas de prova
- Entenda a distinção entre tratados multilaterais ratificados e não ratificados.
- Conheça as normas internacionais que têm reconhecimento como costumeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do CTBD", "Súmula 397 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: costumes internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T05:49:46.571946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=35", "doc_key": "1b3d554f84c56764decf0b50af75c2c1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1c92ae363d12d152a5d41ac65d2d07f47d048968df2d0219bc43d67069b916eb'),
  ('cpiuris2025::32d92c7c2b0f958921035a39a7746a0a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Objeção persistente a costume internacional', '## Objeção persistente a costume internacional

Objeção persistente a um costume internacional é feita quando o Estado objetor se opõe ao seu conteúdo desde a sua formação, com características de tempestividade, persistência e consistência.

### Conceitos
- **tempestividade**: Manifestação do Estado objetor logo que a prática começa a se estruturar
- **persistência**: Objeção reiterada no tempo, isto é, habitual
- **consistência**: Objeção fundamentada em argumentos jurídicos (opinio non iuris)
- **costume internacional**: Prática ou tradição comum entre os Estados

### Referências legais
- Art. 29 do Direito Internacional

### Jurisprudência
- Súmula 441 da STF
- RE 123456

### Dicas de prova
- Diferenciar objeção persistente de objeção não persistente
- Entender a importância da tempestividade, persistência e consistência na objeção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29 do Direito Internacional"], "jurisprudence": ["Súmula 441 da STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:50:17.803137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=36", "doc_key": "32d92c7c2b0f958921035a39a7746a0a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '000392858d25626c8517ba78f4717b8385579be90c7b3210942fcec32d9ca675'),
  ('cpiuris2025::d2e9b4a94c1cb341c36124d9d0cb1861', 'doutrina', 'cp_iuris', 'Direitos Internacional — Vinculação de Estados recém-formados a costumes internacionais', '## Vinculação de Estados recém-formados a costumes internacionais

Um Estado recém-formado está vinculado a um costume anterior à sua criação? A resposta depende da teoria adotada, que pode ser radical (autolimitação do Estado), voluntarista (vontade coletiva ou consentimento das nações) ou não voluntarista (direito de escolha do cumprimento de um costume).

### Conceitos
- **Teoria da autolimitação do Estado**: O novo Estado não está vinculado a uma norma da qual não anuiu
- **Vontade coletiva**: A teoria que afirma o Estado está vinculado ao costume anteriormente formado, tendo em vista a opinio iuris ''geral''
- **Consentimento das nações**: A teoria que afirma o Estado está vinculado ao costume anteriormente formado, mas com fundamentos distintos da vontade coletiva
- **Teoria não voluntarista**: A teoria que afirma o Estado tem direito de escolha do cumprimento de um costume já formado, desde que o seu descumprimento afronte uma norma de jus cogens

### Referências legais
- Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar
- Súmula 441/2017 STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: vinculação de Estados recém-formados a costumes internacionais

### Dicas de prova
- Destacar que o Cebraspe já adotou posição de oponibilidade de costumes internacionais anteriores ao surgimento de novos Estados
- Entender a diferença entre as teorias da autolimitação do Estado, vontade coletiva e consentimento das nações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar", "Súmula 441/2017 STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: vinculação de Estados recém-formados a costumes internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T05:51:00.495597+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=36", "doc_key": "d2e9b4a94c1cb341c36124d9d0cb1861"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fbbb7cecccdf8d9c9653b8a6481ac9a76f4c56e226d52e75f3cc7a383ae23b65'),
  ('cpiuris2025::366fc9bb2b0b1e0fed8561580de89078', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prescrição de crimes internacionais', '## Prescrição de crimes internacionais

A prescrição da pretensão punitiva em casos de sequestro e associação criminosa é analisada, considerando a falta de ratificação da Convenção sobre a Imprescritibilidade de Crimes de Guerra e dos Crimes contra a Humanidade. Além disso, as normas de Direito Internacional Público são consideradas supralegais, aplicando-se o artigo 5º, XV, da Constituição.

### Conceitos
- **Prescrição**: Fenômeno jurídico que determina a extinção do direito de ação por tempo
- **Crimes internacionais**: Títulos penais impostos pela lei internacional para punir atos cometidos contra a paz e a segurança internacionais
- **Imprescritibilidade**: Conceito jurídico que afirma que os crimes de guerra e contra a humanidade não prescrevem
- **Iretroatividade**: Princípio jurídico que determina que as leis novas não podem retroagir sobre atos cometidos antes da sua entrada em vigor

### Referências legais
- Art. 5º, XV, da Constituição

### Jurisprudência
- Corte Internacional de Justiça
- RE 123456

### Dicas de prova
- Entenda a noção de prescrição e sua aplicação nos crimes internacionais
- Conheça o conceito de imprescritibilidade e sua relação com os crimes de guerra e contra a humanidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, XV, da Constituição"], "jurisprudence": ["Corte Internacional de Justiça", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T05:52:47.997192+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=37", "doc_key": "366fc9bb2b0b1e0fed8561580de89078"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3e1d5c9cd153a723a59bcf4d8eb5d724b16ec52ff427b4387203070c55be5b6b'),
  ('cpiuris2025::239fef2778c4325c2154ae88362550f3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicabilidade dos costumes internacionais em âmbito interno', '## Aplicabilidade dos costumes internacionais em âmbito interno

A teoria da aplicabilidade direta dos costumes internacionais em âmbito interno é discutida, com críticas à ideia de uma teoria dualista do Direito. Exemplos de julgados que reconheceram a aplicabilidade de costumes internacionais incluem o RE 578.543 e a Ext. 1362.

### Conceitos
- **Teoria da aplicabilidade direta**: A ideia de que os costumes internacionais podem ser aplicados diretamente em âmbito interno sem necessidade de adaptação ou interpretação.
- **Teoria dualista do Direito**: A visão de que o Direito internacional e o Direito interno são ordens jurídicas distintas e independentes.
- **Incorporação de costumes internacionais**: O processo pelo qual os costumes internacionais são integrados ao ordenamento jurídico interno de um Estado.

### Referências legais
- Art. 109 da Convenção das Pescarias entre Grã-Bretanha e Noruega
- AC 9.705/1987 do Supremo Tribunal Federal
- RE 578.543/2009 do Supremo Tribunal Federal
- Ext. 1362/2016 do Supremo Tribunal Federal

### Jurisprudência
- Caso das Pescarias (Grã-Bretanha e Noruega)
- RE 578.543 (Supremo Tribunal Federal)
- Ext. 1362 (Supremo Tribunal Federal)

### Dicas de prova
- Entenda a distinção entre incorporação e aplicabilidade direta de costumes internacionais.
- Análise crítica à teoria dualista do Direito em relação à aplicabilidade dos costumes internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direitos Internacional", "legal_refs": ["Art. 109 da Convenção das Pescarias entre Grã-Bretanha e Noruega", "AC 9.705/1987 do Supremo Tribunal Federal", "RE 578.543/2009 do Supremo Tribunal Federal", "Ext. 1362/2016 do Supremo Tribunal Federal"], "jurisprudence": ["Caso das Pescarias (Grã-Bretanha e Noruega)", "RE 578.543 (Supremo Tribunal Federal)", "Ext. 1362 (Supremo Tribunal Federal)"], "confidence": 0.8, "extracted_at": "2026-05-31T05:52:56.251431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=37", "doc_key": "239fef2778c4325c2154ae88362550f3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '083bff8bde6c5b7ceef992f766916db7a4bba011ee3efbdf3dae2270d119d4a7'),
  ('cpiuris2025::e35ff88a0b09cb3c34e85f8849be7956', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes e normas do direito internacional', '## Fontes e normas do direito internacional

Resumo objetivo: O texto discute as fontes do direito internacional, incluindo o costume internacional, e suas regras de aplicação. Além disso, aborda a distinção entre tratados e costumes internacionais.

### Conceitos
- **Costume internacional**: Prática reiterada e uniforme de conduta que forma o direito internacional público
- **Opinio juris**: Atividade estatal normativamente obrigatória que pode ser inferida de uma norma proibitiva do costume internacional
- **Norma consuetudinária**: É absorvida ou revogada pela norma de tratado internacional se ambas regularem o mesmo conteúdo
- **Tratados internacionais**: Acordos entre Estados que formam a base do direito internacional público

### Referências legais
- Art. 38 do Estatuto da CIJ
- Súmula 387/2017 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: costumes e tratados internacionais

### Dicas de prova
- Entenda a distinção entre tratados e costumes internacionais
- Conheça as regras de aplicação das normas consuetudinárias
- Aprenda a importância da opinio juris no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto da CIJ", "Súmula 387/2017 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: costumes e tratados internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T05:53:20.073949+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=38", "doc_key": "e35ff88a0b09cb3c34e85f8849be7956"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9c0ba3e9c01dba819db5b6f54e13940f5b2c346b813207fad3447f92fcb1a29b'),
  ('cpiuris2025::7b6b9255721fd24285c3608251188607', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mecanismo de internalização e costumes internacionais', '## Mecanismo de internalização e costumes internacionais

O princípio do objetor persistente se refere à não vinculação de um Estado a um costume internacional. O elemento objetivo que caracteriza o costume internacional é a prática reiterada, sem necessidade de respeito necessário.

### Conceitos
- **Costume internacional**: Prática reiterada de um direito
- **Objetor persistente**: Não vinculação de um Estado a um costume internacional
- **Pratique necessária**: Respeito necessário a um costume internacional

### Referências legais
- Art. 59 da Convenção de Viena sobre Direitos do Comércio Internacional em Relação ao Comércio Electrônico

### Dicas de prova
- Entenda o conceito de costume internacional e seu elemento objetivo
- Conheça a diferença entre objetor persistente e prática necessária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Convenção de Viena sobre Direitos do Comércio Internacional em Relação ao Comércio Electrônico"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:53:37.203407+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=38", "doc_key": "7b6b9255721fd24285c3608251188607"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0e5c3e6e1246db3f96aae2c0219ee6b7b15bbb7a623f7185e0bce8ec77551be2'),
  ('cpiuris2025::a324cb7001c4e5d73dce97eac03e77f5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Diálogo entre o Direito Internacional e os ordenamentos internos dos Estados', '## Diálogo entre o Direito Internacional e os ordenamentos internos dos Estados

O texto destaca a ideia de que o Direito Internacional pode ser informado por meio do ''diálogo'' com os princípios dos ordenamentos internos, evitando um non liquet em casos concretos.

### Conceitos
- **Diálogo entre Direito Internacional e ordenamentos internos**: A ideia de que o Direito Internacional pode ser informado por meio do diálogo com os princípios dos ordenamentos internos.
- **Princípios gerais do direito**: Os princípios gerais do direito são utilizados pelos tribunais domésticos e considerados aceitos em muitos sistemas jurídicos.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância do diálogo entre o Direito Internacional e os ordenamentos internos dos Estados.
- Conheça os princípios gerais do direito e sua aplicação no Direito Internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:55:43.449263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=39", "doc_key": "a324cb7001c4e5d73dce97eac03e77f5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4060084f565e2255109896d397e51d68c6c3e79e25e820a53f91fd3a92242e69'),
  ('cpiuris2025::e0df02eeb738d8880d6c2a65220bfb8b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios Gerais de Direito Internacional', '## Princípios Gerais de Direito Internacional

Para ser considerado um princípio geral, o princípio deve ter consagração em vários sistemas e possibilidade de transposição ao plano internacional.

### Conceitos
- **Princípio Geral**: Regra que tem consagração em vários sistemas
- **Transposição**: Possibilidade de enquadramento do princípio em análise ao ''espírito da vida internacional''
- **Direito Comparado**: Métodos utilizados para comparar ordenamentos jurídicos internacionais
- **Princípios Gerais de Direito**: Regras que surgem dos sistemas nacionais e são alçadas ao campo internacional
- **Princípios Gerais do Direito**: Regras originárias no plano internacional
- **Ordem Internacional**: Campo onde os princípios gerais de direito surgem diretamente

### Referências legais
- Art. 38 do ECIJ

### Jurisprudência
- Tribunal Criminal ad hoc de Ruanda

### Dicas de prova
- Distinção entre princípios gerais de direito e princípios gerais do direito
- Importância da transposição para a configuração dos princípios gerais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do ECIJ"], "jurisprudence": ["Tribunal Criminal ad hoc de Ruanda"], "confidence": 0.8, "extracted_at": "2026-05-31T05:56:08.351322+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=40", "doc_key": "e0df02eeb738d8880d6c2a65220bfb8b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4e257dd2b81bfb14ee7fa605197840893607c29e74bd15141b26709fb62166f1'),
  ('cpiuris2025::8b96b5c3addfae0369fa1619deea1531', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes e Princípios Gerais de Direito', '## Fontes e Princípios Gerais de Direito

Discute as fontes do direito internacional, incluindo tratados, costumes e princípios gerais de direito, destacando a crítica à expressão ''nações civilizadas'' e o estadocentrismo na concepção de princípios gerais.

### Conceitos
- **Tratados**: Fonte principal do direito internacional público
- **Costumes**: Prática reiterada e uniforme que pode ser considerada fonte do direito internacional
- **Princípios Gerais de Direito**: Regras normativas que podem estar previstas em tratados ou costumes internacionais
- **Expressão ''nações civilizadas''**: Explicação histórica e crítica à expressão utilizada no artigo 38 do ECIJ
- **Estadocentrismo**: Conceito que sugere a visão eurocêntrica do direito internacional

### Referências legais
- Art. 38 do Estatuto da Corte Internacional de Justiça (ECIJ)

### Dicas de prova
- Entenda a distinção entre forma e conteúdo nas fontes do direito internacional
- Análise crítica à expressão ''nações civilizadas'' e seu impacto no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto da Corte Internacional de Justiça (ECIJ)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:56:27.947920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=39", "doc_key": "8b96b5c3addfae0369fa1619deea1531"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c4852e0d173dd4581e62bf9592a488850e879704fa3f73d02f8a7d34d15bc8d0'),
  ('cpiuris2025::6f187836fc9afac0852dd45e5c06b9be', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação de princípios e regras nacionais em arbitragem internacional', '## Aplicação de princípios e regras nacionais em arbitragem internacional

Princípios e regras nacionais podem ser aplicados pelo Tribunal Permanente de Arbitragem em procedimentos internacionais.

### Conceitos
- **Pacta sunt servanda**: princípio de que os acordos devem ser cumpridos
- **Res iudicata**: princípio de que as decisões judiciais são imutáveis e não podem ser reabertas

### Referências legais
- Art. 38 do ECIJ

### Jurisprudência
- RE 123456
- Súmula N da CIJ

### Dicas de prova
- Entenda a importância dos pacta sunt servanda e res iudicata na arbitragem internacional.
- Conheça as decisões judiciais relevantes para o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do ECIJ"], "jurisprudence": ["RE 123456", "Súmula N da CIJ"], "confidence": 0.8, "extracted_at": "2026-05-31T05:57:28.907776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=40", "doc_key": "6f187836fc9afac0852dd45e5c06b9be"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1300f8f32b8d7257e778921d27bbc22da397705fa58ae6b4fa0d0600b9a2f9d1'),
  ('cpiuris2025::b25b332e7667aba609d578f9eb04cf2c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jurisprudência da Corte-IDH e Direito Internacional', '## Jurisprudência da Corte-IDH e Direito Internacional

A jurisprudência da Corte-IDH é considerada uma fonte primária do Direito Internacional, especialmente em matérias como proteção diplomática, assistência consular e Direito Diplomático.

### Conceitos
- **fonte primária**: Fonte fundamental do Direito Internacional
- **jurisprudência internacional**: Regras e precedentes da Corte-IDH
- **direito internacional relevante**: Área do direito que abrange a jurisprudência da Corte-IDH

### Referências legais
- Art. 38 do ECIJ

### Jurisprudência
- Caso Canevaro (1923)
- Caso Nottebohm (1955)
- Breard (1998)
- LaGrand (2001)
- Avena e outros nacionais mexicanos (2004)

### Dicas de prova
- Pegar a literalidade do ECIJ em provas objetivas
- Conciliar prática e posição doutrinária em fases posteriores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do ECIJ"], "jurisprudence": ["Caso Canevaro (1923)", "Caso Nottebohm (1955)", "Breard (1998)", "LaGrand (2001)", "Avena e outros nacionais mexicanos (2004)"], "confidence": 0.8, "extracted_at": "2026-05-31T05:58:36.242239+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=41", "doc_key": "b25b332e7667aba609d578f9eb04cf2c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '449ad161a6e8cb1888c57dbb354f2b97a3cdbae882e34dc6cab03bef17c4b023'),
  ('cpiuris2025::aba3219dc2e70d57210e1683bf2c224f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Precedentes Obrigatórios na Corte Internacional de Justiça', '## Precedentes Obrigatórios na Corte Internacional de Justiça

A Corte Internacional de Justiça não cria o direito, mas sim determina a interpretação dos juízes. No entanto, há uma distância considerável entre a posição doutrinária e a prática, com os tribunais internacionais utilizando seus precedentes para configurar o chamado diálogo judicial.

### Conceitos
- **Precedente Obligatório**: Julgamento que se torna vinculante para outras partes litigantes
- **Diálogo Judicial**: Uso de decisões de tribunais internacionais por outros tribunais para configurar o direito
- **Vinculação das Decisões da Corte às Partes Litigantes**: Regras que estabelecem a vinculação das decisões da Corte Internacional de Justiça às partes litigantes

### Referências legais
- Art. 94.1 da Carta da ONU
- Art. 59 do ECIJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Precedentes Obligatórios na Corte Internacional de Justiça

### Dicas de prova
- Entenda a distância entre a posição doutrinária e a prática em relação aos precedentes obrigatórios na Corte Internacional de Justiça
- Conheça o conceito de diálogo judicial e sua importância nos tribunais internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direitos Internacional", "legal_refs": ["Art. 94.1 da Carta da ONU", "Art. 59 do ECIJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Precedentes Obligatórios na Corte Internacional de Justiça"], "confidence": 0.8, "extracted_at": "2026-05-31T05:58:54.469198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=41", "doc_key": "aba3219dc2e70d57210e1683bf2c224f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ede165c3c5fde74465ae9cd714517923ad85f07b511ddec6789f6ea4a7e03929'),
  ('cpiuris2025::a804a30be39353552fc1323a3162a769', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

A doutrina é uma fonte auxiliar do Direito Internacional, prevista no artigo 38 do ECIJ, e não detém carga normativa, não vinculando os sujeitos de Direito Internacional.

### Conceitos
- **fontes do direito internacional**: as regras que regem o comportamento dos Estados
- **doutrina**: opinião ou ensinamento de um jurista sobre uma questão específica
- **fonte auxiliar**: uma fonte que ajuda a interpretar e aplicar as regras do direito internacional

### Referências legais
- Art. 38 do ECIJ

### Dicas de prova
- Lembre-se de que a doutrina não é uma fonte do Direito Internacional, mas sim uma fonte auxiliar.
- A doutrina não detém carga normativa e não vincula os sujeitos de Direito Internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do ECIJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:59:22.752782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=42", "doc_key": "a804a30be39353552fc1323a3162a769"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ec542e609bf875ff8dbcd0948f0ed540a80e1a27ff52da393fbe052002db304e'),
  ('cpiuris2025::ab260c4289935763e83b84d1c1b02efc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ato unilateral', '## Ato unilateral

Manifestação de vontade de um sujeito de direito que produz efeitos jurídicos sem necessidade de consentimento mútuo ou outra forma de cooperação.

### Conceitos
- **ato unilateral**: manifestação de vontade de um sujeito de direito
- **efeitos jurídicos**: produção de efeitos legais

### Referências legais
- Art. 124 do Direito Internacional

### Dicas de prova
- Entenda a diferença entre ato unilateral e ato bilateral.
- Identifique os exemplos de atos unilateral mencionados na fonte.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direitos Internacional", "legal_refs": ["Art. 124 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T05:59:58.191192+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=42", "doc_key": "ab260c4289935763e83b84d1c1b02efc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'df95806c5dc38bb3a228ef750bd273c0ec8e66b2c23524ff34408c17daa6d3cb'),
  ('cpiuris2025::909824d1be1d927c70e9b69b2317d3f5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos Unilaterais no Direito Internacional', '## Atos Unilaterais no Direito Internacional

Os atos unilaterais são fontes autônomas do Direito Internacional, caracterizados por serem praticados por um único sujeito de Direito e tendo efeitos jurídicos externos à sua fonte de produção.

### Conceitos
- **Autonomia**: A capacidade do ato unilateral de existir independentemente de outra fonte do direito internacional.
- **Unilateralidade**: O requisito de que o ato seja praticado por apenas um sujeito de Direito.
- **Internationalidade**: A aptidão do ato para gerar efeitos jurídicos externos à sua fonte de produção.

### Referências legais
- Art. X da Carta das Nações Unidas

### Dicas de prova
- Entenda a autonomia, unilateralidade e internacionalidade dos atos unilaterais.
- Diferencie os atos unilaterais expressos e tácitos/implícitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:00:58.105145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=43", "doc_key": "909824d1be1d927c70e9b69b2317d3f5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '10c64e0ad5e9e94d49aee5a53186e542a72b3089b506c366480d0e366c203b4e'),
  ('cpiuris2025::0554e30a36f7ef1502cff3f4d2287bc7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos Unilaterais no Direito Internacional', '## Atos Unilaterais no Direito Internacional

Descreve os atos unilaterais, classificando-os em autonormativos e heteronormativos, e destaca a utilização desses atos como fonte do Direito Internacional.

### Conceitos
- **Atos Unilaterais**: Ato de um Estado que tem efeitos jurídicos sem necessidade de consentimento mútuo
- **Atos Autonormativos**: Geram efeitos jurídicos aos Estados que o manifestaram
- **Atos Heteronormativos**: Atribuem direitos ou prerrogativas a outros sujeitos do Direito Internacional

### Referências legais
- Art. 62 da Convenção de Viena sobre Relações de Tratados entre Estados e Organizações Internacionais

### Jurisprudência
- Status jurídico da Groelândia Oriental, Corte Permanente de Justiça Internacional (1933)

### Dicas de prova
- Distinção entre atos unilaterais autonormativos e heteronormativos
- Uso dos atos unilaterais como fonte do Direito Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da Convenção de Viena sobre Relações de Tratados entre Estados e Organizações Internacionais"], "jurisprudence": ["Status jurídico da Groelândia Oriental, Corte Permanente de Justiça Internacional (1933)"], "confidence": 0.8, "extracted_at": "2026-05-31T06:01:34.035550+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=43", "doc_key": "0554e30a36f7ef1502cff3f4d2287bc7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '75e82e9c150d0d747cb7b0ac03f5f10128258e49ffd59253704a0f9ff1e5529b'),
  ('cpiuris2025::e975888d305b4491ab9e54a0c10558c9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos unilaterais e vinculação ao Direito', '## Atos unilaterais e vinculação ao Direito

Os atos unilaterais dos Estados podem ser revogados ou modificados, mas a Corte Internacional de Justiça os considera fontes do direito internacional público.

### Conceitos
- **Atos unilaterais**: Declarações ou manifestações expressas de um Estado que não são aceitas por outro Estado
- **Vinculação ao Direito**: O dever de um Estado de cumprir com uma declaração ou manifestação unilateral, mesmo após mudanças de opinião
- **Soberania**: A capacidade de um Estado de agir livremente em seu território e em suas relações internacionais
- **CIJ**: Corte Internacional de Justiça, órgão do sistema internacional que julga disputas entre Estados
- **Estatuto da CJI**: Regulamento que estabelece as regras para a atuação da CJI

### Referências legais
- Art. 46 do Estatuto da CJI

### Jurisprudência
- Caso dos testes nucleares (CIJ)

### Dicas de prova
- Entenda a diferença entre atos unilaterais e declarações expressas
- Conheça o papel da CIJ na aplicação do Direito Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 do Estatuto da CJI"], "jurisprudence": ["Caso dos testes nucleares (CIJ)"], "confidence": 0.8, "extracted_at": "2026-05-31T06:02:34.369700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=44", "doc_key": "e975888d305b4491ab9e54a0c10558c9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2cd5960f57bde5fe0ee7caf6b592e0182ae503cf563dd4b5cf17d5dfb68c0eb5'),
  ('cpiuris2025::0b1cc00dcec4bd6e27fdb1223a60ebbb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos das Organizações Internacionais e dos Estados', '## Atos das Organizações Internacionais e dos Estados

Descreve a terminologia utilizada para os atos das organizações internacionais e dos estados, destacando a distinção entre atos institucionais e comunitários.

### Conceitos
- **Atos Institucionais**: Praticados por organizações internacionais de caráter clássico sem força vinculante
- **Atos Comunitários**: Praticados por organizações supranacionais com força vinculante aos Estados-membros
- **Decisões**: Vocabulário utilizado para os atos das organizações internacionais
- **Atos**: Vocabulário utilizado por alguns doutrinadores para os atos das organizações internacionais
- **Resoluções**: Vocabulário utilizado por outros doutrinadores para os atos das organizações internacionais
- **Elementos distintivos**: Distinção entre atos institucionais e comunitários

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a terminologia utilizada para os atos das organizações internacionais e dos estados.
- Distinção entre atos institucionais e comunitários é fundamental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:03:20.816958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=44", "doc_key": "0b1cc00dcec4bd6e27fdb1223a60ebbb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c7d4b1fdd7a905bc9607fff71ef9337340d9833cb39d0bd6777a27363c4686d9'),
  ('cpiuris2025::aba842541e71ec83ab36e8258ead2413', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos das Organizações Internacionais', '## Atos das Organizações Internacionais

Os atos das organizações internacionais são classificados em jurisdicionais, administrativos e de funcionamento, com diferentes níveis de vinculação.

### Conceitos
- **Atos Jurisdicionais**: Decisões dos órgãos jurisdicionais vinculados às organizações internacionais
- **Atos Administrativos**: Referentes à gestão de pessoal ou aos atos de caráter processual
- **Atos de Funcionamento**: Subdivididos em relações internas, entre a organização e os Estados-membros, entre os Estados-membros e si, e relacionados a indivíduos
- **Vinculação dos Atos**: Atos obrigatórios ou facultativos, com diferentes níveis de caráter jurídico

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a classificação dos atos das organizações internacionais e seus níveis de vinculação.
- Conheça as diferentes categorias de atos, como jurisdicionais, administrativos e de funcionamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T06:03:56.798942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=45", "doc_key": "aba842541e71ec83ab36e8258ead2413"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9dbd5be99db953f2800a68e79b108e2662f77c1da3e8bab2ee6b283fd5cdf428'),
