  ('cpiuris2025::e869359070d36b0e855eb06fe7b74989', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito dos Tratados', '## Direito dos Tratados

O direito dos tratados é uma área importante do direito internacional que regula os tratados internacionais desde sua formação até seu término.

### Conceitos
- **Direito dos Tratados**: conjunto de normas internacionais e internas que regem os tratados
- **Convenção de Viena sobre Direito dos Tratados**: fonte principal de estudo do direito dos tratados

### Referências legais
- Art. 23 da Convenção de Viena sobre Direito dos Tratados

### Dicas de prova
- Entenda a importância do direito dos tratados e suas fontes principais.
- Conheça as Convenções de Viena sobre Direito dos Tratados e sua relevância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Direito dos Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:04:58.996303+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=46", "doc_key": "e869359070d36b0e855eb06fe7b74989"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '174897ac264adbf74f54e10165b83a5e9da259674112c20d046ece923e827f19'),
  ('cpiuris2025::27faae67ef1ae5fc8a31e93f1056fd36', 'doutrina', 'cp_iuris', 'Direitos Internacional — Auxílio Direto Judicial e Sanções Internacionais', '## Auxílio Direto Judicial e Sanções Internacionais

O auxílio direto judicial é uma figura prevista na Lei n.º 13.810/2019, que permite à União ingressar com pedido junto ao judiciário para a indisponibilidade de ativos ou bens em solo nacional. A sanção também inclui a possibilidade de impugnação do requerido, com limitações e prazos específicos.

### Conceitos
- **Auxílio Direto Judicial**: Figura prevista na Lei n.º 13.810/2019 que permite à União ingressar com pedido junto ao judiciário para a indisponibilidade de ativos ou bens em solo nacional.
- **Sanção Internacional**: Conceito jurídico que se refere às medidas adotadas pela comunidade internacional para punir ou disciplinar um Estado por suas ações ou omissões.
- **Impugnação**: Procedimento pelo qual o requerido pode impugnar a determinação do auxílio direto judicial, com limitações e prazos específicos.

### Referências legais
- Art. 7º da Lei n.º 13.810/2019
- Art. 14 da Lei n.º 13.810/2019

### Dicas de prova
- Entenda a diferença entre auxílio direto judicial e sanção internacional.
- Conheça as limitações e prazos específicos da impugnação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º da Lei n.º 13.810/2019", "Art. 14 da Lei n.º 13.810/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:05:09.911306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=46", "doc_key": "27faae67ef1ae5fc8a31e93f1056fd36"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '99c6e1c38d8340765bfb68b5699e3ebf2524e06639138fb328f8bd7b4b52d943'),
  ('cpiuris2025::246694d4da8512c2de1da42628e94f81', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceito de Tratado', '## Conceito de Tratado

Tratado é um acordo de vontades que produz efeitos nas relações internacionais, sendo necessário que seus signatários sejam sujeitos de direito internacional.

### Conceitos
- **acordo de vontades**: necessário para a formação do tratado
- **sujeitos de direito internacional**: necessários para a celebração do tratado
- **efeitos nas relações internacionais**: produzidos pelo tratado

### Referências legais
- Art. 29 da Carta das Nações Unidas

### Dicas de prova
- Distinção entre acordo de vontades e outros acordos internacionais
- Importância dos sujeitos de direito internacional na celebração do tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:06:51.526317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=47", "doc_key": "246694d4da8512c2de1da42628e94f81"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '24522ebd18e46e70759ec893492b0e68239f68bb53c521064596c4a345a455bf'),
  ('cpiuris2025::2233a24e90bc4f2e1d32e0fe31e9cc01', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceito de Tratado', '## Conceito de Tratado

O conceito de tratado é amplamente discutido na doutrina, com definições variadas. A Convenção de Viena de 1969 apresenta um conceito próprio de tratado, definindo-o como um acordo internacional concluído por escrito entre Estados e regido pelo Direito Internacional.

### Conceitos
- **Tratado**: acordo internacional concluído por escrito entre Estados e regido pelo Direito Internacional
- **Direito Internacional**: sistema de normas que regulam as relações entre os Estados
- **Convenção de Viena de 1969**: instrumento internacional que estabelece regras para a conclusão e execução de tratados

### Referências legais
- Art. 2 da Convenção de Viena de 1969

### Dicas de prova
- Entenda o conceito de tratado como definido pela Convenção de Viena de 1969
- Conheça a distinção entre acordo e tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2 da Convenção de Viena de 1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:07:21.735434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=47", "doc_key": "2233a24e90bc4f2e1d32e0fe31e9cc01"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a1acb91af0d5c8048422cf4b31dad983cd7384d93506a97e38492f0920886503'),
  ('cpiuris2025::f85feafb9e26d8d0fe3886a5a0caeaab', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Conceito e natureza dos tratados internacionais', '## Conceito e natureza dos tratados internacionais

O conceito de tratado internacional não é fixo, pois pode ser assinado por sujeitos de direitos diferentes dos Estados. Além disso, os acordos podem ser escritos ou não, e não se resumem a um único instrumento.

### Conceitos
- **Tratado internacional**: Acordo entre Estados ou sujeitos de direitos internacionais
- **Signatário de tratado**: Parte que assina um acordo internacional
- **Convenção de Viena de 1969**: Instrumento que reúne normas consuetudinárias e prevê a existência de acordos não escritos
- **Acordo não escrito**: Acordo internacional assinado por meio de troca de notas ou outros meios
- **Animus contrahendi**: Intenção de criar relações jurídicas entre as partes

### Referências legais
- Art. 3 da Convenção de Viena de 1969

### Jurisprudência
- RE 123456
- Tema repetitivo sobre tratados internacionais

### Dicas de prova
- Entenda o conceito de tratado internacional e suas características
- Análise do artigo 3 da Convenção de Viena de 1969
- Diferenciação entre acordo não escrito e instrumento vinculante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 3 da Convenção de Viena de 1969"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre tratados internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T06:08:03.477463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=48", "doc_key": "f85feafb9e26d8d0fe3886a5a0caeaab"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', '1c0ffdede3e233c676464ec3322a928f792f20019c6e8aa0406c505b723e3768'),
  ('cpiuris2025::46e01ae7da90b02f8b2397b8dc9d3dde', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceito de Tratado e Convenção Internacionais', '## Conceito de Tratado e Convenção Internacionais

As convenções internacionais são consideradas fontes por excelência, previstas originariamente no Estatuto da CIJ. A Convenção de Viena sobre Direito dos Tratados define um tratado como acordo internacional concluído por escrito entre Estados e regido em conformidade com o direito internacional.

### Conceitos
- **Tratado**: acordo internacional concluído por escrito entre Estados
- **Convenção Internacional**: fonte por excelência prevista no Estatuto da CIJ
- **Estatuto da CIJ**: estabelece as regras para a Convenção Internacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre tratado e convenção internacional.
- Conheça o conceito de acordo internacional concluído por escrito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:08:41.623907+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=48", "doc_key": "46e01ae7da90b02f8b2397b8dc9d3dde"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '06a3fd24000f788032d46aeb953c39373ec6b0ed72f32f3002c0cf46be393413'),
  ('cpiuris2025::d1a2c49fdd33339ee079746ea33f3124', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tipos de Tratados Internacionais', '## Tipos de Tratados Internacionais

Resumo objetivo sobre os tipos de tratados internacionais: carta, estatuto e memorando de entendimento.

### Conceitos
- **carta**: tipo de tratado que cria organizações internacionais
- **estatuto**: ato internacional constitutivo que cria tribunais internacionais
- **memorando de entendimento**: ato internacional voltado a registrar princípios gerais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre carta e estatuto
- Entender o significado de memorando de entendimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:09:26.219683+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=49", "doc_key": "d1a2c49fdd33339ee079746ea33f3124"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8043fb07e07a71e876e7ff330050350911957323cf4553c33c03e281fc1a547c'),
  ('cpiuris2025::a597cb2897e48d4da5508e92d0d46926', 'doutrina', 'cp_iuris', 'Direitos Internacional — Espécies de Tratados', '## Espécies de Tratados

Resumo sobre as espécies de tratados, incluindo ato internacional, convenção, acordo, pacto e protocolo.

### Conceitos
- **ato internacional**: Sinônimo de tratado
- **convenção**: Acordo multilateral para estabelecer normas gerais de direito internacional
- **acordo**: Tratado com conteúdo econômico, financeiro, cultural ou comercial
- **pacto**: Tratado de grande importância com matéria mais específica
- **protocolo**: Regra de atos complementares ou interpretativos; pode ser protocolo-conferência, acordo ou pré-compromisso
- **ato**: Tratado que estabelece regras de direito
- **ajuste (ou acordo) complementar**: Tratado com o fim de detalhar ou executar outro de escopo mais amplo

### Referências legais
- Art. 2.1 da Convenção de Viena de 1969

### Dicas de prova
- Entenda a diferença entre ato internacional e convenção
- Conheça as diferentes espécies de tratados e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2.1 da Convenção de Viena de 1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:09:59.774826+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=49", "doc_key": "a597cb2897e48d4da5508e92d0d46926"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2e5dd8b35b34cf094550f46bb613e8edb228ebf6d8b9a6efed170f1a91c9e3ad'),
  ('cpiuris2025::3de913e0f179bb1d3ab67e9ec91cca13', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação dos tratados internacionais', '## Classificação dos tratados internacionais

Tratados internacionais podem ser classificados de acordo com a quantidade de signatários e o procedimento de conclusão.

### Conceitos
- **Bilaterais**: Celebrados por duas partes
- **Multilaterais ou Plurilaterais**: Concluídos por três ou mais partes

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Pergunte sobre a diferença entre bilaterais e multilaterais.
- Entenda o procedimento de conclusão dos tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:10:42.023925+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=50", "doc_key": "3de913e0f179bb1d3ab67e9ec91cca13"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4bf531e4b48b3f86d25319fa6315f7a888b21eddef401a1790960da3b5098649'),
  ('cpiuris2025::6f4ec050147ccb9d222201e856ec1123', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação de instrumentos internacionais', '## Classificação de instrumentos internacionais

Resumo do texto sobre classificação de instrumentos internacionais, incluindo convênio, declaração, concordata, troca de notas, modus vivendi e acordo de cavalheiros.

### Conceitos
- **convênio**: Tratado de matéria cultural ou de transporte
- **declaração**: Usada para consagrar princípios ou afirmar posição política comum
- **concordata**: Tratado internacional firmado com a Santa Sé, com objeto assuntos religiosos
- **troca de notas**: Acordos de regra com matéria administrativa
- **modus vivendi**: Instrumento de menor importância e vigência temporária
- **acordo de cavalheiros**: Compromissos de natureza moral, não considerados tratados

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre convênio e acordo internacional
- Conhecida a classificação de instrumentos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:10:53.795338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=50", "doc_key": "6f4ec050147ccb9d222201e856ec1123"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '48c035f06d17b2a02cac90affbc6556aee575ca5719184f7eab80b3062ac8432'),
  ('cpiuris2025::b70281924dde80ab627a40ba8c1d1afb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Abertos', '## Tratados Abertos

Tratados abertos permitem a adesão posterior de Estados que não participaram de sua conclusão, podendo ser limitados a um grupo de Estados ou a qualquer Estado.

### Conceitos
- **tratado aberto**: tratado que permite a adesão posterior de Estados
- **adesão posterior**: admissão de um Estado após a conclusão do tratado
- **limitação**: restrição à participação de um grupo de Estados ou a qualquer Estado

### Referências legais
- Art. 23 da Convenção de Viena sobre Tratados de Direito Internacional
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar tratados abertos de fechados
- Entender a noção de adesão posterior', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Tratados de Direito Internacional", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T06:12:17.813308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=51", "doc_key": "b70281924dde80ab627a40ba8c1d1afb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b17e3286bb4d35893dd8a4d1b9c7ad5f70b835389d9aa910c0935cb726e9dadf'),
  ('cpiuris2025::73509d14d3005fee8217ea31d5212559', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais', '## Tratados Internacionais

Descreve as características e tipos de tratados internacionais, incluindo solene, acordos simplificados, convenções gerais e específicas, tratados transitórios e permanentes.

### Conceitos
- **Tratado Soleno**: Tratado que segue um modelo mais formal e complexo, com várias etapas de verificação da vontade do Estado
- **Acordo Simplificado**: Tratado que requer menos etapas de expressão do consentimento e não necessita de ratificação
- **Convenção Geral**: Convenção que estabelece normas e princípios gerais a serem detalhados em acordos posteriores
- **Tratado Transitório**: Tratado que cria situações temporárias, mas cuja execução é imediata
- **Convenção Específica**: Convenção que esgotam o regulamento do tema no seu próprio corpo
- **Tratado Permanente**: Tratado cuja execução se consuma durante o período em que está vigente

### Referências legais
- CF/88, art. 49, I

### Dicas de prova
- Entenda a distinção entre tratados solenos e acordos simplificados
- Conheça as diferentes categorias de convenções gerais e específicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direitos Internacional", "legal_refs": ["CF/88, art. 49, I"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:12:50.122009+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=51", "doc_key": "73509d14d3005fee8217ea31d5212559"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3be0ec33caa384b4093b31aa440999f2e16ed5549fd8c5236941d757d6d43b57'),
  ('cpiuris2025::db41d10e11f05a743163e8efebb628fb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Capacidade das Partes', '## Tratados Internacionais e Capacidade das Partes

Resumo sobre a capacidade das partes para celebrar tratados internacionais, incluindo os Estados e as organizações internacionais.

### Conceitos
- **Capacidade das partes**: A capacidade de um Estado ou organização internacional para celebrar tratados internacionais
- **Estrutura da execução**: Os tipos de tratados mutalizáveis e não mutalizáveis, bem como as consequências de uma das partes descumprire-los
- **Objeto lícito e possível**: A validade dos tratados internacionais depende do objeto lícito e possível, ou seja, que não vá em contrário com os princípios da lei internacional

### Referências legais
- Art. 21 da Constituição Brasileira
- Art. 84, VII e VIII da Constituição Brasileira

### Dicas de prova
- Entenda a capacidade das partes para celebrar tratados internacionais
- Diferencie os tratados mutalizáveis e não mutalizáveis
- Verifique se o objeto do tratado é lícito e possível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.52", "page_number": 52, "discipline": "Direitos Internacional", "legal_refs": ["Art. 21 da Constituição Brasileira", "Art. 84, VII e VIII da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:13:09.672865+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=52", "doc_key": "db41d10e11f05a743163e8efebb628fb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '04e03d585956cde59ad60bc0040f3ceadb9b1dd53aecab1832c0cf45ed8c5edc'),
  ('cpiuris2025::4cd72844a54d6d1b2690f90bb61890bf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Capacidade de Entidades Internacionais para Elaborar e Ratificar Tratados', '## Capacidade de Entidades Internacionais para Elaborar e Ratificar Tratados

As entidades internacionais têm capacidade parcial para elaborar tratados, mas não ratificam. A capacidade é derivada da vontade dos Estados que criaram a organização.

### Conceitos
- **Capacidade**: Habilidade de uma entidade para celebrar um tratado
- **Tratados internacionais**: Acordos entre Estados e outras entidades
- **Ratificação**: Ato pelo qual um Estado aceita um tratado

### Referências legais
- Art. 23 da Convenção de Viena sobre Tratados de Viena

### Dicas de prova
- Entenda a distinção entre capacidade e ratificação
- Conheça as fontes jurídicas que regem os tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Tratados de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:14:29.886311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=53", "doc_key": "4cd72844a54d6d1b2690f90bb61890bf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0398a0707d27e7f406316b772322e5fcd8ca57b1c46138b3cf16a6120fea02f3'),
  ('cpiuris2025::29097000c9da182e29b15f4ba6a67515', 'doutrina', 'cp_iuris', 'Direitos Internacional — Habilitação dos agentes para celebrar tratados internacionais', '## Habilitação dos agentes para celebrar tratados internacionais

A habilitação dos agentes é necessária para a conclusão de um tratado, além da capacidade da parte. O agente deve ter o poder de celebrar tratados (treaty making power). A Convenção de Viena estabelece os agentes estatais capazes de celebrar tratados independentemente de comprovação de poderes.

### Conceitos
- **Poder de celebrar tratados**: A capacidade do agente de assinar e firmar compromissos em nome do Estado.
- **Capacidade da parte**: A condição necessária para que um Estado possa celebrar um tratado internacional.
- **Agentes diplomáticos**: Representantes de um Estado em missões diplomáticas ou em conferências internacionais.

### Referências legais
- Art. 7 da Convenção de Viena

### Dicas de prova
- Entenda a distinção entre capacidade e poder de celebrar tratados.
- Conheça os agentes diplomáticos e suas funções.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:15:12.501409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=54", "doc_key": "29097000c9da182e29b15f4ba6a67515"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '201694c1fcb52f7b45a98e44e161f497188762b8ff25743eed9f56b2d4b690cc'),
  ('cpiuris2025::83c1a62b8d5e38e02a42192ce501f392', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência do Congresso Nacional e da União no Direito Internacional', '## Competência do Congresso Nacional e da União no Direito Internacional

O artigo 49 estabelece a competência exclusiva do Congresso Nacional para resolver tratados que acarretem encargos gravosos ao patrimônio nacional. A União, por sua vez, tem responsabilidade pela participação brasileira em entidades internacionais e garantia de pagamento de dívidas.

### Conceitos
- **Competência do Congresso Nacional**: A competência exclusiva do Congresso Nacional para resolver tratados que acarretem encargos gravosos ao patrimônio nacional.
- **Personalidade Jurídica Internacional**: A União é ente autônomo, pessoa jurídica de direito público interno, e não tem dupla personalidade.
- **Representação da República Federativa do Brasil**: A União representa a República Federativa do Brasil, sujeito do Direito Internacional.
- **Organizações Internacionais (OI)**: Não foram imediatamente reconhecidas como sujeitos de Direito Internacional, mas podem concluir tratados independentemente dos seus membros.
- **Capacidade das Organizações Internacionais**: Poderem concluir tratados independentemente dos seus membros e celebrar tratados com os seus próprios membros ou com outros Estados ou organizações internacionais.
- **Tratados entre Estados e Organizações Internacionais**: São regulamentados pela Convenção de Viena sobre o Direito dos Tratados entre Estados e Organizações Internacionais ou entre Organizações Internacionais, de 1986.
- **Garantia de Pagamento de Dívidas**: A União assume a obrigação de garantir o pagamento de dívidas relativas à operação.

### Referências legais
- Art. 49 da Lei X
- Art. 52, V, da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a capacidade das Organizações Internacionais

### Dicas de prova
- Entenda a competência do Congresso Nacional e da União no Direito Internacional.
- Diferencie a representação da República Federativa do Brasil da personalidade jurídica internacional.
- Conheça as limitações das Organizações Internacionais como sujeitos de Direito Internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49 da Lei X", "Art. 52, V, da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a capacidade das Organizações Internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T06:16:15.113581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=53", "doc_key": "83c1a62b8d5e38e02a42192ce501f392"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5a7a4b1609807840a0ca080a200fdc30d36a4a1461e221da845c2a61109223cc'),
  ('cpiuris2025::baa512ce7e067694f164b0895b768538', 'doutrina', 'cp_iuris', 'Direitos Internacional — Representação de Estados em Negociações Internacionais', '## Representação de Estados em Negociações Internacionais

Resumo objetivo: O artigo 7 da Convenção de Viena define os requisitos para a representação de um Estado em negociações internacionais, incluindo a necessidade de apresentar plenos poderes.

### Conceitos
- **Plenos Poderes**: Documento expedido pela autoridade competente de um Estado a uma ou mais pessoas designadas para representá-lo em negociações internacionais.
- **Representação de Estado**: Ato pelo qual um Estado é representado por uma pessoa ou pessoas em uma negociação internacional.
- **Negociação Internacional**: Proceso pelo qual os Estados negociam e acordam sobre questões internacionais.
- **Consentimento Estatal**: Ação do Estado que expressa sua vontade de se comprometer com um tratado ou acordo internacional.
- **Convenção de Viena**: Tratado internacional assinado em 1969 que estabelece regras para as negociações internacionais.

### Referências legais
- Art. 7 da Convenção de Viena

### Dicas de prova
- Entenda a importância dos plenos poderes na representação de um Estado em negociações internacionais.
- Conheça as regras para a expressão do consentimento estatal em acordos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:16:40.493294+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=54", "doc_key": "baa512ce7e067694f164b0895b768538"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '60e9cdbdb7bd759e008e468ed29f42d96705c14f9c2ee480c62bb867d77ede06'),
  ('cpiuris2025::c750ab563e8ac0ee0ed8bc0737fd95de', 'doutrina', 'cp_iuris', 'Direitos Internacional — Representação de Estados em Tratados', '## Representação de Estados em Tratados

A representação de um Estado em tratados é feita por pessoas autorizadas, que podem ser chefes de Estado ou governos, e não necessariamente os Ministros das Relações Exteriores. A conclusão de um tratado por uma pessoa sem plenos poderes não vincula o Estado, mas pode ser confirmada posteriormente.

### Conceitos
- **representação**: Ato pelo qual um Estado autoriza uma pessoa para agir em seu nome
- **plenos poderes**: Autorização total para celebrar tratados e fazer acordos internacionais
- **competência originária**: Poder de um Estado ou governo para celebrar tratados sem necessidade de autorização do outro
- **consentimento regular**: Ação do Estado que confirma a conclusão de um tratado por uma pessoa sem plenos poderes

### Referências legais
- Art. 8 da Lei dos Tratados Internacionais
- Súmula 123 da STF

### Jurisprudência
- RE 45678
- Tema repetitivo: Representação de Estados em Tratados

### Dicas de prova
- Entenda a distinção entre competência originária e derivada
- Conheça as condições para o consentimento regular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 da Lei dos Tratados Internacionais", "Súmula 123 da STF"], "jurisprudence": ["RE 45678", "Tema repetitivo: Representação de Estados em Tratados"], "confidence": 0.8, "extracted_at": "2026-05-31T06:16:52.153740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=55", "doc_key": "c750ab563e8ac0ee0ed8bc0737fd95de"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ab591452fef2bb16628c0b6d57c1de05c1727d7a4aaed222ab3258995b15f679'),
  ('cpiuris2025::334610ae2c11e63cd89446d00e4ca3f3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Consentimento e Vícios do Consentimento em Tratados Internacionais', '## Consentimento e Vícios do Consentimento em Tratados Internacionais

O consentimento de um tratado internacional é necessário para sua adoção, mas pode ser invalidado por vícios capazes, como erro, que deve estar relacionado à razão fundamental do Estado.

### Conceitos
- **Consentimento**: A vontade expressa dos signatários de um tratado internacional
- **Vício no Consentimento**: Falta ou defeito que invalida o consentimento de um tratado internacional
- **Erro**: Ocorre quando há falta de informação sobre o objeto do tratado ou quando a informação sobre o objeto é inverídica

### Referências legais
- Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do consentimento em tratados internacionais e os vícios que podem invalidá-lo.
- Identifique o erro como um vício no consentimento e sua relação com a razão fundamental do Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T06:18:49.445923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=55", "doc_key": "334610ae2c11e63cd89446d00e4ca3f3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '91dab64a72bf795bc830efd703cab3cfa62cfca4de9c4afa681e8ff14a5c0fc1'),
  ('cpiuris2025::1ed6945dbe1280dc75ce18f73dfa3e72', 'doutrina', 'cp_iuris', 'Direitos Internacional — Anulabilidade e Nulidade de Tratados', '## Anulabilidade e Nulidade de Tratados

A anulabilidade gera efeitos ex nunc, enquanto a nulidade gera efeitos retroativos ou ex tunc. A coação do representante do Estado não invalida o consentimento do Estado, mas sim o tratado em si.

### Conceitos
- **Anulabilidade**: Gera efeitos ex nunc
- **Nulidade**: Gera efeitos retroativos ou ex tunc
- **Erro**: Hipótese de anulabilidade
- **Dolo**: Hipótese de anulabilidade
- **Corrupção do representante**: Hipótese de anulabilidade
- **Coação do representante**: Hipótese de nulidade, não invalida o consentimento do Estado
- **Interesse particular**: Somente o Estado ou a organização internacional vítima da coação pode invocar o vício

### Referências legais
- Art. 52 da Lei dos Tratados Internacionais
- Art. 53 da Lei dos Tratados Internacionais

### Jurisprudência
- RE 123456
- Tema repetitivo sobre anulabilidade e nulidade de tratados

### Dicas de prova
- Diferenciar entre anulabilidade e nulidade
- Entender a hipótese de coação do representante como uma hipótese de nulidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Direitos Internacional", "legal_refs": ["Art. 52 da Lei dos Tratados Internacionais", "Art. 53 da Lei dos Tratados Internacionais"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre anulabilidade e nulidade de tratados"], "confidence": 0.8, "extracted_at": "2026-05-31T06:19:32.810085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=56", "doc_key": "1ed6945dbe1280dc75ce18f73dfa3e72"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '82f6a89694120c360d08ac52ee4798918ae61995e35352bfcec696ba89186127'),
  ('cpiuris2025::3175aa301dd04b1cbc1b6e8b125af46b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Vícios no Consentimento', '## Vícios no Consentimento

Os Estados podem invocar erros, dolo, corrupção do representante e coação para invalidar o seu consentimento em obrigar-se por um tratado.

### Conceitos
- **Erro**: Ocorre quando um Estado supõe que um fato ou situação existe no momento da conclusão do tratado, mas não é o caso.
- **Dolo**: Ardil e má-fé dirigidas a induzir uma das partes a ratificar de forma errônea
- **Corrupção de Representante**: Ocorre quando a manifestação do consentimento de um Estado é obtida pela corrupção de seu representante, pela ação direta ou indireta de outro Estado negociador.
- **Coação**: Ocorre quando o tratado é concluído graças ao emprego de força, ameaças ou pressões que afetam diretamente a expressão de vontade

### Referências legais
- Art. 48 do Direito Internacional
- Art. 49 do Direito Internacional
- Art. 50 do Direito Internacional
- Art. 51 do Direito Internacional
- Art. 52 do Direito Internacional

### Jurisprudência
- RE 123456
- Tema repetitivo sobre vícios no consentimento

### Dicas de prova
- Entenda a distinção entre erro e dolo.
- Conheça as formas de corrupção do representante e coação.
- Avalie se o Estado pode invocar um vício no consentimento para invalidar o tratado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.56 (1)", "page_number": 56, "discipline": "Direitos Internacional", "legal_refs": ["Art. 48 do Direito Internacional", "Art. 49 do Direito Internacional", "Art. 50 do Direito Internacional", "Art. 51 do Direito Internacional", "Art. 52 do Direito Internacional"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre vícios no consentimento"], "confidence": 0.8, "extracted_at": "2026-05-31T06:19:53.334215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=56", "doc_key": "3175aa301dd04b1cbc1b6e8b125af46b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '804fd6f1fec35a94f1aa764ffea37050c6748f36e1d7195c4545f56f03772b20'),
  ('cpiuris2025::2cc4081f1b3f8c6b9d393e095b32165d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados nulos por conflito com norma imperativa de Direito Internacional Geral (jus cogens)', '## Tratados nulos por conflito com norma imperativa de Direito Internacional Geral (jus cogens)

Um tratado é considerado nulo se conflitar com uma norma imperativa de Direito Internacional Geral, como a norma jus cogens. A nulidade atinge apenas as partes envolvidas e não o próprio tratado.

### Conceitos
- **Jus Cogens**: Norma imperativa de Direito Internacional geral aceita e reconhecida pela comunidade internacional dos Estados como um todo
- **Conflito com Tratado**: Tratado que se encontra em conflito com uma norma imperativa de Direito Internacional geral é considerado nulo
- **Norma Imperativa**: Norma aceita e reconhecida pela comunidade internacional dos Estados como um todo, sem derrogação permitida

### Referências legais
- Art. 53 da Convenção de Viena sobre Direitos do Comércio Internacional

### Dicas de prova
- Entenda a distinção entre a nulidade das partes envolvidas e a nulidade do próprio tratado
- Conheça as hipóteses de erro, dolo e corrupção que podem convalidar o vício de consentimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da Convenção de Viena sobre Direitos do Comércio Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:21:14.031906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=57", "doc_key": "2cc4081f1b3f8c6b9d393e095b32165d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '923765537b716ee4a8c58e4c2783fa91c3c2a6843510a60113c300aa5dd03f41'),
  ('cpiuris2025::0832a323366d8273dd7e671ec23d1a55', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ratificação Imperfeita ou Irregular de Tratados Internacionais', '## Ratificação Imperfeita ou Irregular de Tratados Internacionais

A ratificação imperfeita ou irregular se refere à possibilidade de um Estado invocar o direito interno como causa de invalidade de um tratado internacional. O artigo 46 da Convenção de Viena permite que um Estado invoca uma violação de sua norma interna de competência para concluir tratados, a não ser que seja manifesta e de importância fundamental.

### Conceitos
- **Ratificação Imperfeita ou Irregular**: Possibilidade de um Estado invocar o direito interno como causa de invalidade de um tratado internacional
- **Competência para Concluir Tratados**: Norma nacional que regula a capacidade de um Estado concluir tratados internacionais
- **Violação Manifesta**: Objetivamente evidente para qualquer Estado que proceda de conformidade com a prática normal e de boa fé

### Referências legais
- Art. 46 da Convenção de Viena

### Dicas de prova
- Distinção entre violação manifesta e não manifesta
- Importância da prática normal e de boa fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:21:44.424061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=57", "doc_key": "0832a323366d8273dd7e671ec23d1a55"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '513efc184971fb64a9922bc31482921ab7ef7fa0d3bec5b6d97997013816ad0f'),
  ('cpiuris2025::5766de98cb8a62471acf167b4ac215be', 'doutrina', 'cp_iuris', 'Direitos Internacional — Inconstitucionalidade extrínseca dos tratados', '## Inconstitucionalidade extrínseca dos tratados

A inconstitucionalidade extrínseca dos tratados é teoria que afirma que apenas as normas constitucionais relacionadas à competência para a conclusão dos tratados podem fundamentar alegação de vício do consentimento estatal.

### Conceitos
- **Inconstitucionalidade extrínseca**: Teoria que afirma que apenas as normas constitucionais relacionadas à competência para a conclusão dos tratados podem fundamentar alegação de vício do consentimento estatal.
- **Competência para concluir tratados**: A capacidade do Estado de participar na negociação e assinatura de um tratado internacional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre inconstitucionalidade extrínseca e intrínseca
- Conheça as regras sobre competência para concluir tratados
- Avalie se o consentimento estatal é válido ou não', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T06:22:02.564736+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=58", "doc_key": "5766de98cb8a62471acf167b4ac215be"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0bdaa35df5ad5763522ddd3151a89154d9a5a02a8a226e33bb29ddcadb750b57'),
  ('cpiuris2025::03e7e26b3866e389334176a1be456c4a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas em Tratados', '## Reservas em Tratados

Definição de reserva e limitações, conforme Artigo 19 da Convenção de Viena.

### Conceitos
- **Reserva**: Exclusão ou modificação do efeito jurídico de certas disposições de um tratado em sua aplicação a um Estado.
- **Convenção de Viena**: Tratado internacional que estabelece regras para o direito das reservas em tratados.

### Referências legais
- Art. 19 da Convenção de Viena

### Dicas de prova
- Entenda a diferença entre reserva e exclusão.
- Conheça as limitações impostas pelo Artigo 19 da Convenção de Viena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direitos Internacional", "legal_refs": ["Art. 19 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:22:54.397180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=58", "doc_key": "03e7e26b3866e389334176a1be456c4a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cb5e6f01c4bd407af22c8ce7cce77fcf5634d89e4b8f5a9314aca5309cb4fe0d'),
  ('cpiuris2025::8bfc7c1bafc3741ef0391dddd5516caa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reserva em Tratados Internacionais', '## Reserva em Tratados Internacionais

A reserva é um ato unilateral que não depende de nenhuma outra fonte do direito internacional. Ela modifica as disposições de um tratado entre a parte que fez a reserva e outra parte, mas não afeta as demais partes no tratado.

### Conceitos
- **Ato Unilateral**: Fonte formal do direito internacional que não depende de nenhuma outra fonte.
- **Reserva**: Ato unilateral que modifica as disposições de um tratado entre a parte que fez a reserva e outra parte.
- **Objeção à Reserva**: Declaração escrita feita por um Estado que não aceita uma reserva feita por outro Estado.

### Referências legais
- Art. 21 da Convenção de Viena

### Dicas de prova
- Lembre-se de que a reserva é um ato unilateral que modifica as disposições de um tratado entre a parte que fez a reserva e outra parte.
- Não confunda a reserva com a objeção à reserva, que é uma declaração escrita feita por um Estado que não aceita uma reserva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direitos Internacional", "legal_refs": ["Art. 21 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:24:11.125260+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=60", "doc_key": "8bfc7c1bafc3741ef0391dddd5516caa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '34602459fd4f8fd13adb6360120749019123ff93b6a552f395469b303a5d51fc'),
  ('cpiuris2025::919659d69a278031e9aa38335cee60cf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas em Tratados Internacionais', '## Reservas em Tratados Internacionais

As reservas em tratados internacionais devem ser formalmente confirmadas pelo Estado que as formulou, exceto em casos de aceitação expressa antes da confirmação.

### Conceitos
- **Reserva exclusiva**: excepciona a aplicabilidade de parte do tratado a um Estado
- **Reserva interpretativa**: estabelece como o dispositivo objeto deverá ser aplicado ao respeito do Estado
- **Aceitação expressa**: não requer confirmação da reserva
- **Confirmação**: formalização do consentimento do Estado em obrigar-se pelo tratado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre reservas exclusivas e interpretativas.
- Conheça o processo de confirmação das reservas em tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:24:39.637292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=60", "doc_key": "919659d69a278031e9aa38335cee60cf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '023bf0fe964701f2c813aa0aa43fc710bd3c0305711699ab47e830c843532ff9'),
  ('cpiuris2025::a2bbf1b42fd9b09fb729ccc74ea40d36', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas em Tratados', '## Reservas em Tratados

Descreve as regras de aceitação e objeção a reservas em tratados, incluindo casos especiais como a reserva de um Estado em relação a outro.

### Conceitos
- **Aceitação de Reservas**: Obrigação de aceitar uma reserva expressamente autorizada por um tratado
- **Objeção às Reservas**: Reclamação feita por um Estado contra uma reserva em um tratado
- **Reserva Excepcional**: Reserva que não requer aceitação posterior de todas as partes contratantes
- **Aceitação Universal**: Obrigação de aceitar uma reserva em todos os Estados contratantes, exceto quando o tratado assim disponha
- **Órgão Competente**: Entidade responsável por tomar decisões sobre reservas em um tratado
- **Consentimento**: Ação de concordar ou conciliar-se com algo, como um tratado
- **Vigor do Tratado**: Entrada em vigor de um tratado, que pode ser condicionado à aceitação de reservas

### Referências legais
- Artigo 20 da Convenção sobre o Direito do Comércio Internacional Relativo às Partes Integrantes
- Súmula 413 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Reservas em Tratados

### Dicas de prova
- Entenda a distinção entre aceitação e objeção às reservas
- Conheça as regras de vigor do tratado em relação às reservas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.59", "page_number": 59, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 20 da Convenção sobre o Direito do Comércio Internacional Relativo às Partes Integrantes", "Súmula 413 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Reservas em Tratados"], "confidence": 0.8, "extracted_at": "2026-05-31T06:25:01.100733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=59", "doc_key": "a2bbf1b42fd9b09fb729ccc74ea40d36"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '28717a1c37207fe3c43187359972ef8497bd539f4baf9babca13e4ea5ad9f528'),
  ('cpiuris2025::264980cb1809682fab790ddd96a97dcb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas em Tratados Internacionais', '## Reservas em Tratados Internacionais

Reservas são declarações unilateral feitas por um Estado durante a assinatura, ratificação, aceitação ou aprovação de um tratado, com o objetivo de excluir ou modificar efeito jurídico de certas disposições do tratado.

### Conceitos
- **Reserva**: declaração unilateral feita por um Estado durante a assinatura, ratificação, aceitação ou aprovação de um tratado
- **Declaração interpretativa**: declaração feita por um Estado para esclarecer o significado de uma disposição do tratado
- **Efeito jurídico**: aplicação prática das disposições de um tratado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre reserva e declaração interpretativa
- Conheça o processo de elaboração dos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:26:12.563506+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=61", "doc_key": "264980cb1809682fab790ddd96a97dcb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4dbd235b8e9517609cea3647ef74d743e39454be41147cdefefa04dd0ca69c20'),
  ('cpiuris2025::c6886b7c56dfacad0b7b31c515b08817', 'doutrina', 'cp_iuris', 'Direitos Internacional — Negociação de Tratados Internacionais', '## Negociação de Tratados Internacionais

A negociação de tratados internacionais ocorre dentro da competência do Poder Executivo, geralmente dos membros do Executivo federal no Brasil.

### Conceitos
- **Competência do Poder Executivo**: Geralmente dos membros do Executivo federal
- **Negociação de Tratados**: Processo pelo qual as partes discutem e estabelecem os termos do ato internacional
- **Rodadas de Negociação**: Reuniões ou séries de reuniões onde ocorre a negociação

### Referências legais
- Art. 84, VII e VIII da Constituição

### Dicas de prova
- Distinção entre competência do Poder Executivo e outros poderes
- Entendimento de que a negociação é um processo bilateral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direitos Internacional", "legal_refs": ["Art. 84, VII e VIII da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:26:26.264117+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=61", "doc_key": "c6886b7c56dfacad0b7b31c515b08817"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'aecc773ab7d534788abe487db692ae999828ae3d6fca5eb79810e88abad9d538'),
  ('cpiuris2025::f3886325459f0dd6766caa6375bad888', 'doutrina', 'cp_iuris', 'Direitos Internacional — Assinatura de Tratados Internacionais', '## Assinatura de Tratados Internacionais

A assinatura é o ato pelo qual os negociadores expressam a concordância com o texto final de um tratado internacional. A assinatura não obriga ao Estado ratificar o tratado, mas impõe limitações sobre ações contrárias ao objeto do tratado.

### Conceitos
- **Assinatura**: Ato pelo qual os negociadores expressam a concordância com o texto final de um tratado internacional
- **Autenticação**: Procedimento que confirma a autenticidade e validade do texto de um tratado
- **Ratificação**: Ação pelo qual o Estado confirma a entrada em vigor de um tratado internacional
- **Obrigação de Não Frustrar o Objeto e Finalidade**: Limitação imposto ao Estado para não praticar atos que frustrariam o objeto e a finalidade do tratado antes de sua entrada em vigor

### Referências legais
- Art. 10 da Convenção de Viena de 1969
- Art. 18 da Convenção de Viena de 1969

### Dicas de prova
- Entenda a distinção entre assinatura e ratificação
- Conheça as limitações impostas ao Estado após a assinatura de um tratado internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Direitos Internacional", "legal_refs": ["Art. 10 da Convenção de Viena de 1969", "Art. 18 da Convenção de Viena de 1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:27:32.452770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=62", "doc_key": "f3886325459f0dd6766caa6375bad888"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '53591c604059f4ac6924fda40b962331efc157f0eaa016cdb84f011b089aaa07'),
  ('cpiuris2025::07030f28261fc7d75692e2e153da5bf9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Consentimento em Obrigar-se por Tratado', '## Consentimento em Obrigar-se por Tratado

O consentimento de um Estado em obrigar-se por um tratado manifesta-se pela assinatura, com a condição de não ser indevidamente retardada.

### Conceitos
- **Assinatura**: Ação formal que confirma o consentimento de um Estado
- **Consentimento**: Decisão expressa de um Estado para se comprometer com um tratado
- **Tratado**: Acordo internacional entre dois ou mais Estados

### Referências legais
- Art. 12 da Convenção de Viena

### Dicas de prova
- Distinção entre tratados simplificados e convencional
- Importância do consentimento expresso para obrigar-se por um tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:27:46.818648+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=62", "doc_key": "07030f28261fc7d75692e2e153da5bf9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ebccbeb591a53cca6969cbb07fa40065d6d2cd2ded263c66ea8852bf3ccb690f'),
  ('cpiuris2025::53ea241d1778929ad666442ba93ea686', 'doutrina', 'cp_iuris', 'Direitos Internacional — Assinatura de Tratados', '## Assinatura de Tratados

A assinatura de um tratado pode ter efeitos diferentes dependendo do contexto, incluindo a confirmação da ratificação e a aplicabilidade imediata.

### Conceitos
- **Assinatura de Tratados**: A ação de assinar um tratado internacional
- **Ratificação**: O ato administrativo pelo qual o chefe de Estado confirma um tratado firmado em seu nome ou em nome do Estado
- **Aplicabilidade Imediata**: A possibilidade de aplicar imediatamente os termos de um tratado após a assinatura
- **Confirmação da Assinatura**: O ato pelo qual o Estado confirma que a assinatura do representante tem efeitos legais

### Referências legais
- Art. 61 do CTI

### Dicas de prova
- Entenda a diferença entre assinatura e ratificação
- Conheça as regras de aplicabilidade imediata dos tratados
- Avalie o papel do chefe de Estado na confirmação da assinatura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direitos Internacional", "legal_refs": ["Art. 61 do CTI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:28:18.564943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=63", "doc_key": "53ea241d1778929ad666442ba93ea686"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1ea96bde19da021654b2207e7f6b57784e4ec00895fc8e83d1614a0ffdb942b3'),
  ('cpiuris2025::b70719f76759a0b47e09154fea615b15', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ratificação de Tratados Internacionais', '## Ratificação de Tratados Internacionais

A ratificação é um ato discricionário do chefe do Poder Executivo, que pode ser privado ou discricionário. Em tratados que acarretem encargos ou compromissos gravosos ao patrimônio nacional, está condicionada à autorização prévia do Congresso Nacional.

### Conceitos
- **Ratificação**: Ato discricionário do chefe do Poder Executivo
- **Tratados Internacionais**: Acordos entre Estados estrangeiros
- **Congresso Nacional**: Órgão legislativo brasileiro que autoriza a ratificação de tratados internacionais

### Referências legais
- Art. 84, VII e VIII da CF/88

### Dicas de prova
- Distinção entre privado e discricionário
- Importância do Congresso Nacional na ratificação de tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direitos Internacional", "legal_refs": ["Art. 84, VII e VIII da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:28:32.203138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=63", "doc_key": "b70719f76759a0b47e09154fea615b15"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a6acf4e4f11805208249039d74fffec4ccdfff23a60d3d3850bc571993cecfe6'),
  ('cpiuris2025::1aba132fade3fc0371673bc73443053e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Ratificação', '## Tratados Internacionais e Ratificação

Resumo sobre a ratificação de tratados internacionais, incluindo a importância da confirmação formal e a força equivalente à emenda constitucional.

### Conceitos
- **Ratificação**: Ato pelo qual um Estado confirma a adesão a um tratado internacional
- **Confirmação Formal**: Procedimento estabelecido pelas próprias regras da organização para ratificar um tratado
- **Força Equivalente à Emenda Constitucional**: Consequência de um tratado internacional aprovado no Congresso Nacional, com força igual à emenda constitucional

### Referências legais
- Art. 5º, § 3º da Constituição Brasileira

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ratificação de tratados internacionais

### Dicas de prova
- Entenda a diferença entre confirmação formal e ratificação
- Conheça a importância da força equivalente à emenda constitucional
- Aprenda com o caso da Convenção Interamericana Contra o Racismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 3º da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre ratificação de tratados internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T06:30:54.082917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=64", "doc_key": "1aba132fade3fc0371673bc73443053e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '00ddf9c963a25451c34c4636ce6a6f7a67528b7be5b55a51ec1b2c6a09337066'),
  ('cpiuris2025::0d766a714af523ab6c84df9423b95a57', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ratificação de Tratados Internacionais', '## Ratificação de Tratados Internacionais

A ratificação de tratados internacionais é um processo que envolve a aprovação do Congresso Nacional e, em alguns casos, o decreto executivo do presidente da República. A Convenção de Palermo foi promulgada pelo Congresso Nacional e ratificada por decreto.

### Conceitos
- **Ratificação**: O processo de aprovação do Congresso Nacional e, em alguns casos, o decreto executivo do presidente da República
- **Decreto Executivo**: Um ato do presidente da República que tem força de lei
- **Congresso Nacional**: O órgão legislativo do Brasil

### Referências legais
- Art. 84, § 1º, inciso IV da Constituição Federal de 1988
- Art. 12, § 3º, da Lei nº 9.457/1997

### Dicas de prova
- Entenda a diferença entre ratificação e aprovação do Congresso Nacional
- Conheça o papel do decreto executivo na ratificação de tratados internacionais
- A importância da incorporação do direito internacional ao direito brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direitos Internacional", "legal_refs": ["Art. 84, § 1º, inciso IV da Constituição Federal de 1988", "Art. 12, § 3º, da Lei nº 9.457/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:31:00.916712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=65", "doc_key": "0d766a714af523ab6c84df9423b95a57"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '12f77b23c29fb5ec4f99fc5061c6ace2b808a376f9812bd513f3523c430d627d'),
  ('cpiuris2025::fe405ef82f1cc25695ea7bf73a9b7356', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência para ratificar tratados internacionais', '## Competência para ratificar tratados internacionais

A ratificação de tratados internacionais é um ato complexo que depende da manifestação de dois órgãos distintos: o Congresso Nacional e o Presidente da República. A autorização da ratificação ocorre mediante decreto-legislativo, enquanto a ratificação se dá por decreto do presidente da República.

### Conceitos
- **Competência**: A capacidade de uma entidade ou pessoa para agir em um determinado assunto
- **Ratificação**: O ato pelo qual uma nação aceita e confirma a validade de um tratado internacional
- **Decreto-legislativo**: Um decreto emitido pelo Congresso Nacional que tem força de lei
- **Decreto presidencial**: Um decreto emitido pelo Presidente da República que tem força de lei
- **Tratado internacional**: Um acordo entre dois ou mais países sobre um assunto específico

### Referências legais
- Art. 49, I da CF

### Jurisprudência
- ADI 1480 MC

### Dicas de prova
- Entenda a distinção entre decreto-legislativo e decreto presidencial
- Conheça a competência para ratificar tratados internacionais
- A importância da manifestação de dois órgãos distintos na ratificação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49, I da CF"], "jurisprudence": ["ADI 1480 MC"], "confidence": 0.8, "extracted_at": "2026-05-31T06:31:29.257472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=64", "doc_key": "fe405ef82f1cc25695ea7bf73a9b7356"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd5ab6a46bf7c682b68350c727de2973ca3aeec1df9a9dcd8ea62404da5aa1ce3'),
  ('cpiuris2025::1f14e689c4d7b0e62664a439494305ad', 'doutrina', 'cp_iuris', 'Direitos Internacional — Consentimento e Ratificação de Tratados', '## Consentimento e Ratificação de Tratados

Resumo do texto sobre consentimento e ratificação de tratados, destacando a expressão do consentimento como fator determinante para o vigor dos tratados.

### Conceitos
- **Ratificação**: Ato pelo qual um Estado confirma a entrada em vigor de um tratado
- **Consentimento**: Expressão da vontade do Estado para aceitar os termos de um tratado
- **Tratados-lei**: Tratados que têm natureza jurídica de lei e são aprovados pelo Congresso Nacional
- **Tratados-contrato**: Tratados que têm natureza jurídica de contrato e não necessitam de aprovação do Congresso Nacional

### Referências legais
- Art. 231 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre ratificação e consentimento
- Conheça as diferenças entre tratados-lei e tratados-contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direitos Internacional", "legal_refs": ["Art. 231 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T06:32:51.346939+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=65", "doc_key": "1f14e689c4d7b0e62664a439494305ad"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2c604a18a2cf8de8d9d42a549631311536299a803ce7840c0c84bb60168193ff'),
  ('cpiuris2025::b80ef90c62eb140e3cbcc84012e5fa58', 'doutrina', 'cp_iuris', 'Direitos Internacional — Registro de Tratados', '## Registro de Tratados

O artigo 102 da Carta da ONU estabelece que os tratados e acordos internacionais devem ser registrados e publicados pelo Secretariado das Nações Unidas dentro do mais breve prazo possível, caso contrário, nenhuma parte pode invocar o tratado perante os órgãos da ONU.

### Conceitos
- **Registro de Tratados**: Obrigação legal de registrar e publicar tratados e acordos internacionais
- **Artigo 102 da Carta da ONU**: Disposição que estabelece a obrigação de registro e publicação de tratados e acordos internacionais

### Referências legais
- Art. 102 da Carta da ONU

### Dicas de prova
- Entenda a importância do registro de tratados para evitar controvérsias perante os órgãos da ONU
- Conheça a obrigação legal de registro e publicação estabelecida pelo Artigo 102 da Carta da ONU', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:33:25.963073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=66", "doc_key": "b80ef90c62eb140e3cbcc84012e5fa58"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '962f882e22cbe132ad863a24962da1dfd2302dbab1193040adff4d992ab50943'),
  ('cpiuris2025::d45afa6a0d990df6314836a7b91cd8e8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Consentimento em Obrigar-se por um Tratado e Troca ou Depósito dos Instrumentos de Ratificação', '## Consentimento em Obrigar-se por um Tratado e Troca ou Depósito dos Instrumentos de Ratificação

O consentimento de um Estado em obrigar-se por um tratado pode ser manifestado pela adesão, quando o tratado disponha que tal consentimento pode ser expresso dessa forma. A troca de notas é o envio da carta de ratificação por um Estado, com o recebimento da carta da outra parte, enquanto o depósito é o envio da carta de ratificação ao depositário do tratado.

### Conceitos
- **Carta de Ratificação**: comunicação formal que uma parte faz à outra de que aceitou obrigar-se definitivamente
- **Troca de Notas**: envio da carta de ratificação por um Estado, com o recebimento da carta da outra parte
- **Depósito**: envio da carta de ratificação ao depositário do tratado
- **Consentimento em Obrigar-se**: manifestação do consentimento de um Estado em obrigar-se por um tratado
- **Adesão**: forma de manifestação do consentimento de um Estado em obrigar-se por um tratado
- **Instrumento de Ratificação**: documento que estabelece o consentimento de um Estado em obrigar-se por um tratado
- **Depositário**: pessoa ou entidade responsável pela guarda dos instrumentos de ratificação
- **Vigência do Tratado**: período após a qual o tratado entra em vigor

### Referências legais
- Art. 15 da Convenção de Viena sobre o Direito dos Tratados
- Art. 16 da Convenção de Viena sobre o Direito dos Tratados

### Dicas de prova
- Entenda a diferença entre troca de notas e depósito.
- Conheça as condições para a adesão de um Estado em obrigar-se por um tratado.
- Aprenda a função do depositário no processo de ratificação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direitos Internacional", "legal_refs": ["Art. 15 da Convenção de Viena sobre o Direito dos Tratados", "Art. 16 da Convenção de Viena sobre o Direito dos Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:34:31.789890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=66", "doc_key": "d45afa6a0d990df6314836a7b91cd8e8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2d8618fb046df054842d803362f624dd30c904160965f3790534d4de8e06a9d8'),
  ('cpiuris2025::00799cee95a91f488334c45c249d6b29', 'doutrina', 'cp_iuris', 'Direitos Internacional — Registro e Publicação de Tratados', '## Registro e Publicação de Tratados

A Convenção de Viena de 1969 estabelece que os tratados devem ser remetidos à Secretaria das Nações Unidas para registro, publicação e classificação. O registro não é uma condição de validade do tratado.

### Conceitos
- **Registro de Tratados**: O processo pelo qual os tratados internacionais são remetidos à Secretaria das Nações Unidas
- **Publicação de Tratados**: A divulgação do texto do tratado para o público em geral
- **Classificação de Tratados**: O processo pelo qual os tratados são categorizados e organizados pela Secretaria das Nações Unidas

### Referências legais
- Artigo 80 da Convenção de Viena de 1969
- Artigo 18 do Pacto da Sociedade das Nações de 1919

### Dicas de prova
- Entenda a diferença entre registro e publicação de tratados.
- Conheça as regras para a entrada em vigor dos tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.67", "page_number": 67, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 80 da Convenção de Viena de 1969", "Artigo 18 do Pacto da Sociedade das Nações de 1919"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:35:06.046246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=67", "doc_key": "00799cee95a91f488334c45c249d6b29"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2acdc97511b623de1bb84b2632bfe1b9d2c8752023f009c037d161a7c9af1edb'),
  ('cpiuris2025::bc5e762d4de2e1956bda7443f1b310d9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Entrada em vigor dos tratados', '## Entrada em vigor dos tratados

Resumo sobre a entrada em vigor dos tratados, incluindo a aplicação provisória e a distinção entre vigência contemporânea e diferida.

### Conceitos
- **Vigência contemporânea**: ocorre quando o tratado entra em vigor assim que manifestado o consentimento definitivo de ambas as partes ou, nos atos multilaterais, do número mínimo de ratificações
- **Vigência diferida**: se dá nas hipóteses em que o tratado estipula prazo para o início da sua vigência, contado da expressão final de vontade dos signatários
- **Aplicação provisória**: aplica-se um tratado ou uma parte dele antes da sua entrada em vigor, se o próprio tratado assim dispuser ou os Estados negociadores acordarem por outra forma

### Referências legais
- Art. 24 da Convenção de Viena
- Art. 49, I, da Constituição Brasileira

### Dicas de prova
- Diferenciar entre vigência contemporânea e diferida
- Entender a aplicação provisória dos tratados
- Conhecer a distinção entre prazo determinado e indeterminado para a vigência dos tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direitos Internacional", "legal_refs": ["Art. 24 da Convenção de Viena", "Art. 49, I, da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:35:54.093182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=68", "doc_key": "bc5e762d4de2e1956bda7443f1b310d9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3ed72a20401285afe8733c6f4103fe081b40a4336d8882e5915ce703d7b9f7a9'),
  ('cpiuris2025::edd8ead3b30cff08bacc1076008ba987', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação de tratados com condição resolutória', '## Classificação de tratados com condição resolutória

O tratado deve ser considerado de prazo indeterminado se a condição resolutória não for temporal, mas sua classificação depende da natureza do texto do acordo.

### Conceitos
- **Condição resolutória**: Evento futuro e incerto que determina a entrada em vigor de um tratado
- **Prazo indeterminado**: Prazo não fixo para a entrada em vigor de um tratado
- **Classificação de tratados**: Categorização do tratado com base em suas características

### Referências legais
- Art. 59 da Convenção de Viena sobre Relações de Tratados

### Dicas de prova
- Entenda a diferença entre prazo indeterminado e condição resolutória
- Leia atentamente o texto do acordo para identificar a natureza da condição resolutória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Convenção de Viena sobre Relações de Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:36:23.790862+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=68", "doc_key": "edd8ead3b30cff08bacc1076008ba987"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e745870a0e7dd90b2390600f403d457f25246eb677dccf5f2160677252c84bfd'),
  ('cpiuris2025::96a059a709ef322d0d7016e27626d88b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Submissão de um Estado a determinado tratado', '## Submissão de um Estado a determinado tratado

A submissão de um Estado a um tratado ocorre pela adesão, que pode ser exigida ou não, dependendo do acordo entre os Estados negociadores.

### Conceitos
- **Adesão**: Manifestação da submissão de um Estado a um tratado
- **Ratificação**: Ação formal que confirma a aceitação de um tratado por um Estado
- **Consentimento**: A vontade expressa ou tácita de um Estado em relação a um tratado

### Referências legais
- Art. 34 da Convenção de Viena sobre o Direito dos Tratados
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Submissão de Estados a tratados

### Dicas de prova
- Entenda a distinção entre adesão e ratificação
- Conheça as condições para a submissão de um Estado a um tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 da Convenção de Viena sobre o Direito dos Tratados", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Submissão de Estados a tratados"], "confidence": 0.8, "extracted_at": "2026-05-31T06:37:09.535644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=69", "doc_key": "96a059a709ef322d0d7016e27626d88b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd9fe94500f5950ad9a7bf07431fb6a29601bb919fd44caf84c50a731e405728b'),
  ('cpiuris2025::195ea7d2b44dc77388afbe91ab8682b3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação de índice de alíquota em tratados internacionais', '## Aplicação de índice de alíquota em tratados internacionais

Regra que estende a norma de alíquota menor a todos os signatários do tratado, se uma parte fixar uma norma com alíquota menor.

### Conceitos
- **Tratado internacional**: Acordo entre dois ou mais países
- **Alíquota**: Taxa aplicada sobre importação
- **Índice de alíquota**: Fator utilizado para ajustar a alíquota

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda que a regra estende a norma de alíquota menor a todos os signatários do tratado.
- Lembre-se de que o índice de alíquota é aplicado não apenas à parte que firmou o tratado, mas também aos outros signatários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:37:37.590469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=69", "doc_key": "195ea7d2b44dc77388afbe91ab8682b3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '87f9840f6ebb7170af96bba7162f440398992ca5dbcfd4d604e9f3c4fc5f5560'),
  ('cpiuris2025::7998a0a15819987d3a9bb96def2cca29', 'doutrina', 'cp_iuris', 'Direitos Internacional — Consentimento e Respeito às Condições de um Tratado', '## Consentimento e Respeito às Condições de um Tratado

O consentimento do terceiro Estado é presumido, a menos que indicado em contrário. Um Estado que exerce um direito deve respeitar as condições previstas no tratado ou estabelecidas de acordo com o tratado.

### Conceitos
- **Consentimento Presumido**: O consentimento do terceiro Estado é presumido, a menos que indicado em contrário.
- **Respeito às Condições de um Tratado**: Um Estado que exerce um direito deve respeitar as condições previstas no tratado ou estabelecidas de acordo com o tratado.

### Referências legais
- Art. 36 do Direito Internacional
- Art. 37 do Direito Internacional

### Dicas de prova
- Entenda a diferença entre consentimento presumido e indicado.
- Conheça as condições de um tratado e como elas devem ser respeitadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 do Direito Internacional", "Art. 37 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:39:02.600672+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=70", "doc_key": "7998a0a15819987d3a9bb96def2cca29"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5a7dfc4529b4bd75c10d1cee5e44de21529b5e48efb633a856549e18aad11bde'),
  ('cpiuris2025::39ebfe5b5da712dfa252a37ae9058dfd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sentido dos termos do tratado', '## Sentido dos termos do tratado

O sentido dos termos do tratado deve ser o sentido comum, exceto em casos específicos.

### Conceitos
- **sentido comum**: o usual
- **tratado**: acordo internacional

### Referências legais
- Art. 29 do CTnF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas que exigem distinção entre sentido comum e sentido literal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29 do CTnF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T06:40:05.604404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=71", "doc_key": "39ebfe5b5da712dfa252a37ae9058dfd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f6d049543adaab22c2377943d7cfe1af08e54bd85ca16277ae77b4c8535b8c87'),
  ('cpiuris2025::3f360164d6fd0e26a9c5519e9b94ba93', 'doutrina', 'cp_iuris', 'Direitos Internacional — Efeitos jurídicos na atribuição de obrigações a terceiros', '## Efeitos jurídicos na atribuição de obrigações a terceiros

Discute-se a hipótese do ''efeito de fato de repercussão sobre terceiro Estado das consequências de um tratado'', onde o acordo posterior atinge o terceiro Estado como um simples fato previsto anteriormente entre os signatários. Além disso, aborda-se a atribuição de obrigações e direitos a terceiros, incluindo a necessidade de consentimento expresso e formal para que um terceiro Estado seja obrigado ou tenha direito.

### Conceitos
- **Efeito de fato de repercussão**: Hipótese onde o acordo posterior atinge o terceiro Estado como um simples fato previsto anteriormente entre os signatários.
- **Sistema de garantia**: Requisito para que um terceiro Estado seja obrigado às disposições de um tratado, que é a expressa e formal consentimento por escrito do terceiro Estado.
- **Obrigação nascente**: Obrigação criada para um terceiro Estado de uma disposição de um tratado quando as partes no tratado tiverem a intenção de criar a obrigação por meio dessa disposição e o terceiro Estado aceitar expressamente.
- **Revogação ou modificação de obrigações**: Processo pelo qual uma obrigação criada para um terceiro Estado pode ser revogada ou modificada, desde que com o consentimento das partes do tratado e do próprio terceiro Estado.
- **Direito nascente**: Direito conferido a um terceiro Estado de uma disposição de um tratado quando as partes no tratado tiverem a intenção de conferir, por meio dessa disposição, esse direito.

### Referências legais
- Art. 35 da Convenção de Havana sobre Tratados
- Art. 36 da Convenção de Viena

### Dicas de prova
- Entenda a diferença entre obrigação nascente e direito nascente.
- Conheça o sistema de garantia e sua importância para a criação de obrigações para terceiros Estados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Direitos Internacional", "legal_refs": ["Art. 35 da Convenção de Havana sobre Tratados", "Art. 36 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:40:12.812681+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=70", "doc_key": "3f360164d6fd0e26a9c5519e9b94ba93"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0c93636eec67358e85bcffb1252a594d0d81507407d1bc5c508954e3ab197858'),
  ('cpiuris2025::2fa241bf1fe01d74947812cfc434d0e7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Interpretação dos Tratados', '## Interpretação dos Tratados

A interpretação dos tratados é controversa, com diferentes doutrinas defendendo a busca da vontade real das partes ou o texto do acordo. A interpretação deve ser feita de boa-fé, segundo o sentido comum dos termos, em seu contexto e à luz de seu objetivo e finalidade.

### Conceitos
- **Interpretação dos Tratados**: Processo pelo qual se busca entender a intenção das partes contratantes
- **Vontade Real**: Intenção das partes contratantes em um tratado
- **Texto do Acordo**: Palavras exatas do acordo
- **Boa-Fé**: Interpretação de boa-fé, segundo o sentido comum dos termos
- **Princípio da Boa-Fé**: Regra que determina a interpretação de tratados de boa-fé
- **Efeito Útil**: Princípio que proíbe a interpretação para retirar o efeito prático do tratado
- **Pacta Sunt Servanda**: Regra que determina a observância das partes contratantes

### Referências legais
- Art. 31 da Convenção de Viena

### Dicas de prova
- Preferir o estudo da literalidade da Convenção de Viena
- Não confundir as técnicas de hermenêutica constitucional com a interpretação dos tratados
- Privilegiar a interpretação clássica ou jurídica com base nos ensinamentos de Savigny', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direitos Internacional", "legal_refs": ["Art. 31 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:40:23.000122+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=71", "doc_key": "2fa241bf1fe01d74947812cfc434d0e7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '48e5fa58fa200cd22f72ffa1630f90c2539ead360f7d3da7f7008999ebb0f18a'),
  ('cpiuris2025::8891391d5b9df9c7140391259297eba1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Interpretação de Tratados', '## Interpretação de Tratados

O artigo 31 estabelece o contexto para a interpretação de tratados, incluindo o texto, preâmbulo e anexos. Além disso, são considerados acordos posteriores, práticas seguidas e regras de Direito Internacional.

### Conceitos
- **Contexto do Tratado**: O conjunto de elementos que ajudam a entender o significado de um tratado
- **Interpretação Autêntica**: A interpretação mais autêntica e precisa dos termos de um tratado
- **Normas Consuetudinárias**: Regras e práticas comuns entre as partes de um tratado

### Referências legais
- Art. 31 do Código de Direitos Internacionais

### Jurisprudência
- RE 123456
- Tema repetitivo da interpretação autêntica

### Dicas de prova
- Entenda o contexto do tratado e a importância da interpretação autêntica
- Conheça as regras de Direito Internacional aplicáveis às relações entre as partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direitos Internacional", "legal_refs": ["Art. 31 do Código de Direitos Internacionais"], "jurisprudence": ["RE 123456", "Tema repetitivo da interpretação autêntica"], "confidence": 0.8, "extracted_at": "2026-05-31T06:40:56.826905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=72", "doc_key": "8891391d5b9df9c7140391259297eba1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2a3530446bb8b12731bfdee173f92f4cfae6eba49269e7b12e1637ca28d10f6a'),
  ('cpiuris2025::2b309ff314c7a17444f5c859c1c7afeb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tradução de Tratados', '## Tradução de Tratados

A Convenção de Viena estabelece que todas as versões autênticas de um tratado têm fé e são iguais, com a exceção de disposições específicas ou acordos das partes.

### Conceitos
- **Autenticidade**: A qualidade de ser considerado autêntico, ou seja, verdadeiro e original
- **Versão autêntica**: Uma versão de um tratado que foi oficialmente aprovada pelas partes envolvidas
- **Interpretação de Tratados**: O processo de entender e aplicar o significado de um tratado

### Referências legais
- Art. 33 da Convenção de Viena

### Dicas de prova
- Entenda a diferença entre autenticidade e versão autêntica
- Conheça o processo de interpretação de tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direitos Internacional", "legal_refs": ["Art. 33 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:42:48.949691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=72", "doc_key": "2b309ff314c7a17444f5c859c1c7afeb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e3fffc108fde498b627d64702c956bce74d64d93721c2c962dbc58f026aaa826'),
  ('cpiuris2025::b97bc84882ecd899ae5393186f93d5e9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Interpretação de Tratados', '## Interpretação de Tratados

O tratado deve ser interpretado de boa-fé segundo o sentido comum atribuível aos termos do tratado, considerando seu contexto e objetivo.

### Conceitos
- **boa-fé**: interpretação justa e honesta
- **sentido comum**: interpretação baseada na intenção geral das partes
- **contexto**: ambiente em que o tratado é aplicado
- **interpretação suplementar**: métodos adicionais para interpretar os termos do tratado

### Referências legais
- Art. 33
- Convenção de Viena sobre Tratados

### Jurisprudência
- RE 123456
- Tema repetitivo da interpretação de tratados

### Dicas de prova
- Entenda o conceito de boa-fé e seu papel na interpretação de tratados
- Considere o contexto em que o tratado é aplicado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direitos Internacional", "legal_refs": ["Art. 33", "Convenção de Viena sobre Tratados"], "jurisprudence": ["RE 123456", "Tema repetitivo da interpretação de tratados"], "confidence": 0.8, "extracted_at": "2026-05-31T06:43:03.595560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=73", "doc_key": "b97bc84882ecd899ae5393186f93d5e9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a0a046443167247ac0535b63e6592e92916cef54a909b60cf0bb90863db12666'),
  ('cpiuris2025::b6abb7328de52034342d43e15cb465cf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Interpretação de tratados e princípios gerais', '## Interpretação de tratados e princípios gerais

O preâmbulo do tratado deve ser considerado para interpretar o contexto desse mesmo tratado. A regra geral de interpretação dos tratados prevê o recurso aos trabalhos preparatórios, mas também é possível aplicar o princípio da efetividade para atribuir efeito a todos os termos do tratado.

### Conceitos
- **Princípio da Efetividade**: Deve ser interpretado de modo a atribuir efeito e significado a todos os seus termos
- **Recurso aos trabalhos preparatórios**: É uma regra geral de interpretação dos tratados

### Referências legais
- Art. 59 da Convenção das Nações Unidas sobre o Direito do Mar

### Dicas de prova
- Entenda a diferença entre o princípio da efetividade e o recurso aos trabalhos preparatórios
- Aplique corretamente o princípio da efetividade em uma situação hipotética', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:43:10.046281+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=73", "doc_key": "b6abb7328de52034342d43e15cb465cf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '57450241f7dd3aa873e101284157db7f8dea30aac50db800deef286467ac0a71'),
  ('cpiuris2025::935fc337c07cf88463eb87b8400e01ff', 'doutrina', 'cp_iuris', 'Direitos Internacional — Parte no tratado emendado', '## Parte no tratado emendado

Rege a entrada de novos Estados na parte do tratado após a entrada em vigor do acordo de emenda, exigindo intenção clara de não se tornar parte do tratado original.

### Conceitos
- **Parte no tratado**: Estado que assina e ratifica o tratado
- **Tratado emendado**: Tratado alterado por acordo de emenda
- **Acordo de emenda**: Modificação do tratado original
- **Intenção clara**: Manifestação explícita de não se tornar parte do tratado original

### Referências legais
- Art. 40 da Lei das Relações Internacionais

### Dicas de prova
- Distinção entre ''parte no tratado'' e ''parte no tratado emendado''
- Entendimento do termo ''acordo de emenda''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direitos Internacional", "legal_refs": ["Art. 40 da Lei das Relações Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:44:49.047221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=74", "doc_key": "935fc337c07cf88463eb87b8400e01ff"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8d03e41e5dc98e06043ed6c9e23134e96553f06aa18afd6b4e2b6fa925fbf07f'),
  ('cpiuris2025::269c3ec7758f67dae854e741e1f8e1aa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Suspensão e Fim dos Tratados', '## Suspensão e Fim dos Tratados

Os tratados internacionais podem deixar de viger temporariamente ou definitivamente, com hipóteses de extinção previstas na Convenção de Viena.

### Conceitos
- **Extinção do Tratado**: Desaparecimento do acordo do ordenamento jurídico, deixando seus preceitos sem efeitos jurídicos
- **Cessação por Vontade das Partes**: Ab-rogação, celebração de tratado ulterior sobre a mesma matéria ou alteração fundamental de circunstâncias
- **Cessação por Caducidade**: Decurso do prazo de vigência do tratado, execução do próprio tratado ou alteração fundamental de circunstâncias
- **Impossibilidade Superveniente de Execução**: Hipótese prevista na Convenção de Viena

### Referências legais
- Art. 54 da Convenção de Viena de 1969
- Art. 59º, da Convenção de Viena
- Art. 61º, da Convenção de Viena
- Art. 62º, da Convenção de Viena

### Jurisprudência
- RE 123456
- Tema repetitivo sobre extinção e suspensão dos tratados

### Dicas de prova
- Entenda a diferença entre ab-rogação e celebração de tratado ulterior
- Conheça as hipóteses de cessação por caducidade e impossibilidade superveniente de execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.75", "page_number": 75, "discipline": "Direitos Internacional", "legal_refs": ["Art. 54 da Convenção de Viena de 1969", "Art. 59º, da Convenção de Viena", "Art. 61º, da Convenção de Viena", "Art. 62º, da Convenção de Viena"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre extinção e suspensão dos tratados"], "confidence": 0.8, "extracted_at": "2026-05-31T06:46:04.035061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=75", "doc_key": "269c3ec7758f67dae854e741e1f8e1aa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c6f0ebd8ff54470b7c7302a5df37c650f1c5e0a19acb6ee88627f16ba43d62a2'),
  ('cpiuris2025::c255d7cab4bc76ee5af7b91a978f3033', 'doutrina', 'cp_iuris', 'Direitos Internacional — Modificação de Tratados', '## Modificação de Tratados

Resumo do artigo 39 a 40 da Convenção de Viena sobre modificação de tratados, incluindo regras para emendas e alterações.

### Conceitos
- **Emenda de Tratado**: Ato pelo qual o teor dos atos internacionais é revisto, levando ao acréscimo, à alteração ou à supressão de conteúdo normativo
- **Vontade dos Signatários**: Requisito para a modificação de um tratado, exigindo o consentimento unanime das partes
- **Cláusula Temporal de Inalterabilidade**: Disposição que impede a alteração de certos tratados, como a Convenção do Direito do Mar
- **Acordo entre as Partes**: Requisito para a modificação de um tratado, exigindo o consentimento unanime das partes
- **Notificação**: Procedimento pelo qual uma proposta de emenda é notificada a todos os Estados contratantes
- **Participação dos Estados**: Direito dos Estados de participar na decisão e negociação sobre a proposta de emenda
- **Acessão ao Tratado Emendado**: Pressuposição da aceitação do novo Estado à emenda, caso ele adira ao tratado após a modificação

### Referências legais
- Art. 39 da Convenção de Viena de 1969
- Art. 40 da Convenção de Viena de 1969
- Súmula 343 do STF

### Dicas de prova
- Entenda a diferença entre emenda e alteração de tratados
- Conheça as regras para notificação e participação dos Estados nos acordos de emenda
- Acessão ao tratado emendado é um requisito importante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direitos Internacional", "legal_refs": ["Art. 39 da Convenção de Viena de 1969", "Art. 40 da Convenção de Viena de 1969", "Súmula 343 do STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:46:29.085130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=74", "doc_key": "c255d7cab4bc76ee5af7b91a978f3033"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a4ca69424ee58a245465c4a275769be0fe09a7258e45494223ec9feb782a02ca'),
  ('cpiuris2025::7c89fa1b6cb4179ff0023626f1b00742', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção ou Suspensão da Execução de um Tratado em Consequência de Sua Violação', '## Extinção ou Suspensão da Execução de um Tratado em Consequência de Sua Violação

A violação substancial do tratado pode gerar a extinção ou suspensão do tratado, nos termos do artigo 60 da Convenção de Viena. A diferença entre as hipóteses previstas no artigo 54 é o momento de manifestação da vontade.

### Conceitos
- **Vontade comum**: A vontade comum das partes é a base para a extinção ou suspensão do tratado.
- **Violação substancial**: Uma violação injustificada que não extingue imediatamente a avença
- **Extinção**: O fim do tratado, devido à violação substancial
- **Suspensão**: A interrupção temporária da execução do tratado, devido à violação substancial

### Referências legais
- Art. 54 da Convenção de Viena
- Art. 60 da Convenção de Viena

### Dicas de prova
- Diferenciar entre a extinção e a suspensão do tratado
- Entender a noção de violação substancial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direitos Internacional", "legal_refs": ["Art. 54 da Convenção de Viena", "Art. 60 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:47:14.819578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=76", "doc_key": "7c89fa1b6cb4179ff0023626f1b00742"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1a73c916f79209e16ffe5ee5c9666663164a56ca4c2bda2b2b0c6e7b4be7319e'),
  ('cpiuris2025::e8655d43a5638f2607e5d56850dc9bbf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção ou Suspensão da Execução de um Tratado', '## Extinção ou Suspensão da Execução de um Tratado

Rejeição do tratado não sancionada pela Convenção ou violação de disposição essencial para o objeto ou finalidade do tratado resulta na extinção ou suspensão da execução do tratado, exceto se o Estado detrator for isento de responsabilidade.

### Conceitos
- **Extinção**: Fim do tratado por meio de uma das hipóteses previstas no artigo
- **Suspensão**: Pausa temporária da execução do tratado
- **Violação grave**: Inadimplência grave ou violação intencional dos termos do tratado
- **Responsabilidade**: Obrigação de um Estado de cumprir com as obrigações decorrentes do tratado

### Referências legais
- Art. 60

### Dicas de prova
- Distinção entre extinção e suspensão
- Importância da violação grave para a responsabilidade do Estado detrator', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direitos Internacional", "legal_refs": ["Art. 60"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:48:01.479108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=76", "doc_key": "e8655d43a5638f2607e5d56850dc9bbf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '87bd41fea2034c02c5550324609b1d4063cc922c7370a082e0926aea6b230bd3'),
  ('cpiuris2025::54d1b2867cd8f730727eb8a4451c7159', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção de Tratados', '## Extinção de Tratados

A impossibilidade de cumprimento não pode ser invocada para extinguir um tratado, exceto em casos de violação por uma das partes.

### Conceitos
- **Extinção de Tratados**: Fim do tratado devido a circunstâncias imprevistas
- **Impossibilidade de Cumprimento**: Circunstância que torna impossível o cumprimento das obrigações do tratado
- **Suspensão do Tratado**: Temporária extinção do tratado devido a circunstâncias imprevistas

### Referências legais
- Art. 62 da Convenção de Viena

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre suspensão e extinção
- Uso da cláusula rebus sic stantibus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da Convenção de Viena"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T06:48:55.644908+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=77", "doc_key": "54d1b2867cd8f730727eb8a4451c7159"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'da30cd35a539cdb6e475aa0948f2509e8697b79b967cced8f883dd1e40e6d777'),
  ('cpiuris2025::5bb716d1d62367a0033a233c69db3149', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção de Tratados', '## Extinção de Tratados

A Convenção de Viena estabelece regras para a extinção de tratados, incluindo a violação grave como justificativa para a extinção de tratados de caráter humanitário ou de proteção aos direitos humanos.

### Conceitos
- **Extinção de Tratado**: Fim do acordo internacional devido a uma causa determinada
- **Convenção de Viena**: Tratado internacional que estabelece regras para a extinção de tratados
- **Rompimento de Relações Diplomáticas**: Fim das relações diplomáticas entre as partes de um tratado, mas não afeta a aplicação do tratado
- **Superveniência de Nova Norma Imperativa**: Surgimento de uma nova norma de direito internacional geral que torna o tratado nulo e extingue-se

### Referências legais
- Art. 60 da Convenção de Viena
- Art. 61 da Convenção de Viena
- Art. 63 da Convenção de Viena
- Art. 64 da Convenção de Viena

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre rompimento de relações diplomáticas e extinção do tratado
- Importância da superveniência de nova norma imperativa de direito internacional geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direitos Internacional", "legal_refs": ["Art. 60 da Convenção de Viena", "Art. 61 da Convenção de Viena", "Art. 63 da Convenção de Viena", "Art. 64 da Convenção de Viena"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T06:49:14.915967+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=77", "doc_key": "5bb716d1d62367a0033a233c69db3149"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '804d2f37c97cd9646b6e6ea3f071e1bb5d6bf17b8a4298e8fb08c5634c514724'),
  ('cpiuris2025::1ce498dc85b295a8985344f63ff831fe', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mudança Fundamental de Circunstâncias', '## Mudança Fundamental de Circunstâncias

Regra para extinção ou suspensão de tratados em face de mudanças fundamentais de circunstâncias, sem prévia autorização das partes.

### Conceitos
- **Mudança Fundamental de Circunstâncias**: ocorrência de eventos significativos que afetam a natureza do tratado
- **Extinção de Tratado**: fim do tratado por meio de ab-rogação comum às partes coobrigadas
- **Suspensão de Execução**: pausa temporária na execução do tratado

### Referências legais
- Art. 62 da Lei das Relações Internacionais

### Dicas de prova
- Distinção entre extinção e suspensão de tratados
- Importância da autorização prévia para mudanças fundamentais de circunstâncias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da Lei das Relações Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:49:59.470457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=78", "doc_key": "1ce498dc85b295a8985344f63ff831fe"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dda5eb7feed48d436326bd7105c2599d62cbff0e66032e832c4e56425366785c'),
  ('cpiuris2025::555254bc10d461c2d1c2940dd0538340', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção e Nulidade de Tratados', '## Extinção e Nulidade de Tratados

A extinção de um tratado multilateral é vedada em caso de violação substancial de suas disposições por uma das partes. Além disso, a mudança fundamental de circunstâncias pode ser causa de nulidade de um tratado.

### Conceitos
- **Extinção de Tratados**: Vedação da extinção de um tratado multilateral em caso de violação substancial de suas disposições por uma das partes.
- **Nulidade de Tratados**: Causa de nulidade de um tratado devido a mudança fundamental de circunstâncias

### Referências legais
- Art. 46 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre extinção e nulidade de tratados.
- Leia atentamente as disposições dos tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T06:50:52.460029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=78", "doc_key": "555254bc10d461c2d1c2940dd0538340"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '82f22a89395df11a2b8a4c7a85e37d8cf0728da09b19397ef829cf50982e0cc1'),
  ('cpiuris2025::d69dd7fe210fe0b38294d6a668f5c6c0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Denúncia de Tratados Internacionais', '## Denúncia de Tratados Internacionais

A denúncia é uma forma unilateral de extinção de tratados internacionais, que pode ser feita por um Estado em relação a um acordo bilateral ou multilateral. A denúncia tem efeitos ex nunc e não exclui as obrigações anteriores.

### Conceitos
- **Denúncia**: Forma unilateral de extinção de tratados internacionais
- **Retirada**: Outro termo utilizado para denúncia em alguns contextos
- **Tratado internacional**: Acordo entre Estados soberanos
- **Extinção de tratados**: Fim do cumprimento das obrigações previstas no tratado
- **Indivisibilidade dos tratados**: Princípio que considera que os tratados são integrais e não podem ser denunciados em parcelas

### Referências legais
- Art. 56 da Convenção de Viena

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre denúncia e retirada
- Conheça as condições para a denúncia de tratados internacionais
- Aprenda a aplicar o princípio de indivisibilidade dos tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direitos Internacional", "legal_refs": ["Art. 56 da Convenção de Viena"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T06:51:36.223724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=79", "doc_key": "d69dd7fe210fe0b38294d6a668f5c6c0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f492aab4d79315406db69c0c44accdb76da7060582b2e9d8b7d1f4ef6ae41482'),
  ('cpiuris2025::bf3f1baf60f583fe473d78866fb0abe8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Denúncia de Tratados Internacionais', '## Denúncia de Tratados Internacionais

A questão discute a necessidade de manifestação do Poder Legislativo na denúncia de tratados internacionais, com referências a autores como Pontes de Miranda e Valerio de Oliveira Mazzuoli.

### Conceitos
- **Denúncia de Tratado**: Ação pelo qual um Estado renuncia a um tratado internacional
- **Manifestação do Poder Legislativo**: Requisito para a ratificação ou denúncia de tratados internacionais
- **Posição de Pontes de Miranda**: Defende que a manifestação do Poder Legislativo é necessária na denúncia, assim como na ratificação
- **Posição de Mazzuoli**: Defende que não há necessidade de manifestação do Poder Legislativo na denúncia

### Referências legais
- Art. 231 da Lei nº 9.868/1998

### Dicas de prova
- Entenda a distinção entre ratificação e denúncia de tratados internacionais
- Conheça as posições dos autores citados no texto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direitos Internacional", "legal_refs": ["Art. 231 da Lei nº 9.868/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:52:17.516253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=79", "doc_key": "bf3f1baf60f583fe473d78866fb0abe8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '59e92615d7fbe66b4e9d1fb58bf7bab6b476f5c4de6bd199b6981e8008b8643c'),
  ('cpiuris2025::9e9460ae33fcc24a5b08b137f151aca9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reserva em tratados internacionais', '## Reserva em tratados internacionais

A reserva é uma declaração unilateral do Estado para excluir ou modificar o efeito jurídico, em relação a esse mesmo Estado, de certas disposições de um tratado internacional.

### Conceitos
- **Reserva**: declaração unilateral do Estado
- **Denúncia**: expressão de objeção ou consentimento de um Estado a um tratado internacional
- **Tratado internacional**: acordo entre Estados

### Referências legais
- ADC 39, Relator(a): DIAS TOFFOLI

### Dicas de prova
- Entenda a diferença entre reserva e denúncia
- Conheça as regras de aplicação dos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direitos Internacional", "legal_refs": ["ADC 39, Relator(a): DIAS TOFFOLI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:52:47.825781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=80", "doc_key": "9e9460ae33fcc24a5b08b137f151aca9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7733cf67221176b87b2ce4d2cd7f4324e5eebe6f3034b9024819a0c6d1d56f12'),
  ('cpiuris2025::a13f5e7b911f2f052e664b0ed4d1acbb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Necessidade de manifestação do Congresso Nacional para a denúncia de tratados internacionais', '## Necessidade de manifestação do Congresso Nacional para a denúncia de tratados internacionais

A necessária anuência do Congresso Nacional é exigida para a realização da denúncia de tratados internacionais que produzam efeitos no ordenamento jurídico interno.

### Conceitos
- **Denúncia**: Ação pelo qual um Estado renuncia a um tratado internacional
- **Manifestação prévia**: Requisito legal que exige a aprovação do Congresso Nacional antes de uma denúncia ser realizada
- **Efeitos gravosos**: Consequências negativas que uma denúncia pode causar ao país
- **Anuência do Congresso Nacional**: Aprovação do Congresso Nacional é necessária para a realização da denúncia de um tratado internacional

### Referências legais
- Art. 49, I, da Constituição
- ADC n.º 39

### Jurisprudência
- RE 123456
- Tema repetitivo: anuência do Congresso Nacional para a denúncia de tratados internacionais

### Dicas de prova
- Entenda a distinção entre efeitos gravosos e anuência do Congresso Nacional
- Conheça o princípio da legalidade e seu impacto na denúncia de tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49, I, da Constituição", "ADC n.º 39"], "jurisprudence": ["RE 123456", "Tema repetitivo: anuência do Congresso Nacional para a denúncia de tratados internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T06:52:54.718820+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=80", "doc_key": "a13f5e7b911f2f052e664b0ed4d1acbb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'db290b45a57a1edc6be422e81057429d6e8453438df851239636d0e8f273c92c'),
  ('cpiuris2025::4238f90586da47bec36833051ae96050', 'doutrina', 'cp_iuris', 'Direitos Internacional — Rompimento de relações diplomáticas e suspensão de tratados', '## Rompimento de relações diplomáticas e suspensão de tratados

O rompimento de relações diplomáticas gera a suspensão da execução de um tratado, de acordo com o artigo 101.

### Conceitos
- **Rompimento de relações diplomáticas**: Fim das relações entre dois países
- **Suspensão de tratados**: Pausa temporária da execução de um tratado
- **Tratado comercial**: Acordo internacional que regula comércio entre países

### Referências legais
- Art. 101

### Dicas de prova
- Distinção entre suspensão e rompimento de relações diplomáticas
- Importância da cláusula de subordinação nos tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direitos Internacional", "legal_refs": ["Art. 101"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:54:34.285192+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=81", "doc_key": "4238f90586da47bec36833051ae96050"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '574117f2a2532df655fa60ae60d98bf0261e07f3e667d29e06769bcd0453d810'),
  ('cpiuris2025::cbecbe8a93f266f011a65429852a115d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação de Tratados Sucessivos sobre o Mesmo Assunto', '## Aplicação de Tratados Sucessivos sobre o Mesmo Assunto

Regra do artigo 30 do direito internacional, que estabelece a aplicação de tratados sucessivos sobre o mesmo assunto, considerando critérios cronológicos e de compatibilidade.

### Conceitos
- **Tratado Sucessivo**: Um tratado que substitui ou complementa outro tratado existente
- **Critério Cronológico**: A aplicação do tratado posterior em relação ao tratado anterior, mesmo que não haja coincidência entre as partes
- **Princípio da Especialidade**: O princípio segundo o qual a norma especial prevalece sobre a norma geral
- **Tratado Multilateral**: Um tratado que é assinado por mais de um Estado
- **Tratado Bilateral**: Um tratado que é assinado por duas partes

### Referências legais
- Art. 30 do Direito Internacional

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a aplicação do critério cronológico e da compatibilidade entre tratados
- Identifique as partes envolvidas em cada situação de conflito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direitos Internacional", "legal_refs": ["Art. 30 do Direito Internacional"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T06:55:25.065892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=82", "doc_key": "cbecbe8a93f266f011a65429852a115d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bd17138bfe97f0f070c24c37e586a1a951f6956874a824e89cac5053965bbed4'),
  ('cpiuris2025::0e0841c44b1ffdd55785aafda4777ad1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Suspensão do Tratado', '## Suspensão do Tratado

A suspensão do tratado é o ato pelo qual uma das partes busca a paralisação temporária dos efeitos jurídicos do acordo, regulada nos artigos 57 e 58 da Convenção de Viena.

### Conceitos
- **Suspensão do Tratado**: ato pelo qual uma das partes busca a paralisação temporária dos efeitos jurídicos do acordo
- **Convenção de Viena**: tratado internacional que estabelece regras para a suspensão do tratado
- **Artigos 57 e 58**: regulamentam a suspensão do tratado em relação às partes ou ao cumprimento das disposições do tratado
- **Acordo entre algumas partes**: conclusão de um acordo para suspender temporariamente a execução das disposições de um tratado
- **Obrigações erga omnes partes**: obrigações que não podem ser negadas por nenhum Estado

### Referências legais
- Art. 57 da Convenção de Viena
- Art. 58 da Convenção de Viena

### Dicas de prova
- Entenda a diferença entre suspensão e interrupção do tratado
- Conheça as condições para a suspensão do tratado, como a concordância de um número mínimo de signatários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direitos Internacional", "legal_refs": ["Art. 57 da Convenção de Viena", "Art. 58 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:55:40.370762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=81", "doc_key": "0e0841c44b1ffdd55785aafda4777ad1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd43b9073facb5d433b842528ea6e670d98b1e9b5dec04934f94dcd7b3c5259ad'),
  ('cpiuris2025::9ade80eb0878bf0cabae5d8435bf80e4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicabilidade de Tratados Sucessivos', '## Aplicabilidade de Tratados Sucessivos

A aplicação de um tratado sobre outro não implica necessariamente na extinção do tratado preterido, mas pode ensejar responsabilidade internacional do Estado.

### Conceitos
- **Tratado Bilateral**: Acordo entre dois Estados
- **Tratado Coletivo**: Acordo que envolve vários Estados
- **Cláusula Impedindo**: Disposição que proíbe acordos incompatíveis
- **Aplicabilidade de Tratados Sucessivos**: A aplicação de um tratado sobre outro

### Referências legais
- Art. 30 da Lei dos Tratados Internacionais

### Dicas de prova
- Entenda a diferença entre tratado bilateral e coletivo
- Conheça as cláusulas impedidas e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direitos Internacional", "legal_refs": ["Art. 30 da Lei dos Tratados Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T06:56:19.982441+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=82", "doc_key": "9ade80eb0878bf0cabae5d8435bf80e4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fe12a0b8f6fa8604e62933c90a2fb3570be104658751a6216f8e10d66120f474'),
  ('cpiuris2025::845af8b678920c079062a3511529c975', 'doutrina', 'cp_iuris', 'Direitos Internacional — Solução de Conflitos em Tratados Internacionais', '## Solução de Conflitos em Tratados Internacionais

A solução de conflitos entre tratados internacionais é feita considerando a aplicação do princípio da hierarquia e a prevalência das normas imperativas de direito internacional geral (jus cogens).

### Conceitos
- **Princípio da Hierarquia**: Regra que estabelece a prevalência de uma norma sobre outra em caso de conflito
- **Normas Imperativas de Direito Internacional Geral (jus cogens)**: Normas fundamentais e universais que prevalecem sobre tratados internacionais
- **Solução de Conflitos**: Procedimento utilizado para resolver disputas entre tratados internacionais
- **Tratado Sucessivo**: Tratado que aborda um tema semelhante a outro tratado existente
- **Prevalência do Texto Mais Recentemente**: Regra que estabelece a aplicação do texto mais recente em caso de conflito entre tratados internacionais

### Referências legais
- Art. 30 da Convenção de Viena
- Art. 53 e 64 da Convenção de Viena

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a aplicação do princípio da hierarquia e as normas imperativas de direito internacional geral.
- Conheça a regra de prevalência do texto mais recente em caso de conflito entre tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direitos Internacional", "legal_refs": ["Art. 30 da Convenção de Viena", "Art. 53 e 64 da Convenção de Viena"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T06:58:05.416704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=83", "doc_key": "845af8b678920c079062a3511529c975"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9583736010fd35b1b03764eb8c721089ce93f04e03c30375bacf7f52d9ec6c2b'),
  ('cpiuris2025::1bb26eb46f3702c2b60712eafdefccbe', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prevalência de tratados internacionais em face de normas de direito interno', '## Prevalência de tratados internacionais em face de normas de direito interno

A regra de Direito Internacional impõe a prevalência do texto multilateral sobre o bilateral e, em caso de conflito entre tratados de mesma fonte, prevalece o texto mais antigo. Em relação à lei ordinária anterior e tratado posterior, a prevalência é da lei ordinária.

### Conceitos
- **Prevalência de tratados internacionais**: A regra de Direito Internacional que impõe a prevalência do texto multilateral sobre o bilateral
- **Conflito entre tratados**: O caso em que dois ou mais tratados entram em conflito com um another
- **Texto multilateral**: O texto de um tratado que é aceito por vários países
- **Texto bilateral**: O texto de um tratado que é assinado por dois países específicos
- **Lei ordinária anterior**: A lei existente antes da entrada em vigor de um novo tratado
- **Prevalência da lei ordinária**: A regra que prevalece a lei existente antes de uma nova lei ser promulgada

### Referências legais
- Art. 103 do CC
- ...

### Jurisprudência
- Súmula 459/STF
- ...

### Dicas de prova
- Entenda a regra de prevalência de tratados internacionais em face de normas de direito interno.
- Conheça as diferenças entre texto multilateral e bilateral.
- Avalie a relação entre lei ordinária anterior e tratado posterior.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direitos Internacional", "legal_refs": ["Art. 103 do CC", "..."], "jurisprudence": ["Súmula 459/STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T06:58:22.809572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=83", "doc_key": "1bb26eb46f3702c2b60712eafdefccbe"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3d262508df71f7ff90d6b24766b2645942c0aeda1c113f13475744028417c224'),
  ('cpiuris2025::bb4af496cbadd377111f1d781cccccc4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflito entre tratados e normas de direito interno', '## Conflito entre tratados e normas de direito interno

O Direito Internacional monista considera que as normas do direito interno não podem ser invocadas para justificar o inadimplemento de um tratado, exceto em casos de violação manifesta de norma de importância fundamental de um Estado.

### Conceitos
- **Convenção de Viena**: Tratado internacional que estabelece regras para a observância dos tratados
- **Direito Internacional monista**: Teoria que considera que as normas do direito interno não podem ser invocadas para justificar o inadimplemento de um tratado
- **Lex posterior derogat priori**: Princípio segundo o qual a lei mais recente derroga à lei anterior
- **Lex posterior generalis non derogat legi priori speciali**: Princípio que afirma que a lei mais recente geral não derroga à lei especial anterior
- **Jus cogens**: Norma de direito internacional que não pode ser derogada por tratado ou lei

### Referências legais
- Art. 27 da Convenção de Viena

### Jurisprudência
- RE 123456
- Tema repetitivo: Conflito entre tratados e normas de direito interno

### Dicas de prova
- Entenda a distinção entre lex posterior derogat priori e lex posterior generalis non derogat legi priori speciali
- Conheça o conceito de jus cogens e sua aplicação no Direito Internacional
- Aprenda a distinguir entre tratados de direitos humanos e tratados de comércio internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27 da Convenção de Viena"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conflito entre tratados e normas de direito interno"], "confidence": 0.8, "extracted_at": "2026-05-31T06:59:25.363679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=84", "doc_key": "bb4af496cbadd377111f1d781cccccc4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b1696e58eeb31e37792a4c047e7858a2ef280a6d1e6bcf205fc9a84516898bc0'),
  ('cpiuris2025::d64610bdc2477d845bd9da23671d245b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Controle de Constitucionalidade', '## Tratados Internacionais e Controle de Constitucionalidade

Resumo objetivo em 2-5 frases: Tratados internacionais de direitos humanos anteriores à EC n° 45/04 têm status supralegal e podem ser objeto de controle de constitucionalidade. Tratados ratificados nos termos do art. 5º, § 3º, da Constituição têm força equivalente às emendas constitucionais.

### Conceitos
- **status supralegal**: Tratado com eficácia paralisante que retira a validade do restante da legislação ordinária
- **controle de constitucionalidade**: Ação de controle exercida sobre tratados internacionais para garantir a conformidade com a Constituição
- **bloco de constitucionalidade**: Conjunto de normas que integram o ordenamento jurídico brasileiro e são objeto de controle de constitucionalidade

### Referências legais
- Art. 5º, § 3º da Constituição
- EC n° 45/04

### Jurisprudência
- RE 349.703

### Dicas de prova
- Entenda a diferença entre tratados internacionais de direitos humanos anteriores e ratificados.
- Conheça o conceito de status supralegal e seu impacto no controle de constitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 3º da Constituição", "EC n° 45/04"], "jurisprudence": ["RE 349.703"], "confidence": 0.8, "extracted_at": "2026-05-31T07:00:31.494064+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=84", "doc_key": "d64610bdc2477d845bd9da23671d245b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7e4bf28bc58fc7c6ed38def564c8aef0dc90b6a70335ba5dd57ea5ad58b1800f'),
  ('cpiuris2025::8084faec92a0ba215ddade71f39d097f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais Tributários', '## Tratados Internacionais Tributários

O critério para a aplicação de tratados internacionais tributários é a especialidade, não o hierárquico. Os tratados geram um ''efeito negativo'' limitando as pretensões tributárias dos Estados.

### Conceitos
- **Efeito negativo**: Limitação das pretensões tributárias dos Estados
- **Specialidade**: Critério para a aplicação de tratados internacionais tributários
- **Interpretação como lei especial**: Tratados sobre matéria previdenciária são interpretados como lei especial

### Referências legais
- Art. 85-A da Lei n.º 8.212/1991
- Art. 98 do CTN
- Decreto 72.542/73
- Decreto 75.106/74
- Decreto 85.051/80

### Jurisprudência
- RESP 1.161.467-RS
- Tema repetitivo: Tratados Internacionais Tributários prevalecem sobre normas de Direito Interno

### Dicas de prova
- Distinção entre efeito negativo e especialidade
- Interpretação como lei especial em tratados internacionais tributários
- Consequências da denúncia do tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direitos Internacional", "legal_refs": ["Art. 85-A da Lei n.º 8.212/1991", "Art. 98 do CTN", "Decreto 72.542/73", "Decreto 75.106/74", "Decreto 85.051/80"], "jurisprudence": ["RESP 1.161.467-RS", "Tema repetitivo: Tratados Internacionais Tributários prevalecem sobre normas de Direito Interno"], "confidence": 0.8, "extracted_at": "2026-05-31T07:00:59.839412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=85", "doc_key": "8084faec92a0ba215ddade71f39d097f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f1e842a7ec0f21d331f829aac282607ff815cbb1b3b888f6f3a9c71caea83907'),
  ('cpiuris2025::bfdbd6f260a027fc2060cb1c51ffb1e3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tributação de empresas estrangeiras', '## Tributação de empresas estrangeiras

A sistemática adotada pela legislação fiscal nacional pode ferir os Pactos Internacionais Tributários e infringir o princípio da boa-fé nas relações exteriores.

### Conceitos
- **Pactos Internacionais Tributários**: Acordos internacionais que estabelecem regras para a tributação de empresas estrangeiras
- **Princípio da boa-fé nas relações exteriores**: O dever de agir com honestidade e justiça em relações internacionais
- **Regra da especialidade**: Sistema que prioriza a norma internacional sobre a norma nacional
- **Lex specialis derrogat generalis**: Princípio que prevê que uma norma mais específica deroga a uma norma mais geral

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- REsp 1325709/RJ
