  ('cpiuris2025::967bb1b66d0ca16028134f172735d5df', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tributação de produtos estrangeiros', '## Tributação de produtos estrangeiros

A tributação de produtos estrangeiros é regida pela norma internacional, exceto em casos específicos previstos nas Convenções. O Brasil é parte do Acordo Geral sobre Tarifas e Comércio (GATT), que estabelece a equivalência de tratamento entre produtos importados e similares nacionais.

### Conceitos
- **Tributação de produtos estrangeiros**: Regulada pela norma internacional, exceto em casos específicos previstos nas Convenções
- **GATT**: Acordo Geral sobre Tarifas e Comércio
- **Tratamento nacional**: Regra do GATT que estabelece a equivalência de tratamento entre produtos importados e similares nacionais
- **Isenção tributária**: Concessão legal para evitar a incidência de impostos sobre certas mercadorias estrangeiras

### Referências legais
- Art. 152 da Constituição Brasileira
- Art. 111 do Código Tributário Nacional (CTN)
- REsp. 1161467/RS
- REsp. 460.165
- Súmula 434/STJ

### Jurisprudência
- REsp. 434.703/SP
- REsp. 460.165
- REsp. 1161467/RS

### Dicas de prova
- Entenda a aplicabilidade da norma internacional em relação à tributação de produtos estrangeiros.
