  ('cpiuris2025::6da75c379d233f6ef3114affd8eef78a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Status das Convenções Internacionais no Brasil', '## Status das Convenções Internacionais no Brasil

As convenções internacionais adotadas pelo Brasil podem ter status constitucional se aprovadas pelo processo legislativo previsto para a votação de emendas à CF, e possuem estatuto de lei complementar, exceto em casos específicos onde têm status supralegal.

### Conceitos
- **Convenção sobre Privilégios e Imunidades das Nações Unidas**: tem status supralegal
- **Lei Complementar**: estatuto de tratados internacionais aprovados pelo Congresso Nacional
- **Norma Supralegal**: aplicação limitada à ausência de norma regulamentadora
- **Status Constitucional**: aprovado pelo processo legislativo previsto para a votação de emendas à CF

### Referências legais
- Art. 5º, § 2º, CF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre status das Convenções Internacionais no Brasil

### Dicas de prova
- Entenda a diferença entre norma supralegal e lei complementar
- Conheça o processo legislativo previsto para a votação de emendas à CF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 2º, CF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre status das Convenções Internacionais no Brasil"], "confidence": 0.8, "extracted_at": "2026-05-31T07:04:23.643315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=87", "doc_key": "6da75c379d233f6ef3114affd8eef78a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6ec72e43e2c4bc01f8606c3a49bd337d15759cad3d9f3e78c4649246230329ed'),
  ('cpiuris2025::8b9b93a92214867fd50d46826ee40ff7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Status supralegal de normas constitucionais', '## Status supralegal de normas constitucionais

A partir de 2008, o STF considera II como tendo status supralegal, mas subordinado à Constituição. III tem status supralegal e não pode reformar a Constituição.

### Conceitos
- **Status supralegal**: Conceito jurídico que indica uma norma que tem força de lei, mas é superior à Constituição
- **Subordinação à Constituição**: A norma supralegal está sujeita às limitações e restrições estabelecidas pela Constituição
- **Normas constitucionais**: Disposições da Constituição que têm força de lei e são aplicáveis a todos os cidadãos

### Referências legais
- Art. 5º, § 3º, da Constituição

### Jurisprudência
- Súmula 643/STF

### Dicas de prova
- Distinção entre II e III
- Importância do art. 5º, § 3º, da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 3º, da Constituição"], "jurisprudence": ["Súmula 643/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T07:04:40.326754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=87", "doc_key": "8b9b93a92214867fd50d46826ee40ff7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7f76a13585544440645a28fb1ab837efb1f93da4e1c4c2498bd1bd34bb94e207')
